window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0117", [{"word":"oscillation","ipa_uk":"/ˌɒsɪˈleɪʃən/","ipa_us":"/ˌɑːsəˈleɪʃən/","definition_zh":"摆动；振荡；波动；（数值或意见的）起伏摇摆","definition_en":"a regular movement back and forth around a central point, or a repeated rise and fall of a value or state","core_image":"钟摆越过最低点又荡回另一侧，一次一次在同一段弧线里来回","scene":"秋千在风口里前后摆个不停，横梁上的绳结磨出浅浅的痕迹。 The oscillation of the swing grew wider with every gust.","sceneCN":"这里 oscillation 指「物体围绕平衡位置来回摆动的运动」（第 1 个义项：围绕中心点作往复运动）；句意为秋千的摆幅随每一阵风变得更大。图中可辨识物件：秋千绳、横梁、摆动的弧线、被风压弯的草。","pos":[{"tag":"n.","zh":"摆动；振荡；波动；（意见的）摇摆"}],"collocations":[{"phrase":"damped oscillation","zh":"阻尼振荡"},{"phrase":"free oscillation","zh":"自由振荡"},{"phrase":"oscillation frequency","zh":"振荡频率"},{"phrase":"oscillation amplitude","zh":"摆幅；振荡幅度"},{"phrase":"periodic oscillation","zh":"周期性振荡"},{"phrase":"climate oscillation","zh":"气候振荡"}],"forms":[{"label":"复数","form":"oscillations"},{"label":"动词（摆动；振荡）","form":"oscillate"},{"label":"名词（振荡器）","form":"oscillator"},{"label":"形容词（振荡的）","form":"oscillatory"},{"label":"形容词（摆动的）","form":"oscillating"},{"label":"名词（示波器）","form":"oscilloscope"}],"derivatives":[{"word":"oscillate","pos":"v.","zh":"摆动；振荡；犹豫摇摆"},{"word":"oscillator","pos":"n.","zh":"振荡器；振子"},{"word":"oscillatory","pos":"adj.","zh":"振荡的；摆动的"},{"word":"oscilloscope","pos":"n.","zh":"示波器"},{"word":"oscillograph","pos":"n.","zh":"示波器记录仪"}],"senses":[{"no":"01","title":"Swinging to and fro","titleCN":"围绕平衡位置来回摆动","definition":"the act of moving back and forth regularly around a fixed point","definitionCN":"围绕一个固定点有规律地来回运动","example":"The oscillation of the swing grew wider with every gust.","exampleCN":"秋千的摆幅随着每一阵风变得更大。","why":"oscillation comes from Latin oscillare 'to swing', whose root oscillum named a small mask hung from a branch and rocked by the wind; the physical swing is the literal sense.","whyCN":"oscillation 来自拉丁 oscillare「摆动」，其词根 oscillum 指挂在树枝上随风摇晃的小面具；物理上的摆动就是它最字面的意思。"},{"no":"02","title":"One complete back-and-forth cycle","titleCN":"一个完整的往复周期","definition":"a single complete movement away from a point and back to it","definitionCN":"离开某点又回到该点的一次完整运动","example":"Each oscillation of the pendulum takes exactly one second.","exampleCN":"钟摆每完成一次摆动恰好用一秒。","why":"once the motion is seen as repeatable, one trip out and back becomes a countable unit.","whyCN":"一旦把这种运动看作可重复的，一次出去再回来就成了可数的单位。"},{"no":"03","title":"Electrical or signal oscillation","titleCN":"电流或信号的周期性振荡","definition":"a periodic change in voltage, current or signal strength","definitionCN":"电压、电流或信号强度的周期性变化","example":"The circuit sustains a steady oscillation at radio frequency.","exampleCN":"该电路在射电频率上维持稳定的振荡。","why":"electronics extended the swing image to quantities that rise and fall instead of bodies that move.","whyCN":"电子学把「摆动」的意象扩展到不是物体移动、而是数值升降的量上。"},{"no":"04","title":"Fluctuation of prices or numbers","titleCN":"数值与价格的上下波动","definition":"a repeated rise and fall in a measured value such as price or temperature","definitionCN":"价格或温度等被测数值反复上升与下降","example":"The oscillation of grain prices followed the seasonal harvest.","exampleCN":"粮价的波动随季节性收成而起落。","why":"the value swings around an average the way a pendulum swings around its lowest point.","whyCN":"数值围绕平均值上下摆动，正像钟摆围绕最低点摆动。"},{"no":"05","title":"Wavering of opinion","titleCN":"意见或情绪的摇摆不定","definition":"a state of alternating between two opinions or moods","definitionCN":"在两种意见或情绪之间来回转换的状态","example":"His oscillation between hope and doubt exhausted his friends.","exampleCN":"他在希望与怀疑之间来回摇摆，让朋友们疲惫不堪。","why":"the abstract sense keeps the shape of the swing: two poles, repeated travel between them.","whyCN":"抽象义保留了摆动的形状：两个极点，反复往返其间。"},{"no":"06","title":"Simple harmonic oscillation","titleCN":"简谐振动（物理术语）","definition":"a periodic motion in which the restoring force is proportional to the displacement","definitionCN":"回复力与位移成正比的周期运动","example":"A mass on an ideal spring undergoes simple harmonic oscillation.","exampleCN":"理想弹簧上的重物作简谐振动。","why":"physics gave the general swing a precise mathematical form, one defined by a restoring force.","whyCN":"物理学给一般的摆动一个精确的数学形式，由回复力来定义。"},{"no":"07","title":"Climate or ocean oscillation","titleCN":"气候或海洋系统的周期性振荡","definition":"a recurring shift in a large-scale climate or ocean pattern","definitionCN":"大尺度气候或海洋格局的周期性转变","example":"Forecasters track the oscillation of sea-surface temperatures across the Pacific.","exampleCN":"预报员追踪太平洋海表温度的振荡。","why":"large systems repeat a slow rise and fall, so the same word was borrowed for them.","whyCN":"大型系统重复一种缓慢的升降，于是借用了同一个词。"},{"no":"08","title":"Amplitude of a swing","titleCN":"摆幅；一次摆动的幅度","definition":"the extent of a single swinging movement from one extreme to the other","definitionCN":"一次摆动从一个极端到另一个极端所及的范围","example":"Damping reduced the oscillation to a few centimetres.","exampleCN":"阻尼使摆幅减小到几厘米。","why":"the noun also names the size of the movement, because the whole swing is what is observed.","whyCN":"这个名词也可指运动的幅度，因为被观察到的正是整段摆动。"},{"no":"09","title":"Alternation between extremes","titleCN":"在两个极端之间交替","definition":"a repeated alternation between two opposite conditions","definitionCN":"在两种相反状态之间反复交替","example":"The novel's oscillation between comedy and grief unsettles the reader.","exampleCN":"小说在喜剧与悲恸之间来回切换，令读者不安。","why":"the most abstract sense drops the physical pendulum and keeps only the alternation.","whyCN":"最抽象的义项丢掉了实体的钟摆，只留下交替本身。"}],"etymology":{"intro":{"en":"Oscillation comes from Latin oscillatio, from oscillare 'to swing'. The root oscillum was a small mask hung from a tree and rocked by the wind, so the word began as a picture of something swaying in the breeze. Dates are approximate.","cn":"oscillation 来自拉丁 oscillatio，出自 oscillare「摆动」。词根 oscillum 指挂在树上随风摇晃的小面具，因此这个词最初画的正是风中摇摆之物。年代均为约数。"},"items":[{"era":"LATIN OSCILLUM","en":"Oscillum was a small mask, especially of Bacchus, hung from a branch in Roman gardens and swung in the wind; it is a diminutive of os 'mouth, face'.","cn":"oscillum 是一种小面具，多为酒神面具，挂在罗马园中树枝上随风摆动；它是 os「嘴、脸」的指小形式。"},{"era":"LATIN OSCILLARE","en":"From the noun came oscillare 'to swing, to move to and fro', the verb that supplies English oscillation.","cn":"由该名词产生动词 oscillare「摆动、来回移动」，英语 oscillation 即由此而来。"},{"era":"ENGLISH ENTRY","en":"The noun entered English in the seventeenth century through the scientific Latin of mechanics; the earliest uses describe pendulums and balances.","cn":"这个名词在十七世纪经力学的科学拉丁语进入英语，最早的用法描述钟摆与天平。"},{"era":"PHYSICS SENSE","en":"In the nineteenth century oscillation was fixed as the technical term for any repeated change around an equilibrium, including electric current.","cn":"到十九世纪，oscillation 固定为技术术语，指围绕平衡状态的任何重复变化，包括电流。"},{"era":"ABSTRACT SENSE","en":"The figurative use for wavering opinions and recurring climate patterns is later and secondary, built directly on the visible swing.","cn":"用于意见摇摆与气候周期的那层比喻义出现较晚，是次要引申，直接建立在可见的摆动之上。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of oscillum is not settled, and the exact first date of the English noun varies between dictionaries, so any older Indo-European form offered for it is a reconstruction.","cn":"来源不确定：oscillum 在拉丁语之前的来源未有定论，英语名词的确切首见年代各家词典不一，凡为其给出的更早印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds members of the same oscill- family that are easily swapped by mistake; group two holds near neighbours that describe repeated movement with a different focus.","cn":"第一组是同出 oscill- 词族、极易被误换的词；第二组是描述反复运动、但侧重不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"oscillate","ipa":"/ˈɒsɪleɪt/","tag":"the verb","definition":"The verb naming the action itself: a body oscillates, while the noun oscillation names the action or one cycle of it.","definitionCN":"指动作本身的动词：物体摆动用动词，名词则指这个动作或其中一次周期。"},{"word":"oscillator","ipa":"/ˈɒsɪleɪtə/","tag":"the device","definition":"The instrument or circuit that produces oscillation; it is a thing, not the movement.","definitionCN":"产生振荡的器件或电路；它指实物，不指运动本身。"},{"word":"oscillatory","ipa":"/ˌɒsɪləˈtɔːri/","tag":"the adjective","definition":"An adjective meaning 'of or marked by oscillation', used to describe motion or behaviour.","definitionCN":"意为「振荡的、摆动的」形容词，用来描述运动或行为。"},{"word":"oscilloscope","ipa":"/əˈsɪləskəʊp/","tag":"compound instrument","definition":"A compound of oscill- plus -scope 'viewing instrument': a device that displays a signal's waveform, not a synonym of the movement.","definitionCN":"由 oscill- 加 -scope「观察仪器」构成的复合词：显示信号波形的装置，并非运动的同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vibration","ipa":"/vaɪˈbreɪʃən/","tag":"rapid small movement","definition":"A rapid, often tiny shaking of an object or medium; oscillation is the broader term for any regular back-and-forth motion.","definitionCN":"物体或介质快速而常很细微的颤动；oscillation 是更宽泛的「有规律往复运动」。"},{"word":"fluctuation","ipa":"/ˌflʌktʃuˈeɪʃən/","tag":"rise and fall of values","definition":"An irregular rise and fall in a quantity; oscillation usually implies a repeating rhythm rather than mere unevenness.","definitionCN":"数量不规则地升降；oscillation 通常含有重复节律，而不只是忽高忽低。"},{"word":"swing","ipa":"/swɪŋ/","tag":"everyday word","definition":"The plain everyday word for a body moving back and forth, as on a swing; oscillation is its technical counterpart.","definitionCN":"指物体来回移动的日常词，如荡秋千；oscillation 是它技术化的对应词。"},{"word":"wavering","ipa":"/ˈweɪvərɪŋ/","tag":"unsteady choice","definition":"Hesitation between choices or feelings; the abstract oscillation is close, but wavering stresses indecision rather than rhythm.","definitionCN":"在选择或情感之间犹豫；抽象义的 oscillation 与之接近，但 wavering 更强调举棋不定而非节律。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"oscill- 'swing' + -ation (action noun): the act of swinging.","cn":"oscill-「摆动」+ -ation（动作名词）：摆动的动作。"},{"en":"The family runs oscillation, oscillate, oscillator, oscillatory, oscilloscope.","cn":"同族词包括 oscillation、oscillate、oscillator、oscillatory、oscilloscope。"},{"en":"Fixed phrases mark the technical sense: damped oscillation, free oscillation, oscillation frequency.","cn":"固定搭配标出技术义：阻尼振荡、自由振荡、振荡频率。"},{"en":"Physics pairs it with amplitude and period, the size and the duration of one swing.","cn":"物理学把它与 amplitude（幅度）和 period（周期）配对，即一次摆动的大小与时长。"},{"en":"The same root appears in oscilloscope, an instrument that draws a signal's swing on a screen.","cn":"同一词根出现在 oscilloscope 中，那是把信号的摆动画在屏幕上的仪器。"}],"abstract":[{"en":"Picture a child on a swing who never quite stops, so the arc is drawn again and again in the air.","cn":"想象秋千上的孩子始终没停，弧线在空气里一遍遍被画出。"},{"en":"Picture a price on a tag that climbs and drops while the shelf stays still.","cn":"想象价签上的数字自升自落，而货架本身不动。"},{"en":"Picture an argument that keeps returning to its starting point without resolving.","cn":"想象一场争论反复回到起点，始终没有结论。"}]},"examples":[{"en":"The oscillation of the bridge was measured after the windstorm.","cn":"风暴之后人们测量了桥的摆动。"},{"en":"The oscillator holds a steady oscillation for the whole experiment.","cn":"振荡器在整个实验中维持稳定的振荡。"},{"en":"Public opinion showed a clear oscillation between the two camps.","cn":"公众意见在两个阵营之间明显来回摇摆。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「oscill（摆动）+ ation（动作）」——来回摆动的这件事本身 → 摆动、振荡、波动","word":"oscillation"},"root":"拉丁 oscillatio「摆动」来自 oscillare「来回摆动」，其名词词根 oscillum 指挂在树枝上随风摇晃的小面具，是 os「嘴、脸」的指小形式；oscillum 在拉丁语之前的来源不确定，不作臆测。","sensesIntro":{"en":"Nine senses follow one arc: a body swings around a fixed point, the swing becomes a countable cycle, and the same shape is then lent to currents, prices, opinions, physical models, ocean patterns and finally to pure alternation.","cn":"九个义项沿同一条弧线展开：物体绕定点摆动，摆动成为可数的周期，同一形状再依次借给电流、价格、意见、物理模型、海洋格局，最后落到纯粹的交替。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pendulum crossing its lowest point and rising again on the other side, over and over.","cn":"核心意象：钟摆越过最低点，又在另一侧升回原处，一次又一次。"},"chain":["SWING","ONECYCLE","SIGNAL","FLUCTUATE","WAVER","ALTERNATE"],"branches":[{"senses":"S1 · S2","en":"PHYSICAL SWING: the literal motion and its countable unit.","cn":"实体摆动：字面上的运动及其可数单位。"},{"senses":"S3 · S6","en":"TECHNICAL MODEL: current and the harmonic equation inherit the same back-and-forth form.","cn":"技术模型：电流与简谐方程继承了同一种往复形式。"},{"senses":"S4 · S7","en":"MEASURED RHYTHM: prices and ocean temperatures rise and fall around an average.","cn":"可测节律：价格与海温围绕平均值升降。"},{"senses":"S8","en":"AMPLITUDE: the swing is also measured by how far it reaches.","cn":"幅度：摆动的远近本身也成为被测量的对象。"},{"senses":"S5 · S9","en":"ABSTRACT ARC: opinions and conditions alternate between two poles.","cn":"抽象弧线：意见与状态在两个极点之间交替。"}]},"affixes":{"intro":{"en":"Oscillation is a Latin action noun built on a verb whose root names a swinging mask, so the morphology can be read morpheme by morpheme.","cn":"oscillation 是拉丁动作名词，建立在词根意为「摆动面具」的动词上，因此可以按语素逐个读出。"},"latinIntro":{"en":"Latin oscillum and oscillare give oscillation, oscillate, oscillator and oscillatory; the combining form oscillo- also builds instrument names such as oscilloscope.","cn":"拉丁 oscillum 与 oscillare 衍生 oscillation、oscillate、oscillator 与 oscillatory；组合形式 oscillo- 还构成 oscilloscope 一类仪器名。"},"items":[{"word":"oscill-","structure":"oscillum (Latin noun, 'small mask')","meaning":"a small face or mask hung up to swing","meaningCN":"挂在风中摆动的小面具","example":"A Roman garden hung an oscillum from a branch.","exampleCN":"罗马人的园子里把小面具挂在树枝上。"},{"word":"oscillare","structure":"oscillare, oscillavi, oscillatum (Latin verb, first conjugation)","meaning":"to swing, move to and fro","meaningCN":"摆动；来回移动","example":"The branch oscillated in the wind.","exampleCN":"树枝在风中摆动。"},{"word":"oscillation","structure":"oscillare + -atio (action noun)","meaning":"a swinging; a wavering","meaningCN":"摆动；摇摆","example":"The oscillation of the lamp lasted all night.","exampleCN":"灯的摆动持续了一整夜。"},{"word":"oscillate","structure":"oscillare + -ate (English verb ending)","meaning":"to swing back and forth","meaningCN":"来回摆动","example":"The needle oscillates around zero.","exampleCN":"指针围绕零位摆动。"},{"word":"oscillator","structure":"oscillate + -or (one that acts)","meaning":"a device that produces oscillation","meaningCN":"产生振荡的装置","example":"The oscillator drives the antenna.","exampleCN":"振荡器驱动天线。"},{"word":"oscillatory","structure":"oscillate + -ory (pertaining to)","meaning":"relating to or marked by oscillation","meaningCN":"与振荡有关的；摆动的","example":"The system shows oscillatory behaviour.","exampleCN":"该系统表现出振荡行为。"},{"word":"oscilloscope","structure":"oscillo- (combining form) + -scope (instrument for viewing)","meaning":"an instrument that displays a waveform","meaningCN":"显示波形的仪器","example":"The technician read the pulse on the oscilloscope.","exampleCN":"技术员在示波器上读取脉冲。"},{"word":"oscillograph","structure":"oscillo- + -graph (instrument that writes)","meaning":"an instrument that records oscillations","meaningCN":"记录振荡的仪器","example":"The oscillograph traced the tremor on paper.","exampleCN":"示波记录仪把震动描在纸上。"},{"word":"oscillating","structure":"oscillate + -ing (participial adjective)","meaning":"that is swinging or vibrating","meaningCN":"正在摆动或振荡的","example":"An oscillating fan cooled the room.","exampleCN":"一台摇头风扇给房间降温。"}],"latinEntries":[{"word":"oscillum","structure":"oscillum, oscilli (n., second declension)","meaning":"a small mask hung as a swing","meaningCN":"挂作摆动物的小面具"},{"word":"oscillare","structure":"oscillare, oscillavi, oscillatum (verb, first conjugation)","meaning":"to swing, move to and fro","meaningCN":"摆动；来回移动"},{"word":"oscillatio","structure":"oscillatio, oscillationis (f., third declension)","meaning":"a swinging, oscillation","meaningCN":"摆动；振荡"}]}},{"word":"oscillate","ipa_uk":"/ˈɒsɪleɪt/","ipa_us":"/ˈɑːsəleɪt/","definition_zh":"摆动；振荡；（数值）上下波动；犹豫不决","definition_en":"to move back and forth around a point, or to keep changing between two levels or choices","core_image":"摆锤在两点之间来回划过，每一趟都几乎重复上一趟","scene":"老式挂钟的摆锤在暗处来回划过，滴答声匀得让人犯困。 The brass pendulum continued to oscillate long after midnight.","sceneCN":"这里 oscillate 指「物体绕平衡位置来回运动」（第 1 个义项：往复摆动）；句意为黄铜摆锤在午夜之后仍持续摆动。图中可辨识物件：挂钟、黄铜摆锤、摆杆、暗处的刻度。","pos":[{"tag":"vi.","zh":"摆动；振荡；（数值、意见）来回变动"}],"collocations":[{"phrase":"oscillate between two extremes","zh":"在两个极端之间摇摆"},{"phrase":"oscillate around a mean","zh":"围绕平均值波动"},{"phrase":"oscillate rapidly","zh":"快速振荡"},{"phrase":"oscillate in phase","zh":"同相振荡"},{"phrase":"oscillate with a frequency","zh":"以某一频率振荡"}],"forms":[{"label":"三单（he/she/it）","form":"oscillates"},{"label":"过去式","form":"oscillated"},{"label":"过去分词","form":"oscillated"},{"label":"现在分词","form":"oscillating"},{"label":"名词（摆动；振荡）","form":"oscillation"},{"label":"名词（振荡器）","form":"oscillator"},{"label":"形容词（振荡的）","form":"oscillatory"}],"derivatives":[{"word":"oscillation","pos":"n.","zh":"摆动；振荡；波动"},{"word":"oscillator","pos":"n.","zh":"振荡器；振子"},{"word":"oscillatory","pos":"adj.","zh":"振荡的；摆动的"},{"word":"oscilloscope","pos":"n.","zh":"示波器"},{"word":"oscillograph","pos":"n.","zh":"振荡记录仪"}],"senses":[{"no":"01","title":"Swing around a fixed point","titleCN":"绕固定点来回摆动","definition":"to move regularly back and forth around a central point","definitionCN":"围绕一个中心点有规律地来回运动","example":"The brass pendulum continued to oscillate long after midnight.","exampleCN":"黄铜摆锤在午夜之后仍继续摆动。","why":"the verb comes straight from Latin oscillare 'to swing', so the physical motion is the oldest layer of meaning.","whyCN":"这个动词直接来自拉丁 oscillare「摆动」，因此实体运动是最早的一层意义。"},{"no":"02","title":"Travel between two limits","titleCN":"在两个界限之间往返","definition":"to keep moving from one boundary to the other and back","definitionCN":"不断从一侧边界移到另一侧再返回","example":"The needle oscillates between the two red marks.","exampleCN":"指针在两个红色标记之间来回摆动。","why":"a swing is bounded by its two extremes, so the verb naturally names repeated travel between limits.","whyCN":"摆动被两个极端所限定，因此这个动词自然指在两个界限之间反复往返。"},{"no":"03","title":"Fluctuate in value","titleCN":"数值上下波动","definition":"to rise and fall repeatedly around an average value","definitionCN":"围绕平均值反复上升与下降","example":"Prices oscillate with the rhythm of the harvest.","exampleCN":"价格随收成的节律上下波动。","why":"a quantity that rises and falls traces the same arc as a pendulum, so the verb was extended from bodies to numbers.","whyCN":"数值的升降画出与钟摆相同的弧线，于是这个动词从物体扩展到数字。"},{"no":"04","title":"Waver between choices","titleCN":"在意见与选择之间犹豫","definition":"to keep changing from one opinion or decision to another","definitionCN":"不断从一种意见或决定转向另一种","example":"He oscillated for weeks between accepting and refusing the offer.","exampleCN":"他在接受与拒绝这份提议之间犹豫了好几周。","why":"the two options act like the two ends of a swing, and the mind keeps travelling between them.","whyCN":"两个选项就像摆动的两端，心思在不断往返其间。"},{"no":"05","title":"Reverse direction of current","titleCN":"电流方向交替变化","definition":"to change direction periodically, as an alternating current does","definitionCN":"像交流电那样周期性地改变方向","example":"The current oscillates sixty times a second in the mains supply.","exampleCN":"市电中的电流每秒交替六十次。","why":"electricity has no visible swing, but its direction reverses on a regular beat, which is the same abstract shape.","whyCN":"电没有可见的摆动，但它的方向按固定节拍反转，这正是同一种抽象形状。"},{"no":"06","title":"Vibrate at a frequency","titleCN":"以某一频率振动","definition":"to vibrate with a regular frequency, as a physical system does","definitionCN":"像物理系统那样以有规律的频率振动","example":"The molecule oscillates at frequencies that identify it.","exampleCN":"分子以可标识自身的频率振动。","why":"physics replaced the visible arc with a measurable frequency while keeping the notion of repeated motion.","whyCN":"物理学用可测的频率取代可见的弧线，但保留了重复运动的观念。"},{"no":"07","title":"Alternate between two states","titleCN":"在两种状态之间交替","definition":"to switch repeatedly between two conditions or regimes","definitionCN":"在两种条件或状态之间反复切换","example":"The climate system oscillates between warm and cold phases.","exampleCN":"气候系统在暖相位与冷相位之间交替。","why":"systems with two stable states flip between them on a slow cycle, which speakers describe with the swing verb.","whyCN":"具有两个稳定状态的系统按缓慢周期在两者间翻转，说话者便用这个「摆动」动词来描述。"},{"no":"08","title":"Sweep back and forth","titleCN":"（风扇、光束）左右横扫","definition":"to sweep repeatedly through an arc, as a fan head or a beam does","definitionCN":"像风扇头或光束那样沿弧线反复扫过","example":"The fan oscillates so the whole room gets the breeze.","exampleCN":"风扇左右摇头，好让整个房间都能吹到风。","why":"the modern appliance sense is a visible swing of a whole object rather than a small bob.","whyCN":"现代电器义是整个物体可见的摆动，而不是小摆锤的晃动。"}],"etymology":{"intro":{"en":"Oscillate is the English verb built on Latin oscillare 'to swing', itself derived from oscillum, a small mask hung from a branch to move in the wind. Dates are approximate.","cn":"oscillate 是建立在拉丁 oscillare「摆动」之上的英语动词，而 oscillare 又出自 oscillum，即挂在树枝上随风摆动的小面具。年代均为约数。"},"items":[{"era":"LATIN OSCILLUM","en":"Oscillum named a small mask, often of Bacchus, hung in Roman gardens so that the wind would move it; it is a diminutive of os 'mouth, face'.","cn":"oscillum 指挂在罗马园中、让风把它吹动的小面具，多为酒神面具；它是 os「嘴、脸」的指小形式。"},{"era":"LATIN OSCILLARE","en":"From the noun came oscillare 'to swing, to move to and fro'. The verb describes the mask's motion before it describes a pendulum.","cn":"由该名词产生 oscillare「摆动、来回移动」。这个动词先描述面具的运动，后来才用于钟摆。"},{"era":"ENGLISH VERB","en":"English took the verb in the early eighteenth century, at first in learned writing about pendulums and balances.","cn":"英语在十八世纪初引入这个动词，最初出现在关于钟摆与天平的学术文字里。"},{"era":"SCIENTIFIC EXTENSION","en":"Nineteenth-century physics and electrical engineering extended oscillate to currents, molecules and any quantity that changes periodically.","cn":"十九世纪的物理学与电气工程把 oscillate 扩展到电流、分子以及任何周期性变化的量。"},{"era":"FIGURATIVE USE","en":"The sense of wavering between choices grew from the visible back-and-forth movement and is recorded later than the mechanical sense.","cn":"在选项之间犹豫的义项由可见的往返运动引申而来，书证晚于力学义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of oscillum is unsettled and the exact first English citation is not fixed, so any proposed older Indo-European form is a reconstruction.","cn":"来源不确定：oscillum 在拉丁语之前的来源未有定论，英语最早书证的确切年代也未固定，凡提出的更早印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the verb from its own noun and instrument forms; group two holds near synonyms that differ in how regular or how visible the movement is.","cn":"第一组把这个动词与它自己的名词、工具形式分开；第二组是近义词，差别在于运动是否规律、是否可见。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"oscillation","ipa":"/ˌɒsɪˈleɪʃən/","tag":"the noun","definition":"The noun names the movement or one cycle of it, while oscillate is the act performed by a body.","definitionCN":"名词指这个运动或其中一次周期，而 oscillate 是物体执行的动作。"},{"word":"oscillator","ipa":"/ˈɒsɪleɪtə/","tag":"the device","definition":"A device or circuit that produces oscillation; it cannot replace the verb in a sentence.","definitionCN":"产生振荡的装置或电路，不能在句中替代动词。"},{"word":"oscillatory","ipa":"/ˌɒsɪləˈtɔːri/","tag":"the adjective","definition":"An adjective describing something that oscillates; it modifies a noun rather than naming an action.","definitionCN":"描述会摆动的某物的形容词，修饰名词而非指动作。"},{"word":"oscilloscope","ipa":"/əˈsɪləskəʊp/","tag":"instrument compound","definition":"A viewing instrument built from oscillo- plus -scope; it displays a waveform but is not a form of the verb.","definitionCN":"由 oscillo- 加 -scope 构成的观察仪器；它显示波形，但不是动词的变形。"}]},{"heading":"NEAR MEANING","entries":[{"word":"swing","ipa":"/swɪŋ/","tag":"everyday motion","definition":"The plain word for moving back and forth, often a large visible arc; oscillate is the technical and regular version.","definitionCN":"指来回移动的日常词，常指大幅可见的弧线；oscillate 是其技术化、规律化的版本。"},{"word":"vibrate","ipa":"/vaɪˈbreɪt/","tag":"rapid tiny motion","definition":"To shake with very rapid small movements; oscillate can be slow and wide, so it is not limited to vibration.","definitionCN":"以极快的小幅动作颤动；oscillate 可以缓慢而幅度大，因此并不限于颤动。"},{"word":"fluctuate","ipa":"/ˈflʌktʃueɪt/","tag":"values only","definition":"Used of numbers, prices or levels that rise and fall unevenly; it does not describe a physical body.","definitionCN":"用于数字、价格或水平的不规则升降，不描述实体物体。"},{"word":"waver","ipa":"/ˈweɪvə/","tag":"indecision","definition":"To hesitate between choices; this is the human sense of oscillate without the mechanical regularity.","definitionCN":"在选择之间犹豫；这是 oscillate 的人事义，但缺少机械般的规律性。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"oscill- 'swing' + -ate (verb ending): to perform the swinging.","cn":"oscill-「摆动」+ -ate（动词词尾）：执行摆动这个动作。"},{"en":"The family runs oscillate, oscillation, oscillator, oscillatory, oscilloscope.","cn":"同族词包括 oscillate、oscillation、oscillator、oscillatory、oscilloscope。"},{"en":"Fixed patterns mark the abstract senses: oscillate between, oscillate around, oscillate with a frequency.","cn":"固定搭配标出抽象义：在两者间摇摆、围绕某值波动、以某频率振荡。"},{"en":"The verb pairs with pendulum, needle and fan, three objects whose motion is easy to see.","cn":"这个动词常与 pendulum（钟摆）、needle（指针）、fan（风扇）搭配，三者运动都易看见。"},{"en":"Physics turns the verb into a measurement: a system oscillates at so many hertz.","cn":"物理学把这个动词变成测量：系统以多少赫兹振荡。"}],"abstract":[{"en":"Picture a grandfather clock whose pendulum never stops, even when the house is asleep.","cn":"想象一座落地钟，屋里人都睡了，摆锤仍不停。"},{"en":"Picture a shopper who picks up one brand and puts it back, again and again.","cn":"想象顾客拿起一个牌子又放回，反复不停。"},{"en":"Picture a fan head sweeping the room while the fan itself stays put.","cn":"想象风扇头扫过房间，而风扇底座不动。"}]},"examples":[{"en":"The pendulum oscillates with a period of two seconds.","cn":"这个钟摆以两秒的周期摆动。"},{"en":"Temperature oscillates between day and night in the desert.","cn":"沙漠里的气温在昼夜之间上下波动。"},{"en":"She oscillated between anger and relief for the rest of the day.","cn":"那天余下的时间里，她在愤怒与宽慰之间来回摇摆。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「oscill（摆动）+ ate（动词）」——让某物来回摆起来 → 摆动、振荡、摇摆不定","word":"oscillate"},"root":"拉丁 oscillare「来回摆动，第一变位」来自名词 oscillum「挂起随风摆动的小面具」，oscillum 是 os「嘴、脸」的指小形式；其更早来源不确定，不作臆测。","sensesIntro":{"en":"Eight senses follow one motion: a body swings, crosses between two limits, and then the same shape is applied to numbers, decisions, currents, vibrations, systems and finally to a fan sweeping a room.","cn":"八个义项沿同一个动作展开：物体摆动，在两个界限间往返，同一形状再依次用于数值、决定、电流、振动、系统，最后用于扫过房间的风扇。"},"semanticMap":{"core":{"en":"CORE IMAGE: a weighted arm passing the same two points again and again.","cn":"核心意象：一根带重物的摆杆一次又一次经过相同的两点。"},"chain":["SWING","BETWEEN LIMITS","FLUCTUATE","WAVER","ALTERNATE CURRENT","VIBRATE"],"branches":[{"senses":"S1 · S2","en":"VISIBLE SWING: a body and its two boundaries.","cn":"可见摆动：一个物体及其两侧界限。"},{"senses":"S3 · S7","en":"MEASURED CHANGE: values and systems rise and fall on a rhythm.","cn":"可测变化：数值与系统按节律升降。"},{"senses":"S4","en":"HUMAN WAIVER: the two limits become two choices.","cn":"人的犹豫：两个界限变成两个选项。"},{"senses":"S5 · S6","en":"PHYSICAL ALTERNATION: current reverses and matter vibrates at a frequency.","cn":"物理交替：电流反向，物质按频率振动。"},{"senses":"S8","en":"APPLIANCE SWEEP: a whole object traces the arc instead of a small bob.","cn":"电器横扫：画出弧线的是整个物体，而非小摆锤。"}]},"affixes":{"intro":{"en":"Oscillate is a Latin-derived verb whose root names a swinging mask; the same root yields a full noun, adjective and instrument family.","cn":"oscillate 是源自拉丁语的动词，其词根指摆动的面具；同一词根衍生出完整的名词、形容词与仪器词族。"},"latinIntro":{"en":"Latin oscillum and oscillare supply oscillate, oscillation, oscillator and oscillatory; oscillo- also combines with -scope and -graph for instruments.","cn":"拉丁 oscillum 与 oscillare 提供 oscillate、oscillation、oscillator 与 oscillatory；oscillo- 还与 -scope、-graph 组合成仪器名。"},"items":[{"word":"oscill-","structure":"oscillum (Latin noun, 'small mask')","meaning":"a small face hung up to swing","meaningCN":"挂起来摆动的小面具","example":"The mask swung from the branch all afternoon.","exampleCN":"面具在树枝上摆了一下午。"},{"word":"oscillare","structure":"oscillare, oscillavi, oscillatum (Latin verb, first conjugation)","meaning":"to swing, move to and fro","meaningCN":"摆动；来回移动","example":"The rope oscillated in the wind.","exampleCN":"绳子在风中来回摆动。"},{"word":"oscillate","structure":"oscillare + -ate (English verb ending)","meaning":"to swing back and forth","meaningCN":"来回摆动","example":"The pointer oscillates around zero.","exampleCN":"指针围绕零位摆动。"},{"word":"oscillation","structure":"oscillate + -ion (action noun)","meaning":"the act or one cycle of swinging","meaningCN":"摆动这一动作或一次周期","example":"One oscillation took exactly a second.","exampleCN":"一次摆动恰好用了一秒。"},{"word":"oscillator","structure":"oscillate + -or (one that acts)","meaning":"a device that produces oscillation","meaningCN":"产生振荡的装置","example":"The oscillator feeds the antenna.","exampleCN":"振荡器向天线馈送信号。"},{"word":"oscillatory","structure":"oscillate + -ory (pertaining to)","meaning":"marked by oscillation","meaningCN":"具有振荡特征的","example":"The motion is purely oscillatory.","exampleCN":"这一运动是纯振荡性的。"},{"word":"oscilloscope","structure":"oscillo- (combining form) + -scope (instrument for viewing)","meaning":"an instrument that displays a waveform","meaningCN":"显示波形的仪器","example":"The waveform filled the oscilloscope screen.","exampleCN":"波形占满了示波器屏幕。"},{"word":"oscillograph","structure":"oscillo- + -graph (instrument that writes)","meaning":"an instrument that records oscillation","meaningCN":"记录振荡的仪器","example":"The oscillograph recorded the tremor.","exampleCN":"振荡记录仪记下了这次震动。"},{"word":"oscillating","structure":"oscillate + -ing (participial adjective)","meaning":"currently swinging or vibrating","meaningCN":"正在摆动或振荡的","example":"An oscillating fan stood in the corner.","exampleCN":"角落里立着一台摇头风扇。"}],"latinEntries":[{"word":"oscillum","structure":"oscillum, oscilli (n., second declension)","meaning":"a small mask hung as a swing","meaningCN":"挂作摆动物的小面具"},{"word":"oscillare","structure":"oscillare, oscillavi, oscillatum (verb, first conjugation)","meaning":"to swing, move to and fro","meaningCN":"摆动；来回移动"},{"word":"oscillatio","structure":"oscillatio, oscillationis (f., third declension)","meaning":"a swinging, oscillation","meaningCN":"摆动；振荡"}]}},{"word":"turbulence","ipa_uk":"/ˈtɜːbjələns/","ipa_us":"/ˈtɜːrbjələns/","definition_zh":"湍流；乱流；气流颠簸；动荡与混乱","definition_en":"irregular, chaotic motion of a fluid or air, or a state of confusion and unrest","core_image":"河水撞上桥墩后翻起无规则的白色漩涡，原本平行的水纹全被打散","scene":"飞机落进云层后猛地一沉，餐车上的杯子滑到托盘边缘。 The seatbelt sign came on as the plane hit turbulence over the mountains.","sceneCN":"这里 turbulence 指「大气中不规则的扰动气流」（第 2 个义项：飞行中造成颠簸的乱流）；句意为飞机在山地上空遇到湍流时，安全带指示灯亮起。图中可辨识物件：安全带指示灯、杯子、餐车托盘、舷窗外的灰云。","pos":[{"tag":"n.","zh":"湍流；乱流；颠簸；动荡；混乱"}],"collocations":[{"phrase":"clear-air turbulence","zh":"晴空湍流"},{"phrase":"atmospheric turbulence","zh":"大气湍流"},{"phrase":"experience turbulence","zh":"遭遇颠簸"},{"phrase":"turbulence intensity","zh":"湍流强度"},{"phrase":"political turbulence","zh":"政治动荡"},{"phrase":"turbulence mixing","zh":"湍流混合"}],"forms":[{"label":"形容词（湍流的；动荡的）","form":"turbulent"},{"label":"副词（动荡地）","form":"turbulently"},{"label":"名词（浑浊；混浊度）","form":"turbidity"},{"label":"形容词（浑浊的）","form":"turbid"},{"label":"动词（扰乱）","form":"perturb"},{"label":"名词（扰动）","form":"perturbation"}],"derivatives":[{"word":"turbulent","pos":"adj.","zh":"湍流的；动荡的；骚动的"},{"word":"turbulently","pos":"adv.","zh":"动荡地；翻涌地"},{"word":"turbid","pos":"adj.","zh":"浑浊的；混乱的"},{"word":"turbidity","pos":"n.","zh":"浑浊度；混浊"},{"word":"perturb","pos":"v.","zh":"扰乱；使不安"}],"senses":[{"no":"01","title":"Irregular fluid motion","titleCN":"流体不规则运动形成湍流","definition":"the chaotic, eddying motion of a fluid in which flow no longer stays smooth and layered","definitionCN":"流体失去平滑分层、出现混乱涡旋的运动状态","example":"The engineers studied turbulence behind the bridge pier.","exampleCN":"工程师研究桥墩后方形成的湍流。","why":"turbulence descends from Latin turba 'turmoil, crowd', so the word carries disorder from the start; a fluid in turbulence is a crowd of eddies.","whyCN":"turbulence 源自拉丁 turba「骚动、人群」，因此这个词从一开始就带着无序；处于湍流的流体正是一群涡旋。"},{"no":"02","title":"Bumpy air in flight","titleCN":"飞行中遇到的乱流颠簸","definition":"rough, uneven air that shakes an aircraft in flight","definitionCN":"使飞行中的飞机摇晃的粗糙、不均匀气流","example":"The seatbelt sign came on as the plane hit turbulence over the mountains.","exampleCN":"飞机在山地上空遇到湍流时，安全带指示灯亮起。","why":"the aviation sense applies the fluid meaning to air and to what passengers feel: sudden lifts and drops.","whyCN":"航空义把流体义用于空气，也用于乘客的感受：突然的抬升与下坠。"},{"no":"03","title":"Churning water","titleCN":"水流翻涌、白沫四散","definition":"violent, swirling movement of water that breaks its surface into foam","definitionCN":"水流剧烈回旋，把水面打成白沫","example":"Turbulence at the rapids flipped the small boat sideways.","exampleCN":"急流处的翻涌把小船掀得横了过来。","why":"water was the first visible place where the word's disorder could be watched, so it remains a common concrete use.","whyCN":"水是最早能看见这个词所指无序状态的地方，因此它一直是很常见的具体用法。"},{"no":"04","title":"Social or political unrest","titleCN":"社会或政治的动荡","definition":"a period of confusion, conflict and rapid change in a society","definitionCN":"社会中充满混乱、冲突与急剧变化的时期","example":"The city's markets stayed open through years of political turbulence.","exampleCN":"在多年政治动荡中，城里的市场一直开着。","why":"a society in turmoil is like a fluid that has lost its smooth layers, which is why the abstract sense feels natural.","whyCN":"陷入动荡的社会就像失去平滑层流的流体，因此这个抽象义读来自然。"},{"no":"05","title":"Emotional disturbance","titleCN":"情绪或关系中的波动","definition":"an unsettled, agitated state of feeling or of a relationship","definitionCN":"情感或关系上不安定、被搅动的状态","example":"A year of turbulence followed the family's sudden move.","exampleCN":"家里突然搬迁之后，随之而来的是动荡的一年。","why":"the same disorder is felt inward: feelings that once ran smooth begin to churn.","whyCN":"同一种无序被转向内心：原本平顺的情绪开始翻搅。"},{"no":"06","title":"Measured intensity of disturbance","titleCN":"可测量的湍流强度","definition":"the measurable degree of random fluctuation in a flow or signal","definitionCN":"流动或信号中随机起伏的可测程度","example":"Sensors logged the turbulence inside the wind tunnel.","exampleCN":"传感器记录了风洞内的湍流强度。","why":"science turned the quality into a quantity, so turbulence can now be high, low or within a stated range.","whyCN":"科学把这种性质变成可计量的量，于是湍流可以说高、低或落在某个区间。"},{"no":"07","title":"Ocean mixing","titleCN":"海洋中的湍流混合","definition":"small-scale swirling in the ocean that mixes heat, salt and nutrients","definitionCN":"海洋中把小尺度涡旋、热量、盐分与养分混合起来的过程","example":"Turbulence along the shelf edge carries warm water downward.","exampleCN":"陆架边缘的湍流把暖水带向深处。","why":"the oceanographic sense is still the fluid sense, narrowed to the mixing that eddies perform.","whyCN":"海洋学义仍是流体义，只是收窄到涡旋所完成的混合作用。"},{"no":"08","title":"General disorder","titleCN":"抽象义：局面失去秩序","definition":"a general condition in which order has broken down and events move unpredictably","definitionCN":"秩序崩解、事态难以预测的一般局面","example":"The schedule fell into turbulence after the storm closed the airport.","exampleCN":"风暴关闭机场后，日程陷入一片混乱。","why":"the most general sense keeps only the core of turba: a crowd whose movements no longer follow a line.","whyCN":"最泛化的义项只保留 turba 的核心：一群不再循线而行的人和事。"}],"etymology":{"intro":{"en":"Turbulence comes from Latin turbulentia 'disturbance', from turbulentus 'confused, restless', from turbare 'to disturb', from turba 'turmoil, crowd'. Dates are approximate.","cn":"turbulence 来自拉丁 turbulentia「扰动」，出自 turbulentus「混乱、躁动」，再出自 turbare「搅乱」，最终出自 turba「骚动、人群」。年代均为约数。"},"items":[{"era":"LATIN TURBA","en":"Turba meant 'a crowd, a turmoil, a disturbance'. Its deeper origin is disputed; a link with Greek tyrbe 'turmoil' has been suggested but is not demonstrated.","cn":"turba 意为「人群、骚动、扰乱」。其更深来源有争议；有人提出它与希腊语 tyrbe「骚动」有关，但这并未得到证实。"},{"era":"LATIN TURBARE","en":"From turba came turbare 'to disturb, throw into confusion', the verb behind turbulentus and turbulentia.","cn":"由 turba 产生 turbare「搅乱、使陷入混乱」，它正是 turbulentus 与 turbulentia 背后的动词。"},{"era":"LATIN TURBULENTIA","en":"Turbulentia named the state of being disturbed or restless; English took the word through French in the sixteenth century.","cn":"turbulentia 指被搅动、躁动的状态；英语在十六世纪经法语引入这个词。"},{"era":"FLUID DYNAMICS","en":"In the nineteenth and twentieth centuries the word was fixed as the technical name for chaotic flow, opposed to laminar flow.","cn":"到十九与二十世纪，这个词被固定为混乱流动的技术名称，与层流相对。"},{"era":"SOCIAL AND EMOTIONAL SENSE","en":"The political and emotional senses are older metaphors that treat a society or a mind as a stirred liquid.","cn":"政治义与情绪义是较旧的比喻，把社会或人心当作被搅动的液体。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of turba is unsettled, and the Greek comparison remains a hypothesis rather than a proven borrowing, so any reconstructed root is offered only as a reconstruction.","cn":"来源不确定：turba 在拉丁语之前的来源未有定论，与希腊语的比较仍只是假说而非已证实的借取，凡给出的重构词根都只能算重构形式。"}]},"similar":{"note":{"en":"Group one separates words from the same Latin turb- stock that are often confused; group two holds near synonyms for disorder with different scopes.","cn":"第一组区分同出拉丁 turb- 词干、常被混淆的词；第二组是范围不同的「混乱」近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"turbulent","ipa":"/ˈtɜːbjələnt/","tag":"the adjective","definition":"An adjective meaning 'full of turbulence'; it describes a flow, a period or a person, while turbulence names the state itself.","definitionCN":"意为「充满湍流的」形容词，描述流动、时期或人；turbulence 则指状态本身。"},{"word":"turbid","ipa":"/ˈtɜːbɪd/","tag":"muddy, not chaotic","definition":"From Latin turbidus 'muddy': thick with suspended matter, said of water or air; it does not mean swirling motion.","definitionCN":"来自拉丁 turbidus「浑浊」：因悬浮物而浓浊，用于水或空气；它不指回旋运动。"},{"word":"perturb","ipa":"/pəˈtɜːb/","tag":"verb with per-","definition":"Per- 'thoroughly' plus turbare: to disturb something or someone, often slightly; it is a verb, not a state.","definitionCN":"per-「彻底」加 turbare：扰乱某物或某人，常指轻微扰动；它是动词，不指状态。"},{"word":"turbine","ipa":"/ˈtɜːbaɪn/","tag":"different Latin noun","definition":"From Latin turbo 'whirlwind, spinning top', a noun distinct from turba; it names a rotating engine, not disorder.","definitionCN":"来自拉丁 turbo「旋风、陀螺」，是与 turba 不同的名词；它指旋转的发动机，不指混乱。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chaos","ipa":"/ˈkeɪɒs/","tag":"total orderlessness","definition":"Complete absence of order; it is stronger and more general than turbulence, which can be a local state within a larger order.","definitionCN":"完全无序；比 turbulence 更强也更泛，后者可以是更大秩序中的局部状态。"},{"word":"commotion","ipa":"/kəˈməʊʃən/","tag":"noisy disturbance","definition":"A noisy, visible disturbance among people; turbulence need not be heard or seen as events.","definitionCN":"人群中喧闹可见的骚动；turbulence 不必表现为听得见、看得见的事件。"},{"word":"unrest","ipa":"/ʌnˈrest/","tag":"social dissatisfaction","definition":"A state of dissatisfaction that may lead to protest; it names the human cause, not the physical churning.","definitionCN":"可能导致抗议的不满状态；它指人的起因，而非物理翻搅。"},{"word":"agitation","ipa":"/ˌædʒɪˈteɪʃən/","tag":"stirred feeling","definition":"Emotional or political stirring; turbulence is broader and can also describe fluids and air.","definitionCN":"情绪或政治上的搅动；turbulence 范围更广，也能描述流体与空气。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"turb- 'turmoil' + -ulence (state): the state of being stirred up.","cn":"turb-「骚动」+ -ulence（状态）：被搅动的状态。"},{"en":"The family runs turbulence, turbulent, turbulently, turbid, perturb, perturbation.","cn":"同族词包括 turbulence、turbulent、turbulently、turbid、perturb、perturbation。"},{"en":"Fixed phrases mark the technical sense: clear-air turbulence, atmospheric turbulence, turbulence intensity.","cn":"固定搭配标出技术义：晴空湍流、大气湍流、湍流强度。"},{"en":"The word is paired with laminar flow as its opposite in fluid mechanics.","cn":"在流体力学中，这个词与层流相对。"},{"en":"Aviation uses it for what passengers feel: turbulence over the mountains, turbulence during descent.","cn":"航空用它指乘客感受到的东西：山地上空的颠簸、下降时的颠簸。"}],"abstract":[{"en":"Picture a river that forgets how to flow in straight lines after it strikes a pier.","cn":"想象河水撞上桥墩后，忘了怎样走直线。"},{"en":"Picture a crowded square where every person changes direction at once.","cn":"想象拥挤的广场上，每个人同时改变方向。"},{"en":"Picture a calm conversation that suddenly breaks into several at once.","cn":"想象一场平静的谈话忽然分成好几摊同时进行。"}]},"examples":[{"en":"Turbulence behind the reef made the channel unsafe for small boats.","cn":"礁石后方的湍流使这条水道对小船不安全。"},{"en":"The flight landed safely despite an hour of turbulence.","cn":"尽管颠簸了一个小时，航班还是安全降落。"},{"en":"Years of turbulence reshaped the country's economy.","cn":"多年的动荡重塑了这个国家的经济。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「turb（搅动）+ ulence（状态）」——被搅得没有秩序的状态 → 湍流、颠簸、动荡","word":"turbulence"},"root":"拉丁 turba「骚动、人群」→ turbare「搅乱」→ turbulentus「混乱的」→ turbulentia「扰动」；turba 更深来源不确定，与希腊语 tyrbe「骚动」的联系仅为假说。","sensesIntro":{"en":"Eight senses follow one disorder: a fluid loses its smooth layers, air shakes a plane, water foams, and the same loss of order is then read into societies, feelings, measurements, the ocean and finally into any broken schedule.","cn":"八个义项沿同一种失序展开：流体失去平滑层理，空气把飞机摇动，水面翻起白沫，同一种失序再被读进社会、情绪、测量、海洋，最后读进任何被打乱的日程。"},"semanticMap":{"core":{"en":"CORE IMAGE: smooth parallel threads of water breaking into random eddies.","cn":"核心意象：原本平行的水线碎成无规则的涡旋。"},"chain":["CHURN","IRREGULAR FLOW","BUMPY AIR","SOCIAL UNREST","EMOTIONAL STORM","MIXING"],"branches":[{"senses":"S1 · S3","en":"VISIBLE CHURN: fluid and water lose their layers.","cn":"可见翻搅：流体与水失去层理。"},{"senses":"S2","en":"AIRBORNE SHAKE: the same flow is felt as a bump in flight.","cn":"空中摇晃：同一种流动在飞行中被感受为颠簸。"},{"senses":"S4 · S8","en":"BROKEN ORDER: society or a schedule falls out of its line.","cn":"秩序崩解：社会或日程脱离原有的线路。"},{"senses":"S5","en":"INWARD STORM: feelings churn like stirred water.","cn":"内心风暴：情绪像被搅动的水一样翻涌。"},{"senses":"S6 · S7","en":"MEASURED MIXING: intensity is logged and eddies mix the sea.","cn":"可测混合：强度被记录，涡旋混合海水。"}]},"affixes":{"intro":{"en":"Turbulence is a Latin state noun built on turba 'turmoil'; the turb- root also builds verbs and adjectives of disturbing and stirring.","cn":"turbulence 是建立在 turba「骚动」之上的拉丁状态名词；turb- 词根还构成表示搅乱与翻动的动词、形容词。"},"latinIntro":{"en":"Latin turba, turbare and turbulentia give turbulence, turbulent and perturb; turbid comes from the related turbidus 'muddy'.","cn":"拉丁 turba、turbare 与 turbulentia 衍生 turbulence、turbulent 与 perturb；turbid 则来自相关的 turbidus「浑浊」。"},"items":[{"word":"turb-","structure":"turba (Latin noun, 'crowd, turmoil')","meaning":"a crowd; a disturbance","meaningCN":"人群；骚动","example":"The square filled with a shouting turba.","exampleCN":"广场上挤满了叫嚷的人群。"},{"word":"turbare","structure":"turbare, turbavi, turbatum (Latin verb, first conjugation)","meaning":"to disturb, confuse","meaningCN":"搅乱；使混乱","example":"The news turbavit the whole household.","exampleCN":"这消息搅乱了整个家。"},{"word":"turbulentus","structure":"turbare + -ulentus (full of)","meaning":"full of confusion, restless","meaningCN":"充满混乱的；躁动的","example":"The turbulentus sea kept the boats ashore.","exampleCN":"翻涌的大海把船困在岸上。"},{"word":"turbulence","structure":"turbulentus + -entia (state noun)","meaning":"a state of disturbance","meaningCN":"受扰动的状态","example":"The turbulence shook the cabin.","exampleCN":"湍流摇晃着机舱。"},{"word":"turbulent","structure":"turbulence + -ent (adjective form)","meaning":"marked by turbulence","meaningCN":"具有湍流特征的；动荡的","example":"They crossed a turbulent strait.","exampleCN":"他们穿过一条水流翻涌的海峡。"},{"word":"turbid","structure":"turbidus (Latin adjective, 'muddy')","meaning":"thick with suspended matter","meaningCN":"因悬浮物而浑浊的","example":"The flood left the river turbid for days.","exampleCN":"洪水让河水浑浊了好几天。"},{"word":"perturb","structure":"per- (thoroughly) + turbare","meaning":"to disturb greatly","meaningCN":"扰乱；使不安","example":"The change perturbed the old routine.","exampleCN":"这一变化打乱了旧有的常规。"},{"word":"perturbation","structure":"perturb + -ation (action noun)","meaning":"a disturbance","meaningCN":"扰动；不安","example":"The perturbation spread through the system.","exampleCN":"扰动在系统中扩散开来。"},{"word":"turbidity","structure":"turbid + -ity (quality noun)","meaning":"the quality of being muddy","meaningCN":"浑浊的性质；浑浊度","example":"Turbidity rose after the landslide.","exampleCN":"滑坡之后浑浊度升高。"}],"latinEntries":[{"word":"turba","structure":"turba, turbae (f., first declension)","meaning":"crowd, turmoil, disturbance","meaningCN":"人群；骚动；扰乱"},{"word":"turbare","structure":"turbare, turbavi, turbatum (verb, first conjugation)","meaning":"to disturb, throw into confusion","meaningCN":"搅乱；使陷入混乱"},{"word":"turbulentia","structure":"turbulentia, turbulentiae (f., first declension)","meaning":"disturbance, unrest","meaningCN":"扰动；不安"}]}},{"word":"turbulent","ipa_uk":"/ˈtɜːbjələnt/","ipa_us":"/ˈtɜːrbjələnt/","definition_zh":"湍流的；翻涌的；动荡的；骚动不安的","definition_en":"moving in a chaotic, irregular way, or marked by unrest and rapid change","core_image":"被风撕碎的水面，浪头彼此冲撞，找不到一条安静的线","scene":"湖畔的风把水面卷成碎浪，岸边的芦苇一齐弯向一侧。 The lake remained turbulent until the wind dropped at dusk.","sceneCN":"这里 turbulent 指「水面被搅动、翻涌不止的状态」（第 1 个义项：流体剧烈而不规则地运动）；句意为湖面一直翻涌到黄昏风停。图中可辨识物件：碎浪、弯向一侧的芦苇、压低的云、岸边石。","pos":[{"tag":"adj.","zh":"湍流的；翻涌的；动荡的；骚动的"}],"collocations":[{"phrase":"turbulent flow","zh":"湍流；紊流"},{"phrase":"turbulent times","zh":"动荡的年代"},{"phrase":"turbulent water","zh":"翻涌的水面"},{"phrase":"turbulent air","zh":"颠簸的气流"},{"phrase":"turbulent history","zh":"动荡的历史"},{"phrase":"turbulent emotions","zh":"翻腾的情绪"}],"forms":[{"label":"比较级","form":"more turbulent"},{"label":"最高级","form":"most turbulent"},{"label":"名词（湍流；动荡）","form":"turbulence"},{"label":"副词（动荡地）","form":"turbulently"},{"label":"名词（扰动）","form":"perturbation"},{"label":"形容词（浑浊的）","form":"turbid"}],"derivatives":[{"word":"turbulence","pos":"n.","zh":"湍流；颠簸；动荡"},{"word":"turbulently","pos":"adv.","zh":"翻涌地；动荡地"},{"word":"perturb","pos":"v.","zh":"扰乱；使不安"},{"word":"perturbation","pos":"n.","zh":"扰动；不安"},{"word":"turbid","pos":"adj.","zh":"浑浊的；混乱的"}],"senses":[{"no":"01","title":"Of flow: chaotic and eddying","titleCN":"（流体）湍流的、涡旋混乱的","definition":"describing a fluid whose flow is irregular and full of eddies rather than smooth and layered","definitionCN":"描述流体流动不规则、充满涡旋，而非平滑分层","example":"The lake remained turbulent until the wind dropped at dusk.","exampleCN":"湖面一直翻涌到黄昏风停。","why":"turbulent is the adjective of turbulence, and both descend from Latin turba 'turmoil'; the adjective simply names whatever carries that disorder.","whyCN":"turbulent 是 turbulence 的形容词，两者都源自拉丁 turba「骚动」；形容词只是指出带有这种无序的事物。"},{"no":"02","title":"Of air: rough and bumpy","titleCN":"（气流）颠簸不定的","definition":"describing air that rises and falls unevenly and shakes an aircraft","definitionCN":"描述空气不均匀地升降，使飞机摇晃","example":"Pilots avoid turbulent air near the thunderheads.","exampleCN":"飞行员避开雷暴云附近的颠簸气流。","why":"the aviation sense is the fluid sense applied to the sky, where passengers feel the disorder as jolts.","whyCN":"航空义是把流体义用于天空，乘客把这种无序感受为一次次撞击。"},{"no":"03","title":"Of water: churning","titleCN":"（水面）翻腾汹涌的","definition":"describing water that swirls violently and breaks into foam","definitionCN":"描述水剧烈回旋并拍出白沫","example":"The ferry crossed a turbulent strait in winter.","exampleCN":"渡轮在冬天穿过一条水流翻涌的海峡。","why":"water is the most visible carrier of turbulence, so the adjective is often used of seas and rivers.","whyCN":"水是湍流最可见的载体，因此这个形容词常用于海洋与河流。"},{"no":"04","title":"Of a period: full of upheaval","titleCN":"（时期）充满剧变与动荡的","definition":"describing a period marked by conflict, sudden change and uncertainty","definitionCN":"描述充满冲突、突变与不确定性的时期","example":"The country passed through a turbulent decade of reform.","exampleCN":"这个国家经历了动荡的十年改革。","why":"history is imagined as a current, and a period of rapid conflict is one that will not settle into a line.","whyCN":"历史被想象成一股水流，急剧冲突的时期就是无法归于一条线的水流。"},{"no":"05","title":"Of society: restless","titleCN":"（社会）骚动不安的","definition":"describing a society or group in a state of unrest and agitation","definitionCN":"描述处于不安与骚动中的社会或群体","example":"Turbulent crowds gathered outside the assembly hall.","exampleCN":"骚动的人群聚集在议事厅外。","why":"the Latin source turba literally meant a crowd, so the adjective kept a natural foothold in descriptions of people.","whyCN":"拉丁词源 turba 本义就是「人群」，因此这个形容词自然保留了描述人的用法。"},{"no":"06","title":"Of feelings: agitated","titleCN":"（情绪）翻腾不安的","definition":"describing emotions that are intense, unsettled and hard to control","definitionCN":"描述强烈、不安定、难以控制的情绪","example":"Her turbulent feelings showed in the way she paced the room.","exampleCN":"她翻腾的情绪从她在屋里来回踱步的样子显露出来。","why":"the inner life is treated as a liquid, and strong feelings are those that will not stay level.","whyCN":"内心被当作一种液体，强烈的情绪就是无法保持水平的那种。"},{"no":"07","title":"Of a market: sharply unstable","titleCN":"（市场、局势）剧烈波动的","definition":"describing a market or situation with violent, unpredictable swings","definitionCN":"描述剧烈且难以预测地起落的市场或局势","example":"Investors pulled back during a turbulent week on the exchange.","exampleCN":"交易所经历动荡的一周，投资者纷纷收手。","why":"prices that swing without a stable trend repeat the physical picture of a churned surface.","whyCN":"价格在没有稳定趋势的情况下剧烈起落，重复了翻搅水面的物理图景。"},{"no":"08","title":"Of a relationship: stormy","titleCN":"（关系）波折不断的","definition":"describing a relationship or negotiation full of friction and reversals","definitionCN":"描述充满摩擦与反复的关系或谈判","example":"Their turbulent partnership survived two near-breakups.","exampleCN":"他们波折不断的合作熬过了两次濒临破裂。","why":"two people, like two currents, can meet in a way that keeps throwing up spray.","whyCN":"两个人就像两股水流，相遇时不断激起水花。"}],"etymology":{"intro":{"en":"Turbulent comes from Latin turbulentus 'confused, restless, stormy', formed from turbare 'to disturb' and the suffix -ulentus 'full of'. Dates are approximate.","cn":"turbulent 来自拉丁 turbulentus「混乱的、躁动的、汹涌的」，由 turbare「搅乱」加后缀 -ulentus「充满……」构成。年代均为约数。"},"items":[{"era":"LATIN TURBA","en":"Turba 'crowd, turmoil' supplied the disorder at the heart of the word. Its own earlier origin is disputed.","cn":"turba「人群、骚动」提供了这个词核心的无序义。它更早的来源本身有争议。"},{"era":"LATIN TURBARE","en":"Turbare 'to disturb, throw into confusion' turned the noun into an action of stirring things up.","cn":"turbare「搅乱、使混乱」把这个名词变成「把东西搅起来」的动作。"},{"era":"LATIN TURBULENTUS","en":"The suffix -ulentus 'full of' produced turbulentus 'full of disturbance', first used of weather, water and crowds.","cn":"后缀 -ulentus「充满……」构成 turbulentus「充满扰动的」，最初用于天气、水面与人群。"},{"era":"ENGLISH ENTRY","en":"English borrowed the adjective through French in the sixteenth century; political and emotional uses appear early.","cn":"英语在十六世纪经法语借入这个形容词，政治义与情绪义很早就出现了。"},{"era":"SCIENTIFIC SENSE","en":"Modern fluid mechanics fixed turbulent as the opposite of laminar, giving the adjective a precise technical reading.","cn":"现代流体力学把 turbulent 固定为 laminar（层流的）的对立面，使这个形容词有了精确的技术含义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of turba before Latin is unsettled and the suggested Greek connection is a hypothesis, so any reconstructed Indo-European root is only a reconstruction.","cn":"来源不确定：turba 在拉丁语之前的来源未有定论，所提出的希腊语联系只是假说，凡给出的印欧词根均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the adjective from its noun, its adverb and its look-alike relatives; group two holds adjectives of disorder that differ in force and scope.","cn":"第一组把这个形容词与它的名词、副词及形近同族词分开；第二组是表示无序的形容词，强度与范围不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"turbulence","ipa":"/ˈtɜːbjələns/","tag":"the noun","definition":"The noun names the state; turbulent is the adjective that describes something in that state.","definitionCN":"名词指这种状态；turbulent 是描述处于该状态之物的形容词。"},{"word":"turbulently","ipa":"/ˈtɜːbjələntli/","tag":"the adverb","definition":"The adverb modifies a verb, telling how something moves; it is not a synonym of the adjective.","definitionCN":"副词修饰动词，说明运动的方式；它不是形容词的同义词。"},{"word":"turbid","ipa":"/ˈtɜːbɪd/","tag":"muddy, not swirling","definition":"From turbidus 'muddy': cloudy with particles; a turbid river may be still, while a turbulent one is churning.","definitionCN":"来自 turbidus「浑浊」：因颗粒而混浊；浑浊的河可以静止，翻涌的河则在搅动。"},{"word":"perturb","ipa":"/pəˈtɜːb/","tag":"the verb","definition":"Per- plus turbare, meaning to disturb someone or something; the adjective describes the resulting state, not the act.","definitionCN":"per- 加 turbare，意为扰乱某人或某物；形容词描述结果状态，而非动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stormy","ipa":"/ˈstɔːmi/","tag":"weather and conflict","definition":"Marked by storms or angry conflict; turbulent stresses disorderly motion rather than the storm itself.","definitionCN":"以风暴或激烈冲突为特征；turbulent 更强调无序的运动，而非风暴本身。"},{"word":"chaotic","ipa":"/keɪˈɒtɪk/","tag":"without any order","definition":"Wholly without order; turbulent can describe vigorous but still bounded motion, so it is often milder.","definitionCN":"完全无秩序；turbulent 可指剧烈但仍受边界限制的运动，因此常较温和。"},{"word":"restless","ipa":"/ˈrestləs/","tag":"unable to settle","definition":"Unable to stay still, said of people or moods; it lacks the physical churning of turbulent.","definitionCN":"无法安定，用于人或情绪；它缺少 turbulent 那种物理翻搅。"},{"word":"agitated","ipa":"/ˈædʒɪteɪtɪd/","tag":"stirred up","definition":"Nervous or disturbed in feeling, or physically stirred; it is usually narrower than turbulent.","definitionCN":"情绪紧张不安，或被物理搅动；通常比 turbulent 范围更窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"turb- 'turmoil' + -ulent (full of): full of disturbance.","cn":"turb-「骚动」+ -ulent（充满）：充满扰动的。"},{"en":"The family runs turbulent, turbulence, turbulently, turbid, perturb.","cn":"同族词包括 turbulent、turbulence、turbulently、turbid、perturb。"},{"en":"Fixed phrases mark its range: turbulent flow, turbulent times, turbulent water, turbulent air.","cn":"固定搭配标出它的范围：湍流、动荡的年代、翻涌的水面、颠簸的气流。"},{"en":"Fluid mechanics opposes turbulent to laminar, the rough flow to the smooth.","cn":"流体力学把 turbulent 与 laminar 相对，即粗糙流动与平滑流动。"},{"en":"Journalism pairs it with times, decade and history when describing an unsettled era.","cn":"新闻写作在描述不安定年代时，常把它与 times、decade、history 搭配。"}],"abstract":[{"en":"Picture a lake that refuses to hold a reflection because every wave arrives from a different angle.","cn":"想象一片湖怎么也不肯留住倒影，因为每道浪都从不同方向来。"},{"en":"Picture a meeting where three people speak at once and no one holds the floor.","cn":"想象一场会有三个人同时说话，没人能主导。"},{"en":"Picture a heart that cannot decide whether to laugh or cry, and does both.","cn":"想象一颗心决定不了该笑还是该哭，于是两样都做了。"}]},"examples":[{"en":"The divers waited for the turbulent water to calm.","cn":"潜水员等待翻涌的水面平静下来。"},{"en":"He grew up in a turbulent border town.","cn":"他在一个动荡的边境小镇长大。"},{"en":"Their turbulent romance filled two volumes of letters.","cn":"他们波折不断的恋情写满了两卷书信。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「turb（搅动）+ ulent（充满）」——充满搅动的 → 湍流的、翻涌的、动荡的","word":"turbulent"},"root":"拉丁 turbare「搅乱」+ -ulentus「充满」→ turbulentus「充满扰动的」；再往前出自 turba「骚动、人群」，其更深来源不确定，与希腊语 tyrbe 的联系仅为假说。","sensesIntro":{"en":"Eight senses follow one adjective: a churned surface, the air above it, the water itself, and then the same disorder is read into periods, crowds, feelings, markets and relationships.","cn":"八个义项沿同一个形容词展开：翻搅的表面、其上方的空气、水本身，随后同一种失序被读进时期、人群、情绪、市场与关系。"},"semanticMap":{"core":{"en":"CORE IMAGE: a surface that cannot settle because every current arrives at a different angle.","cn":"核心意象：一个无法平静的表面，因为每道水流都从不同角度到来。"},"chain":["CHURNING","UNEVEN AIR","UPHEAVAL","AGITATION","INSTABILITY","STORMY BOND"],"branches":[{"senses":"S1 · S3","en":"VISIBLE CHURN: flow and water refuse to stay layered.","cn":"可见翻搅：水流与水拒绝保持层理。"},{"senses":"S2","en":"AIRBORNE ROUGHNESS: the same disorder is felt as a jolt.","cn":"空中粗糙：同一种无序被感受为撞击。"},{"senses":"S4 · S5","en":"HISTORICAL UPHEAVAL: periods and crowds lose their line.","cn":"历史剧变：时期与人群失去原有的线路。"},{"senses":"S6","en":"INNER AGITATION: feeling churns like water.","cn":"内心激荡：情绪像水一样翻搅。"},{"senses":"S7 · S8","en":"UNSTABLE BONDS: markets and relationships swing without settling.","cn":"不稳的联结：市场与关系剧烈摇摆，无法安定。"}]},"affixes":{"intro":{"en":"Turbulent is a Latin adjective of fullness built on the turb- root, so its relatives all circle around disturbance.","cn":"turbulent 是建立在 turb- 词根上的拉丁「充满」形容词，因此其同族词都围绕「扰动」展开。"},"latinIntro":{"en":"Latin turba and turbare give turbulent, turbulence and perturb; -ulentus is the suffix that turned the verb into 'full of disturbance'.","cn":"拉丁 turba 与 turbare 衍生 turbulent、turbulence 与 perturb；-ulentus 是把动词变成「充满扰动」的后缀。"},"items":[{"word":"turb-","structure":"turba (Latin noun, 'crowd, turmoil')","meaning":"a crowd; a disturbance","meaningCN":"人群；骚动","example":"A noisy turba filled the forum.","exampleCN":"喧闹的人群挤满了广场。"},{"word":"turbare","structure":"turbare, turbavi, turbatum (Latin verb, first conjugation)","meaning":"to disturb, confuse","meaningCN":"搅乱；使混乱","example":"The rumour turbavit the market.","exampleCN":"谣言扰乱了市场。"},{"word":"-ulentus","structure":"-ulentus, -ulenta, -ulentum (Latin adjective suffix)","meaning":"full of, abounding in","meaningCN":"充满……的","example":"A suffix of abundance builds adjectives from nouns and verbs.","exampleCN":"这个表丰盈的后缀由名词或动词构成形容词。"},{"word":"turbulentus","structure":"turbare + -ulentus","meaning":"full of confusion, stormy","meaningCN":"充满混乱的；汹涌的","example":"The turbulentus sea delayed the fleet.","exampleCN":"汹涌的大海耽搁了船队。"},{"word":"turbulent","structure":"turbulentus + -ent (English adjective)","meaning":"marked by turbulence","meaningCN":"具有湍流特征的；动荡的","example":"They sailed through turbulent water.","exampleCN":"他们驶过翻涌的水面。"},{"word":"turbulence","structure":"turbulent + -ence (state noun)","meaning":"the state of being turbulent","meaningCN":"湍流或动荡的状态","example":"Turbulence shook the aircraft.","exampleCN":"湍流摇晃着飞机。"},{"word":"turbulently","structure":"turbulent + -ly (adverb)","meaning":"in a turbulent manner","meaningCN":"翻涌地；动荡地","example":"The river ran turbulently through the gorge.","exampleCN":"河水翻涌着穿过峡谷。"},{"word":"perturb","structure":"per- (thoroughly) + turbare","meaning":"to disturb greatly","meaningCN":"扰乱；使不安","example":"The question perturbed the witness.","exampleCN":"这个问题让证人不安。"},{"word":"turbid","structure":"turbidus (Latin adjective, 'muddy')","meaning":"cloudy with particles","meaningCN":"因颗粒而浑浊的","example":"The stream turned turbid after rain.","exampleCN":"雨后小溪变得浑浊。"}],"latinEntries":[{"word":"turba","structure":"turba, turbae (f., first declension)","meaning":"crowd, turmoil","meaningCN":"人群；骚动"},{"word":"turbare","structure":"turbare, turbavi, turbatum (verb, first conjugation)","meaning":"to disturb, confuse","meaningCN":"搅乱；使混乱"},{"word":"turbulentus","structure":"turbulentus, turbulenta, turbulentum (adj., first and second declension)","meaning":"confused, stormy, restless","meaningCN":"混乱的；汹涌的；躁动的"}]}},{"word":"surface","ipa_uk":"/ˈsɜːfɪs/","ipa_us":"/ˈsɜːrfɪs/","definition_zh":"表面；水面；地表；界面；表象；浮现；铺面","definition_en":"the outer face of an object or the top of a liquid, or to rise to view; also the outward appearance rather than the inner truth","core_image":"一层薄薄的壳包住整块物体，所有接触都先落在这层壳上","scene":"潜水员在池边停下，指尖先碰到水面才继续下潜。 The diver broke the surface with a quiet splash.","sceneCN":"这里 surface 指「水与空气相接的那一层」（第 2 个义项：水面、液面）；句意为潜水员悄然破开水面，溅起轻微水花。图中可辨识物件：池边、指尖、水面、细碎水花。","pos":[{"tag":"n.","zh":"表面；水面；地表；界面；表象"},{"tag":"vi.","zh":"浮出水面；显现；公开"},{"tag":"vt.","zh":"给……铺面；使露出表面"},{"tag":"adj.","zh":"表面的；表层的"}],"collocations":[{"phrase":"on the surface","zh":"表面上；从表面看"},{"phrase":"surface water","zh":"地表水"},{"phrase":"surface area","zh":"表面积"},{"phrase":"surface tension","zh":"表面张力"},{"phrase":"surface temperature","zh":"表面温度"},{"phrase":"rise to the surface","zh":"浮到水面；显露出来"}],"forms":[{"label":"复数","form":"surfaces"},{"label":"三单（he/she/it）","form":"surfaces"},{"label":"过去式","form":"surfaced"},{"label":"过去分词","form":"surfaced"},{"label":"现在分词","form":"surfacing"},{"label":"形容词（表面的；肤浅的）","form":"superficial"},{"label":"名词（表面；外观，术语）","form":"superficies"}],"derivatives":[{"word":"superficial","pos":"adj.","zh":"表面的；肤浅的"},{"word":"superficially","pos":"adv.","zh":"表面上；肤浅地"},{"word":"superficies","pos":"n.","zh":"表面；外观（法律与几何术语）"},{"word":"surfacing","pos":"n.","zh":"铺面材料；表层处理"},{"word":"surfactant","pos":"n.","zh":"表面活性剂"}],"senses":[{"no":"01","title":"Outer face of an object","titleCN":"物体的外表面","definition":"the outside layer or boundary of a solid object","definitionCN":"固体物件的外层或边界","example":"Dust had settled on every surface in the empty room.","exampleCN":"空房间里每一处表面都落了灰。","why":"surface is French sur- 'above' plus face, so it names the face that lies on top and meets the world first.","whyCN":"surface 由法语 sur-「在上」加 face 构成，指位于上方、最先接触外界的那一面。"},{"no":"02","title":"Top of a liquid","titleCN":"水面；液面","definition":"the boundary between a liquid and the air above it","definitionCN":"液体与其上方空气之间的交界层","example":"The diver broke the surface with a quiet splash.","exampleCN":"潜水员悄然破开水面，溅起轻微水花。","why":"a liquid has no fixed face, so its surface is simply the level where it meets the air.","whyCN":"液体没有固定的脸面，因此它的表面就是与空气相接的那个高度。"},{"no":"03","title":"The ground or land surface","titleCN":"地面；地表","definition":"the top layer of the earth or of a landscape","definitionCN":"大地或地貌的最上层","example":"The road surface cracked after the hard winter.","exampleCN":"严冬过后，路面裂开了。","why":"the ground is the face of the earth, so the same word serves for soil, rock and pavement.","whyCN":"地面就是大地的脸面，因此同一个词可用于土壤、岩石与铺装。"},{"no":"04","title":"Interface between two phases","titleCN":"两相之间的界面","definition":"the boundary where two materials or phases meet","definitionCN":"两种材料或物相相接的边界","example":"Water molecules at the surface behave differently from those inside.","exampleCN":"处于界面的水分子与内部水分子行为不同。","why":"physical chemistry sharpened the everyday word into a measurable boundary between phases.","whyCN":"物理化学把这个日常词精确化为物相之间可测量的边界。"},{"no":"05","title":"Outward appearance only","titleCN":"表象；仅从表面看","definition":"the outward appearance of something, as opposed to its real nature","definitionCN":"事物的外在样子，与真实本质相对","example":"On the surface the deal looked fair.","exampleCN":"从表面看，这笔交易似乎公平。","why":"what lies on the outer face is what can be seen, so surface came to mean appearance without depth.","whyCN":"位于外脸之上的东西就是能被看见的东西，因此 surface 引申为没有深度的表象。"},{"no":"06","title":"Rise to the top of water","titleCN":"浮出水面","definition":"to come up to the top of a body of water after being below it","definitionCN":"从水下升到水体表面","example":"The submarine surfaced after twelve hours below.","exampleCN":"潜艇在水下十二小时后浮出水面。","why":"the verb reverses the viewpoint: instead of looking at the surface, something arrives at it.","whyCN":"动词反转了视角：不是去看表面，而是有东西抵达表面。"},{"no":"07","title":"Come to light","titleCN":"（问题、消息）显露、公开","definition":"to become known or visible after being hidden","definitionCN":"原本隐藏的事物变得为人所知或可见","example":"New evidence surfaced during the second hearing.","exampleCN":"第二次听证时出现了新证据。","why":"something hidden below the water becomes visible when it reaches the surface, and information follows the same path.","whyCN":"藏在水下的东西到达水面就可见，信息走的也是同一条路径。"},{"no":"08","title":"Pave a road","titleCN":"给路面铺面层","definition":"to put a hard layer on a road or path","definitionCN":"在道路或通道上铺一层硬质表层","example":"Crews surfaced the lane with fresh asphalt.","exampleCN":"施工队用新沥青给这条车道铺了面层。","why":"paving creates an artificial face for the ground, which is why the verb uses the same word.","whyCN":"铺路就是给地面造一张人造的脸面，因此动词也用同一个词。"},{"no":"09","title":"Shallow, not deep","titleCN":"形容词：表面的、不深入的","definition":"existing only at the outer level and lacking depth or seriousness","definitionCN":"只停留在外层，缺乏深度或严肃性","example":"His surface calm hid a great deal of worry.","exampleCN":"他表面的平静掩藏了许多忧虑。","why":"the adjective keeps the idea of the outer layer and applies it to knowledge, calm or charm.","whyCN":"形容词保留「外层」的观念，再用到知识、平静或魅力上。"}],"etymology":{"intro":{"en":"Surface comes from French surface, from sur- 'above' plus face 'face', with face from Latin facies 'form, appearance'. It entered English in the sixteenth century. Dates are approximate.","cn":"surface 来自法语 surface，由 sur-「在上」加 face「脸面」构成，而 face 出自拉丁 facies「形状、外观」。它在十六世纪进入英语。年代均为约数。"},"items":[{"era":"LATIN FACIES","en":"Facies meant 'form, shape, appearance, face'. Its link to facere 'to make' is often suggested but not fully demonstrated.","cn":"facies 意为「形状、外观、脸面」。人们常说它与 facere「制造」有关，但这一点并未完全得到证明。"},{"era":"FRENCH SURFACE","en":"French built surface from sur- 'above' and face, naming the face that lies above or outside something.","cn":"法语用 sur-「在上」与 face 构成 surface，指位于某物上方或外部的那张脸面。"},{"era":"ENGLISH ENTRY","en":"English adopted surface in the sixteenth century for the outer boundary of a body, soon extending it to liquids and land.","cn":"英语在十六世纪引入 surface，指物体的外部边界，随后扩展到液体与土地。"},{"era":"SCIENTIFIC SENSE","en":"From the eighteenth century the word became technical: surface area, surface tension and the interface between phases.","cn":"从十八世纪起这个词变得技术化：表面积、表面张力以及物相之间的界面。"},{"era":"VERBAL SENSE","en":"The verb surfaced developed in the nineteenth century, first of submarines and ships, then of facts that come to light.","cn":"动词 surfaced 在十九世纪发展出来，先用于潜艇与船只，再用于浮出水面的事实。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of facies is unsettled, and the exact first English date is usually given only approximately.","cn":"来源不确定：facies 在拉丁语之前的来源未有定论，英语最早书证的确切年代通常只能给出约数。"}]},"similar":{"note":{"en":"Group one holds words that share the Latin facies or the surf- shape but are not interchangeable; group two holds near synonyms for the outer side of a thing.","cn":"第一组是同出拉丁 facies 或 surf- 外形、但不可互换的词；第二组是表示事物外侧的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"superficial","ipa":"/ˌsuːpəˈfɪʃəl/","tag":"the adjective","definition":"Built on Latin superficies: describing something that concerns only the surface, often with a hint of shallowness.","definitionCN":"建立在拉丁 superficies 之上：描述只涉及表面的东西，常含「肤浅」的暗示。"},{"word":"superficies","ipa":"/ˌsuːpəˈfɪʃiːz/","tag":"technical noun","definition":"The Latin-derived legal and geometric term for a surface or outer appearance; it is not the everyday word for a table top.","definitionCN":"源自拉丁的法律与几何术语，指表面或外观；它不是日常指桌面的词。"},{"word":"surfacing","ipa":"/ˈsɜːfɪsɪŋ/","tag":"material or act","definition":"The noun for the layer laid on a road or the act of applying it; it names a material or process, not a face.","definitionCN":"指铺在道路上的材料层或铺设动作；它指材料或过程，不指脸面。"},{"word":"face","ipa":"/feɪs/","tag":"same root, different scope","definition":"From the same Latin facies: the front of a head or the front side of a thing; surface is the outer layer as a whole.","definitionCN":"同出拉丁 facies：指头部正面或物体正面；surface 指整体的外层。"}]},{"heading":"NEAR MEANING","entries":[{"word":"outside","ipa":"/ˌaʊtˈsaɪd/","tag":"external side","definition":"The external side or the space beyond something; surface is the boundary layer itself.","definitionCN":"指外部一侧或某物之外的空间；surface 指边界层本身。"},{"word":"exterior","ipa":"/ɪkˈstɪəriə/","tag":"formal outside","definition":"A formal word for the outside of a building or object, often as a whole; surface can be any outer face.","definitionCN":"指建筑或物体外部的正式用词，常作为整体；surface 可以是任何外表面。"},{"word":"appearance","ipa":"/əˈpɪərəns/","tag":"look, not layer","definition":"How something looks to observers; the abstract sense of surface is close, but appearance need not involve a physical layer.","definitionCN":"事物在观察者眼中的样子；surface 的抽象义与之接近，但外观不必涉及物理表层。"},{"word":"top","ipa":"/tɒp/","tag":"highest part","definition":"The highest point or part of something; a surface can be vertical, while top is positional.","definitionCN":"某物的最高点或最高部分；surface 可以是竖直的，而 top 表示位置在上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"sur- 'above' + face: the face that lies above and meets the world.","cn":"sur-「在上」+ face「脸面」：位于上方、最先接触外界的那张脸。"},{"en":"The family runs surface, superficial, superficially, superficies, surfacing.","cn":"同族词包括 surface、superficial、superficially、superficies、surfacing。"},{"en":"Fixed phrases mark the physical sense: surface area, surface water, surface tension, surface temperature.","cn":"固定搭配标出物理义：表面积、地表水、表面张力、表面温度。"},{"en":"The idiom on the surface signals the abstract sense of mere appearance.","cn":"习语 on the surface 标出「仅就表象而言」的抽象义。"},{"en":"The verb is common in news: evidence surfaces, a submarine surfaces, a problem surfaces.","cn":"这个动词在新闻中常见：证据浮现、潜艇浮出、问题暴露。"}],"abstract":[{"en":"Picture a sealed parcel where only the wrapping is ever seen.","cn":"想象一个封好的包裹，人们只能看见包装。"},{"en":"Picture a pond whose top is bright while the bottom stays dark.","cn":"想象一口池塘，水面明亮而水底幽暗。"},{"en":"Picture a calm face that tells nothing about the storm behind it.","cn":"想象一张平静的脸，对背后的风暴只字不提。"}]},"examples":[{"en":"Wipe the surface before you apply the paint.","cn":"上漆之前先把表面擦干净。"},{"en":"The wreck surfaced only at low tide.","cn":"沉船只在退潮时才露出水面。"},{"en":"On the surface the plan sounded simple.","cn":"从表面看，这个计划似乎很简单。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「sur（在上）+ face（脸面）」——位于最上面的那张脸 → 表面、水面、表象","word":"surface"},"root":"法语 surface = sur-「在上」+ face「脸面」，face 出自拉丁 facies「形状、外观」；facies 与 facere「制造」的联系常被提及但未完全证实，其更早来源不确定。","sensesIntro":{"en":"Nine senses follow one layer: the outer face of a solid, the top of a liquid, the ground, a phase boundary, mere appearance, and then the acts of rising, coming to light, paving and the adjective for shallowness.","cn":"九个义项沿同一层展开：固体的外表面、液体的顶面、地面、物相边界、单纯的外观，随后是浮出、显露、铺面这些动作，以及表示肤浅的形容词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin shell around a solid body, the first thing any contact meets.","cn":"核心意象：包住固体的一层薄壳，任何接触最先碰到的就是它。"},"chain":["OUTER FACE","WATER LEVEL","GROUND","BOUNDARY","APPEARANCE","EMERGE"],"branches":[{"senses":"S1 · S3","en":"VISIBLE FACE: object and ground present an outside layer.","cn":"可见的脸面：物体与地面都呈现一层外表。"},{"senses":"S2","en":"LIQUID LEVEL: water has a surface where it meets air.","cn":"液面：水与空气相接处形成表面。"},{"senses":"S4","en":"PHASE BOUNDARY: science measures the interface itself.","cn":"物相边界：科学直接测量这个界面。"},{"senses":"S5 · S9","en":"APPEARANCE ONLY: what is seen may lack depth.","cn":"仅存表象：看得见的东西可能没有深度。"},{"senses":"S6 · S7 · S8","en":"ARRIVING AT THE FACE: a body rises, a fact emerges, a road is given a new layer.","cn":"抵达表面：物体浮上、事实显露、道路被铺上新层。"}]},"affixes":{"intro":{"en":"Surface is a French compound of a Latin-derived face and the prefix sur-; its family includes the Latin-based superficial and the technical superficies.","cn":"surface 是法语复合词，由拉丁来源的 face 与前置成分 sur- 构成；其词族包括拉丁系的 superficial 与技术词 superficies。"},"latinIntro":{"en":"Latin facies 'form, face' gives face and, through the compound superficies, superficial and superficially.","cn":"拉丁 facies「形状、脸面」衍生 face，并经复合词 superficies 衍生 superficial 与 superficially。"},"items":[{"word":"sur-","structure":"sur- (French prefix from Latin super, 'above')","meaning":"above, over","meaningCN":"在上；越过","example":"The prefix places one thing over another.","exampleCN":"这个前缀把一物置于另一物之上。"},{"word":"face","structure":"face (French, from Latin facies 'form, appearance')","meaning":"the front or visible side","meaningCN":"正面；可见的一面","example":"The face of the cliff was sheer.","exampleCN":"崖面陡直。"},{"word":"surface","structure":"sur- + face","meaning":"the outer face of a thing","meaningCN":"物体的外表面","example":"The surface was smooth to the touch.","exampleCN":"表面摸起来很光滑。"},{"word":"superficies","structure":"super- (above) + facies (form)","meaning":"surface; outer appearance","meaningCN":"表面；外观","example":"The lease concerns the superficies of the land.","exampleCN":"这份租约涉及土地的表面权利。"},{"word":"superficial","structure":"superficies + -al (adjective)","meaning":"of the surface only","meaningCN":"仅及表面的","example":"The cut was superficial.","exampleCN":"这道割伤只是表皮伤。"},{"word":"superficially","structure":"superficial + -ly (adverb)","meaning":"at the surface level","meaningCN":"表面上；肤浅地","example":"The two plans differ only superficially.","exampleCN":"这两个计划只在表面上有差别。"},{"word":"surfacing","structure":"surface + -ing (action or material noun)","meaning":"the act or material of laying a surface","meaningCN":"铺面（动作或材料）","example":"The surfacing will close the lane for a day.","exampleCN":"铺面施工将使这条车道关闭一天。"},{"word":"surfactant","structure":"surface-active + -ant (agent noun)","meaning":"a substance that acts at a surface","meaningCN":"在表面起作用的物质；表面活性剂","example":"A surfactant lowers the surface tension.","exampleCN":"表面活性剂降低表面张力。"},{"word":"surfaced","structure":"surface + -ed (past participle)","meaning":"having risen to the surface","meaningCN":"已浮出水面的","example":"The surfaced wreck was covered in weed.","exampleCN":"浮出水面的残骸覆满水草。"}],"latinEntries":[{"word":"facies","structure":"facies, faciei (f., fifth declension)","meaning":"form, shape, face, appearance","meaningCN":"形状；脸面；外观"},{"word":"superficies","structure":"superficies, superficiei (f., fifth declension)","meaning":"surface, outer appearance","meaningCN":"表面；外观"},{"word":"superficialis","structure":"superficialis, superficiale (adj., third declension)","meaning":"of the surface","meaningCN":"表面的"}]}},{"word":"seafloor","ipa_uk":"/ˈsiːflɔː/","ipa_us":"/ˈsiːflɔːr/","definition_zh":"海底；海床；海洋底部的表面","definition_en":"the bottom surface of the ocean, covered by sediment and shaped into plains, ridges and trenches","core_image":"海水像一整块透明的厚毯压在大地上，毯子底下那片起伏的泥沙就是海底","scene":"遥控潜水器的灯照下去，泥沙上散着几枚贝壳。 The camera showed a crab crawling across the seafloor.","sceneCN":"这里 seafloor 指「海洋底部的表面」（第 1 个义项：覆盖着沉积物的海底界面）；句意为摄像机拍到一只蟹爬过海底。图中可辨识物件：探照灯、泥沙、贝壳、蟹。","pos":[{"tag":"n.","zh":"海底；海床（通常作单数，不加不定冠词）"}],"collocations":[{"phrase":"seafloor spreading","zh":"海底扩张"},{"phrase":"deep seafloor","zh":"深海海底"},{"phrase":"seafloor sediment","zh":"海底沉积物"},{"phrase":"seafloor mapping","zh":"海底测绘"},{"phrase":"seafloor habitat","zh":"海底栖息地"},{"phrase":"seafloor volcanic activity","zh":"海底火山活动"}],"forms":[{"label":"复数（少见）","form":"seafloors"},{"label":"异体拼写（分写）","form":"sea floor"},{"label":"异体拼写（连字符）","form":"sea-floor"},{"label":"近义复合词","form":"seabed"},{"label":"近义短语","form":"ocean floor"},{"label":"相关术语","form":"seafloor spreading"}],"derivatives":[{"word":"seabed","pos":"n.","zh":"海床；海底"},{"word":"ocean floor","pos":"n.","zh":"洋底"},{"word":"seafloor spreading","pos":"n.","zh":"海底扩张"},{"word":"deep-seafloor","pos":"adj.","zh":"深海海底的"},{"word":"sea-floor","pos":"adj.","zh":"海底的（连字符异体）"}],"senses":[{"no":"01","title":"The bottom of the sea","titleCN":"海洋底部","definition":"the ground beneath the ocean, taken as a whole","definitionCN":"海洋之下的地面，作为整体看待","example":"The camera showed a crab crawling across the seafloor.","exampleCN":"摄像机拍到一只蟹爬过海底。","why":"seafloor is a plain English compound of sea and floor: the sea is given a floor the way a room is.","whyCN":"seafloor 是 sea 与 floor 的英语复合词：给海配上一块地板，正如给房间配上地板。"},{"no":"02","title":"The sediment-covered surface","titleCN":"覆着沉积物的海底界面","definition":"the actual surface layer of mud, sand and rock at the bottom of the sea","definitionCN":"海底由泥、沙与岩石构成的实际表层","example":"Fine sediment covers most of the seafloor in the abyssal plain.","exampleCN":"深海平原的大部分海底覆着细粒沉积物。","why":"a floor is a surface you can touch, so the word also names the sediment layer rather than the whole volume below.","whyCN":"地板是能触摸到的表面，因此这个词也指沉积层，而不是下方整个体积。"},{"no":"03","title":"Submarine terrain","titleCN":"海底地形","definition":"the shape of the ocean bottom, including plains, ridges, hills and trenches","definitionCN":"洋底的形状，包括平原、海岭、丘陵与海沟","example":"Sonar revealed a rugged seafloor cut by deep canyons.","exampleCN":"声呐显示出一片被深谷切开的崎岖海底。","why":"once the bottom is mapped, it behaves like land with its own hills and valleys, so seafloor names terrain as well as surface.","whyCN":"一旦海底被测绘，它就像陆地一样有山有谷，因此 seafloor 也指地形而不只是表面。"},{"no":"04","title":"A benthic habitat","titleCN":"海底栖息地","definition":"the environment at the bottom of the sea where benthic organisms live","definitionCN":"海洋底部、底栖生物生活的环境","example":"Cold seeps support a dense community on the seafloor.","exampleCN":"冷泉在海底养育着密集的生物群落。","why":"ecology treats the bottom as a habitat, so the same word can stand for the living place rather than the rock.","whyCN":"生态学把海底当作栖息地，因此同一个词可指生存场所，而非岩石本身。"},{"no":"05","title":"A record of ocean history","titleCN":"记录海洋历史的地质面","definition":"the bottom as a layered archive of sediment and magnetic stripes","definitionCN":"作为沉积层与磁条带档案的海底","example":"The seafloor records reversals of the magnetic field in stripes.","exampleCN":"海底以条带记录地磁场的倒转。","why":"new crust forms at ridges and keeps a dated record, so geologists read the seafloor like a tape.","whyCN":"新洋壳在海岭形成并留下可定年的记录，因此地质学家像读磁带一样读海底。"},{"no":"06","title":"Ground for resources and structures","titleCN":"海底资源与工程的场所","definition":"the seabed considered as a site for mining, cables, pipelines and platforms","definitionCN":"作为采矿、电缆、管道与平台场所的海底","example":"Engineers surveyed the seafloor before laying the pipeline.","exampleCN":"工程师在铺设管道之前勘测了海底。","why":"industry needs a stable ground under water, and the word supplies that practical sense.","whyCN":"工业需要水下一块稳定的地面，这个词正好提供这层实用意义。"},{"no":"07","title":"The top of oceanic crust","titleCN":"洋壳的顶面","definition":"the upper boundary of the oceanic crust, where rock meets water","definitionCN":"洋壳的上边界，即岩石与海水相接处","example":"Young lava forms fresh seafloor near the ridge axis.","exampleCN":"年轻的熔岩在脊轴附近形成新的海底。","why":"geology distinguishes the crust from the water above it, and the boundary is precisely the seafloor.","whyCN":"地质学把洋壳与上方水体区分开，而二者的边界正是海底。"},{"no":"08","title":"The echo-reflecting interface","titleCN":"声学测深中的反射界面","definition":"the bottom as the surface that returns a sonar echo","definitionCN":"作为返回声呐回声的那个界面","example":"The echo sounder traced the seafloor at six thousand metres.","exampleCN":"回声测深仪在六千米深处描出海底。","why":"hydrography cares only about the surface that reflects sound, so seafloor can mean that acoustic boundary.","whyCN":"水文测量只关心反射声音的那个面，因此 seafloor 可指这条声学边界。"}],"etymology":{"intro":{"en":"Seafloor is a native English compound of sea, from Old English sǣ, and floor, from Old English flor 'floor, ground'. The compound is modern, dating from scientific writing about the ocean. Dates are approximate.","cn":"seafloor 是英语本族复合词，由古英语 sǣ「海」与古英语 flor「地面、底板」构成。这个复合词属于现代词，出自关于海洋的科学写作。年代均为约数。"},"items":[{"era":"OLD ENGLISH SǢ","en":"Sǣ meant 'sea, lake, sheet of water' and is shared by other Germanic languages. Its pre-Germanic origin is not settled.","cn":"sǣ 意为「海、湖、一片水域」，与其他日耳曼语共有。它在日耳曼语之前的来源没有定论。"},{"era":"OLD ENGLISH FLOR","en":"Flor meant 'floor, ground, bottom of a room'. The same word was extended to the bottom of natural features.","cn":"flor 意为「地板、地面、房间底部」。同一个词被扩展到自然事物的底部。"},{"era":"COMPOUND FORMATION","en":"The compound sea floor joins the two nouns in the modern scientific period, when the ocean bottom became an object of systematic mapping.","cn":"sea floor 这个复合词在现代科学时期把两个名词结合，当时海底开始成为系统测绘的对象。"},{"era":"SPELLING","en":"Both sea floor and sea-floor are older spellings; the closed form seafloor is now standard in geology and oceanography.","cn":"sea floor 与 sea-floor 都是较早的写法；在今日地质学与海洋学中，连写的 seafloor 已成标准。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Germanic roots of both sea and floor are reconstructed rather than attested, and the exact first date of the compound is not fixed.","cn":"来源不确定：sea 与 floor 在日耳曼语之前的词根都是重构而非有书证的形式，复合词的确切首见年代也未固定。"}]},"similar":{"note":{"en":"Group one holds the competing names for the ocean bottom, which differ in register and scope; group two holds general words for a bottom surface.","cn":"第一组是海洋底部的几个并用名称，语体与范围不同；第二组是泛指底部表面的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seabed","ipa":"/ˈsiːbed/","tag":"legal and general","definition":"The common British term for the ocean bottom, especially as land under water; it overlaps with seafloor but is more frequent in legal and general prose.","definitionCN":"英式常用词，指海洋底部，尤指水下的土地；与 seafloor 重叠，但更常用于法律与一般文字。"},{"word":"ocean floor","ipa":"/ˈəʊʃən flɔː/","tag":"deep-ocean focus","definition":"The open-ocean bottom as opposed to shallow shelf water; ocean floor is the more explicit phrase for the deep sea.","definitionCN":"指开阔大洋的底部，与浅海陆架相对；ocean floor 是更明确指向深海的短语。"},{"word":"sea floor","ipa":"/ˈsiː flɔː/","tag":"open spelling","definition":"The older two-word spelling of the same compound; it is not a different feature, only a different house style.","definitionCN":"同一复合词的较早分写形式；它不是另一种事物，只是书写体例不同。"},{"word":"seafloor spreading","ipa":"/ˈsiːflɔː ˈspredɪŋ/","tag":"process term","definition":"The geological process by which new crust forms at ridges and moves away; it uses seafloor but names a process, not the bottom itself.","definitionCN":"新洋壳在海岭形成并向两侧移动的地质过程；它虽含 seafloor，却指过程而非海底本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bottom","ipa":"/ˈbɒtəm/","tag":"general lowest part","definition":"The lowest part of anything; it is far broader than seafloor and needs context to mean the ocean bottom.","definitionCN":"任何事物的最低部分；范围远比 seafloor 宽，需要上下文才指海底。"},{"word":"bed","ipa":"/bed/","tag":"natural bottom","definition":"The bottom of a river, lake or sea, as in riverbed; it is the older and more general noun behind seabed.","definitionCN":"河、湖、海的底部，如河床；它是 seabed 背后更旧、更一般的名词。"},{"word":"ground","ipa":"/ɡraʊnd/","tag":"surface to stand on","definition":"The solid surface beneath water or feet; it stresses support rather than the ocean setting.","definitionCN":"水下或脚下的坚实表面；它强调可依托性，而非海洋环境。"},{"word":"depths","ipa":"/depθs/","tag":"deep water, not bottom","definition":"The deep parts of the sea as a region of water; it names the volume, while seafloor names the surface at its base.","definitionCN":"作为水域区域的深海；它指水体积，而 seafloor 指其底部的表面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"sea + floor: the sea given a floor, exactly as a room has one.","cn":"sea「海」+ floor「地板」：给海配一块地板，正如房间有地板。"},{"en":"The related compounds run seafloor, seabed, ocean floor and seafloor spreading.","cn":"相关复合词包括 seafloor、seabed、ocean floor 与 seafloor spreading。"},{"en":"Fixed phrases mark the science: seafloor spreading, seafloor sediment, seafloor mapping.","cn":"固定搭配标出科学用法：海底扩张、海底沉积物、海底测绘。"},{"en":"Geologists read magnetic stripes on the seafloor as a record of reversals.","cn":"地质学家把海底的磁条带读作地磁倒转的记录。"},{"en":"The word is usually singular with no article, as in on the seafloor.","cn":"这个词通常用单数且不加不定冠词，如 on the seafloor。"}],"abstract":[{"en":"Picture a vast room whose ceiling is the whole ocean.","cn":"想象一个巨大的房间，天花板就是整片海洋。"},{"en":"Picture a tape lying under miles of water, still recording.","cn":"想象一盘磁带躺在数英里水下，仍在录音。"},{"en":"Picture a city of crabs and worms built on mud that never sees the sun.","cn":"想象一座由蟹与蠕虫建在泥上的城市，从不见太阳。"}]},"examples":[{"en":"The submersible landed gently on the seafloor.","cn":"潜水器轻轻落在海底。"},{"en":"Volcanic vents on the seafloor build chimneys of rock.","cn":"海底的火山喷口堆起岩石烟囱。"},{"en":"Magnetic stripes on the seafloor record ancient reversals.","cn":"海底的磁条带记录了古老的地磁倒转。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「sea（海）+ floor（地板）」——海的地板就是海底","word":"seafloor"},"root":"英语本族复合词：sea 来自古英语 sǣ「海」，floor 来自古英语 flor「地板、地面」；两词在日耳曼语之前的词根均为重构形式，复合词首见年代不确定。","sensesIntro":{"en":"Eight senses follow one floor: the ocean bottom as a whole, its sediment surface, its terrain, its habitat, its geological record, its use as ground for construction, its identity as crust, and its role as a sonar reflector.","cn":"八个义项沿同一块地板展开：作为整体的海洋底部、其沉积表面、其地形、其栖息地、其地质记录、其作为工程地基的用途、其洋壳身份，以及其作为声呐反射面的角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: a floor under a thick transparent blanket of seawater.","cn":"核心意象：一层厚厚透明海水之下的地板。"},"chain":["SEA BOTTOM","SEDIMENT SURFACE","TERRAIN","HABITAT","GEOLOGIC RECORD","ENGINEERING GROUND"],"branches":[{"senses":"S1 · S2","en":"THE BOTTOM ITSELF: the whole ground and its touchable surface.","cn":"底部本身：整块地面与其可触摸的表层。"},{"senses":"S3 · S7","en":"SHAPED CRUST: terrain and the top of oceanic rock are one boundary.","cn":"有形的洋壳：地形与洋岩顶面是同一条边界。"},{"senses":"S4","en":"LIVING FLOOR: the bottom becomes a habitat.","cn":"活的地板：海底成为栖息地。"},{"senses":"S5 · S8","en":"READABLE SURFACE: magnetic stripes and sonar echoes are both records of the same face.","cn":"可读的表面：磁条带与声呐回声都是同一张脸的记录。"},{"senses":"S6","en":"WORKING GROUND: cables, pipelines and mines need a stable bottom.","cn":"施工地面：电缆、管道与矿山需要稳定的底部。"}]},"affixes":{"intro":{"en":"Seafloor is a transparent Germanic compound, so its parts can be read directly and compared with the parallel compound seabed.","cn":"seafloor 是透明的日耳曼语复合词，其组成部分可以直接读出，并可与并行的复合词 seabed 比较。"},"latinIntro":{"en":"Both sea and floor are Germanic, so the word has no Latin entries; the Latin layer of English supplies terms such as benthic and abyssal instead.","cn":"sea 与 floor 都属日耳曼语，因此这个词没有拉丁条目；英语的拉丁层改为提供 benthic、abyssal 这类术语。"},"items":[{"word":"sea","structure":"Old English sǣ (noun, 'sea, lake')","meaning":"the sea; a large body of salt water","meaningCN":"海；大片咸水","example":"The sea was calm at dawn.","exampleCN":"黎明时海面平静。"},{"word":"floor","structure":"Old English flor (noun, 'floor, ground')","meaning":"the bottom surface of a space","meaningCN":"空间的地面或底板","example":"The floor of the hall was stone.","exampleCN":"大厅的地面是石头的。"},{"word":"seafloor","structure":"sea + floor (compound noun)","meaning":"the bottom of the sea","meaningCN":"海底","example":"The probe settled on the seafloor.","exampleCN":"探测器落在海底。"},{"word":"seabed","structure":"sea + bed (parallel compound)","meaning":"the bed of the sea","meaningCN":"海床","example":"Anchors scarred the seabed.","exampleCN":"锚在海底留下划痕。"},{"word":"seafloor spreading","structure":"seafloor + spreading (verbal noun)","meaning":"the growth of new crust at ridges","meaningCN":"海岭处新洋壳的生长；海底扩张","example":"Seafloor spreading moves the continents apart.","exampleCN":"海底扩张把大陆推开。"},{"word":"deep-seafloor","structure":"deep + seafloor (compound adjective)","meaning":"of the deep ocean bottom","meaningCN":"深海海底的","example":"Deep-seafloor communities rely on falling debris.","exampleCN":"深海海底群落依赖落下的碎屑。"},{"word":"sea-floor","structure":"sea + floor (hyphenated variant)","meaning":"the bottom of the sea","meaningCN":"海底（连字符写法）","example":"The sea-floor map showed a narrow trench.","exampleCN":"海底地图显示出一条狭窄海沟。"},{"word":"undersea","structure":"under- + sea (compound adjective)","meaning":"beneath the sea","meaningCN":"海底的；水下的","example":"An undersea cable links the islands.","exampleCN":"一条海底电缆连接这些岛屿。"}],"latinEntries":[]}},{"word":"seabed","ipa_uk":"/ˈsiːbed/","ipa_us":"/ˈsiːbed/","definition_zh":"海床；海底（尤指作为水下土地与底土上表面的那一层）","definition_en":"the bottom of the sea, especially considered as the underwater land and the surface that lies under shallow or coastal water","core_image":"把海水抽干后露出的那层湿沙与岩石，边界像一块被水盖住的地籍图","scene":"退潮后的浅湾露出湿沙，渔民拖着网在浅水里走。 Anchors had scarred the seabed near the old pier.","sceneCN":"这里 seabed 指「浅海或近岸的水下底部」（第 1 个义项：近岸海底的沙泥表面）；句意为旧码头附近的锚痕划伤了海床。图中可辨识物件：湿沙、渔网、旧木桩、浅水。","pos":[{"tag":"n.","zh":"海床；海底（通常作单数）"}],"collocations":[{"phrase":"seabed mining","zh":"海床采矿"},{"phrase":"seabed lease","zh":"海床租约"},{"phrase":"seabed survey","zh":"海床勘测"},{"phrase":"seabed sediment","zh":"海床沉积物"},{"phrase":"seabed habitat","zh":"海床栖息地"},{"phrase":"disturb the seabed","zh":"扰动海床"}],"forms":[{"label":"复数（少见）","form":"seabeds"},{"label":"异体拼写（分写）","form":"sea bed"},{"label":"异体拼写（连字符）","form":"sea-bed"},{"label":"近义复合词","form":"seafloor"},{"label":"近义短语","form":"sea bottom"},{"label":"相关术语","form":"seabed mining"}],"derivatives":[{"word":"seabed mining","pos":"n.","zh":"海床采矿"},{"word":"seabed survey","pos":"n.","zh":"海床勘测"},{"word":"seabed lease","pos":"n.","zh":"海床租约"},{"word":"sea-bed","pos":"adj.","zh":"海床的（连字符异体）"},{"word":"seafloor","pos":"n.","zh":"海底（同义复合词）"}],"senses":[{"no":"01","title":"Bottom of shallow or coastal sea","titleCN":"浅海或近岸的海底","definition":"the bottom of the sea, especially in coastal waters where it can be reached or worked","definitionCN":"海洋的底部，尤指可以到达或施工的近岸水域底部","example":"Anchors had scarred the seabed near the old pier.","exampleCN":"旧码头附近的锚痕划伤了海床。","why":"seabed is sea plus bed: a bed is the surface one lies on, so the word pictures the sea as a place with a place to rest.","whyCN":"seabed 是 sea 加 bed：床是躺卧其上的表面，因此这个词把海想象成一个有处可躺的地方。"},{"no":"02","title":"Underwater land","titleCN":"水下的土地（法律与管辖意义）","definition":"the sea bottom treated as land that can be owned, leased or regulated","definitionCN":"把海底当作可拥有、出租或受管辖的土地","example":"The Crown holds title to the seabed within territorial waters.","exampleCN":"王室拥有领海内海床的所有权。","why":"property law needs a surface to attach rights to, and the seabed supplies that underwater ground.","whyCN":"财产法需要一张可附着权利的表面，海底正好提供这块水下地面。"},{"no":"03","title":"Sediment skin of the sea bottom","titleCN":"海床的沉积物表层","definition":"the layer of sand, mud and gravel that forms the actual surface of the bottom","definitionCN":"构成底部实际表面的沙、泥与砾石层","example":"A thin layer of sand covers the bedrock seabed here.","exampleCN":"这里一层薄沙覆盖在基岩海床上。","why":"the bed you touch is the sediment, so the word often means that skin rather than the rock beneath.","whyCN":"能触摸到的床面是沉积物，因此这个词常指这层表皮，而非下面的岩石。"},{"no":"04","title":"Base for underwater structures","titleCN":"水下工程的基面","definition":"the bottom considered as the ground on which cables, pipelines or foundations rest","definitionCN":"作为电缆、管道或基础依托之处的底部","example":"Engineers mapped the seabed along the cable route.","exampleCN":"工程师测绘了电缆路线沿线的海床。","why":"builders need a firm bed under water, and the compound's literal image fits that need exactly.","whyCN":"施工者需要水下一块坚实的床面，这个复合词的字面意象正好对应这一需要。"},{"no":"05","title":"Benthic habitat","titleCN":"底栖生物的栖息地","definition":"the bottom as the living place of organisms that attach to or crawl over it","definitionCN":"作为附着或爬行其上的生物生活场所的底部","example":"Oyster reefs once covered much of the estuary seabed.","exampleCN":"牡蛎礁曾覆盖这片河口海床的大部分。","why":"animals that live on the bed turn it into a habitat, so seabed can name a living community's ground.","whyCN":"生活在床面上的动物把海床变成栖息地，因此 seabed 可指一个生物群落的基底。"},{"no":"06","title":"Site of mineral extraction","titleCN":"海床矿产开采场所","definition":"the bottom as a source of sand, gravel, nodules or other minerals","definitionCN":"作为沙、砾石、结核或其他矿产来源的底部","example":"The company applied for a licence to mine the seabed.","exampleCN":"该公司申请了海床采矿许可。","why":"when the bottom is dug for materials, the word shifts from surface to resource site.","whyCN":"当底部被挖取材料时，这个词就从表面义转向资源场所义。"},{"no":"07","title":"Bottom terrain","titleCN":"海床地形","definition":"the shape of the underwater bottom, including banks, channels and scour marks","definitionCN":"水下底部的形状，包括沙洲、水道与冲刷痕","example":"Tidal currents carve ridges across the sandy seabed.","exampleCN":"潮流在沙质海床上刻出一道道脊。","why":"the bed has its own relief, just as a field does, so the word also names bottom terrain.","whyCN":"海床有自己的起伏，正如田野有起伏，因此这个词也指底部地形。"},{"no":"08","title":"Boundary between water and subsoil","titleCN":"水域与底土的分界","definition":"the dividing surface between the water column above and the solid subsoil below","definitionCN":"上方水柱与下方固体底土之间的分界面","example":"Samples were taken right at the seabed to compare pore water.","exampleCN":"样品正好取在海床处，以比较孔隙水。","why":"science needs a line where water ends and soil begins, and the seabed is that line.","whyCN":"科学需要一条水结束、土开始的界线，而海床正是这条线。"}],"etymology":{"intro":{"en":"Seabed is a native English compound of sea, from Old English sǣ, and bed, from Old English bedd 'bed, couch'. The compound is recorded from the early modern period. Dates are approximate.","cn":"seabed 是英语本族复合词，由古英语 sǣ「海」与古英语 bedd「床、卧榻」构成。这个复合词在近代早期已有书证。年代均为约数。"},"items":[{"era":"OLD ENGLISH SǢ","en":"Sǣ meant 'sea, lake, sheet of water' and belongs to the Germanic stock of English. Its earlier origin is not settled.","cn":"sǣ 意为「海、湖、一片水域」，属于英语的日耳曼语词库。它更早的来源没有定论。"},{"era":"OLD ENGLISH BEDD","en":"Bedd meant 'bed, couch, resting place', and was soon used for the bottom of a river or sea.","cn":"bedd 意为「床、卧榻、休憩之处」，很快也用于河或海的底部。"},{"era":"COMPOUND FORMATION","en":"The compound sea bed was formed by analogy with riverbed, treating the sea as a body with a bed of its own.","cn":"sea bed 这个复合词依 riverbed 的类推构成，把海看作一个有自己的床的水体。"},{"era":"LEGAL AND INDUSTRIAL USE","en":"Modern law and offshore industry made seabed a familiar term for underwater land and its resources.","cn":"现代法律与近海工业使 seabed 成为指水下土地及其资源的常用词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Germanic roots of sea and bed are reconstructed, and the exact first citation of the compound is not fixed.","cn":"来源不确定：sea 与 bed 在日耳曼语之前的词根均为重构形式，复合词的最早书证年代也未固定。"}]},"similar":{"note":{"en":"Group one holds the competing and related names for the sea bottom; group two holds general words that can mean a bottom only in context.","cn":"第一组是海洋底部的并用名称与相关名称；第二组是只有在语境中才能指底部的通用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seafloor","ipa":"/ˈsiːflɔː/","tag":"same referent, science tone","definition":"A near synonym used especially in geology and oceanography; seabed is more common in law, industry and general British prose.","definitionCN":"近义词，尤用于地质学与海洋学；seabed 更常见于法律、工业与英式一般文字。"},{"word":"sea bed","ipa":"/ˈsiː bed/","tag":"spelling variant","definition":"The two-word spelling of the same compound, not a different feature; house style decides which form appears.","definitionCN":"同一复合词的分写形式，并非另一种事物；用哪种形式取决于体例。"},{"word":"seabed mining","ipa":"/ˈsiːbed ˈmaɪnɪŋ/","tag":"process term","definition":"The industry of extracting minerals from the bottom; it contains seabed but names an activity.","definitionCN":"从海底提取矿产的行业；它虽含 seabed，却指一种活动。"},{"word":"riverbed","ipa":"/ˈrɪvəbed/","tag":"parallel compound","definition":"The bottom of a river, built on the same bed pattern; it is the model that seabed follows, not a synonym.","definitionCN":"河底，按同一 bed 模式构成；它是 seabed 仿照的模型，并非同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bottom","ipa":"/ˈbɒtəm/","tag":"general lowest part","definition":"The lowest part of anything; context is needed before it means the sea bottom.","definitionCN":"任何事物的最低部分；需要上下文才指海底。"},{"word":"bed","ipa":"/bed/","tag":"the base noun","definition":"The bottom of a watercourse or sea; it is the simple noun from which seabed is built.","definitionCN":"水道或海的底部；它是构成 seabed 的简单名词。"},{"word":"ground","ipa":"/ɡraʊnd/","tag":"supporting surface","definition":"The solid surface beneath water or feet; it stresses what can bear weight rather than the marine setting.","definitionCN":"水下或脚下的坚实表面；强调承重，而非海洋环境。"},{"word":"floor","ipa":"/flɔː/","tag":"room-like image","definition":"The bottom surface of a space, used figuratively for the sea in seafloor; it shares the image but not the spelling.","definitionCN":"空间的地面，在 seafloor 中借喻海底；共享意象但拼写不同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"sea + bed: the sea given a bed to rest on.","cn":"sea「海」+ bed「床」：给海配一张可躺的床。"},{"en":"The related compounds run seabed, seafloor, riverbed and lakebed.","cn":"相关复合词包括 seabed、seafloor、riverbed 与 lakebed。"},{"en":"Fixed phrases mark law and industry: seabed lease, seabed mining, seabed survey.","cn":"固定搭配标出法律与工业用法：海床租约、海床采矿、海床勘测。"},{"en":"The word is usually singular and takes the definite article: on the seabed.","cn":"这个词通常用单数并带定冠词：on the seabed。"},{"en":"British usage prefers seabed where American usage often says seafloor.","cn":"英式用法偏好 seabed，而美式用法常说 seafloor。"}],"abstract":[{"en":"Picture a bed of wet sand with no one lying on it.","cn":"想象一张湿沙做的床，却没有人躺在上面。"},{"en":"Picture a buried boundary line drawn under the whole ocean.","cn":"想象整片海洋之下画着一条埋藏的界线。"},{"en":"Picture a field ploughed by anchors instead of ploughs.","cn":"想象一片被锚而非犁翻过的田地。"}]},"examples":[{"en":"The pipeline was buried beneath the seabed.","cn":"管道被埋在海床之下。"},{"en":"Trawling can damage the seabed over wide areas.","cn":"拖网会大面积破坏海床。"},{"en":"The survey found gas pockets just below the seabed.","cn":"勘测发现海床正下方有气藏。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「sea（海）+ bed（床）」——海躺卧的那张床就是海床","word":"seabed"},"root":"英语本族复合词：sea 来自古英语 sǣ「海」，bed 来自古英语 bedd「床、卧榻」；两词在日耳曼语之前的词根均为重构形式，复合词最早书证年代不确定。","sensesIntro":{"en":"Eight senses follow one bed: the shallow bottom, the same bottom as owned land, its sediment skin, its use as a foundation, its living cover, its minerals, its relief, and its role as the line between water and soil.","cn":"八个义项沿同一张床展开：浅海底、作为被拥有的土地、其沉积表皮、其作为地基的用途、其上的生物覆盖、其矿产、其起伏，以及其作为水与土界线的角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wet bed of sand and rock lying under a sheet of shallow water.","cn":"核心意象：一层浅水之下湿沙与岩石构成的床面。"},"chain":["SHALLOW BOTTOM","UNDERWATER LAND","SEDIMENT SKIN","STRUCTURE BASE","HABITAT","MINERAL SITE"],"branches":[{"senses":"S1 · S3","en":"TOUCHABLE BOTTOM: the shallow floor and its sediment surface.","cn":"可触的底部：浅海底与其沉积表层。"},{"senses":"S2 · S8","en":"A DRAWN LINE: the bottom as owned land and as the boundary with subsoil.","cn":"一条画出的线：海底作为被拥有的土地，也作为与底土的分界。"},{"senses":"S4","en":"FOUNDATION: cables and pipelines rest on the bed.","cn":"地基：电缆与管道依托于这张床。"},{"senses":"S5","en":"LIVING COVER: oysters and worms turn the bed into habitat.","cn":"生命覆盖：牡蛎与蠕虫把床面变成栖息地。"},{"senses":"S6 · S7","en":"RESOURCE AND RELIEF: the bed is both a mine and a landscape.","cn":"资源与起伏：这张床既是矿场，也是地形。"}]},"affixes":{"intro":{"en":"Seabed is a transparent Germanic compound of two common nouns, so its parts and its close compounds can be read without Latin help.","cn":"seabed 是两个常用名词构成的透明日耳曼语复合词，其组成部分与近邻复合词无需拉丁语知识即可读出。"},"latinIntro":{"en":"Both sea and bed are Germanic, so the word has no Latin entries; Latin supplies the technical neighbours benthic and littoral instead.","cn":"sea 与 bed 都属日耳曼语，因此这个词没有拉丁条目；拉丁语改为提供 benthic、littoral 这类技术近邻。"},"items":[{"word":"sea","structure":"Old English sǣ (noun, 'sea, lake')","meaning":"the sea","meaningCN":"海","example":"The sea covered the rocks.","exampleCN":"海水淹没了岩石。"},{"word":"bed","structure":"Old English bedd (noun, 'bed, couch')","meaning":"a resting place; a bottom layer","meaningCN":"卧处；底层","example":"The bed of the stream was gravel.","exampleCN":"溪底是砾石。"},{"word":"seabed","structure":"sea + bed (compound noun)","meaning":"the bottom of the sea","meaningCN":"海床；海底","example":"The anchor hit the seabed.","exampleCN":"锚触到了海床。"},{"word":"sea bed","structure":"sea + bed (open spelling)","meaning":"the bottom of the sea","meaningCN":"海床（分写形式）","example":"The chart marks the sea bed in grey.","exampleCN":"海图用灰色标出海床。"},{"word":"seabed mining","structure":"seabed + mining (compound noun)","meaning":"extraction of minerals from the sea bottom","meaningCN":"海床采矿","example":"Seabed mining remains controversial.","exampleCN":"海床采矿仍有争议。"},{"word":"seabed lease","structure":"seabed + lease (compound noun)","meaning":"a legal right to use a area of sea bottom","meaningCN":"海床租约","example":"The firm won a seabed lease.","exampleCN":"这家公司获得了海床租约。"},{"word":"seabed survey","structure":"seabed + survey (compound noun)","meaning":"a systematic mapping of the bottom","meaningCN":"海床勘测","example":"The seabed survey took two months.","exampleCN":"海床勘测花了两个月。"},{"word":"sea-bed","structure":"sea + bed (hyphenated variant)","meaning":"the bottom of the sea","meaningCN":"海床（连字符写法）","example":"The sea-bed profile showed a channel.","exampleCN":"海床剖面显示出一条水道。"}],"latinEntries":[]}},{"word":"ocean floor","ipa_uk":"/ˈəʊʃən flɔː/","ipa_us":"/ˈoʊʃən flɔːr/","definition_zh":"洋底；大洋底部（尤指开阔深海的底部表面）","definition_en":"the bottom of the open ocean, especially the deep-sea floor beyond the continental margins","core_image":"越过大陆架的浅水之后，海底像一张巨大的褐色平原一直铺到对面的大陆坡","scene":"科考船拖着声呐，屏幕上一片平坦的褐色缓缓展开。 The sonar revealed a wide plain on the ocean floor.","sceneCN":"这里 ocean floor 指「开阔大洋底部的表面」（第 1 个义项：深海平原所在的洋底）；句意为声呐揭示出洋底一片宽广的平原。图中可辨识物件：声呐缆、屏幕剖面、褐色平原、科考船。","pos":[{"tag":"n.","zh":"洋底；大洋底部（通常作单数，带定冠词）"}],"collocations":[{"phrase":"deep ocean floor","zh":"深海洋底"},{"phrase":"ocean floor spreading","zh":"洋底扩张"},{"phrase":"ocean floor sediment","zh":"洋底沉积物"},{"phrase":"ocean floor mapping","zh":"洋底测绘"},{"phrase":"ocean floor rocks","zh":"洋底岩石"},{"phrase":"the ocean floor","zh":"洋底（带定冠词的常用形式）"}],"forms":[{"label":"复数（少见）","form":"ocean floors"},{"label":"形容词形式","form":"ocean-floor"},{"label":"近义短语","form":"ocean bottom"},{"label":"近义复合词","form":"seafloor"},{"label":"相关术语","form":"oceanic crust"},{"label":"相关术语","form":"ocean basin"}],"derivatives":[{"word":"ocean-floor","pos":"adj.","zh":"洋底的"},{"word":"ocean bottom","pos":"n.","zh":"洋底（近义短语）"},{"word":"seafloor","pos":"n.","zh":"海底"},{"word":"oceanic crust","pos":"n.","zh":"洋壳"},{"word":"ocean basin","pos":"n.","zh":"洋盆"}],"senses":[{"no":"01","title":"Bottom of the open ocean","titleCN":"开阔大洋的底部","definition":"the bottom surface of the open ocean beyond the shelf and slope","definitionCN":"陆架与陆坡之外的开阔大洋底部表面","example":"The sonar revealed a wide plain on the ocean floor.","exampleCN":"声呐揭示出洋底一片宽广的平原。","why":"ocean names the open sea and floor names its bottom, so the phrase makes the deep setting explicit in a way seafloor need not.","whyCN":"ocean 指开阔海洋，floor 指其底部，因此这个短语比 seafloor 更明确地点出深海环境。"},{"no":"02","title":"Submarine relief","titleCN":"洋底地形","definition":"the shape of the deep bottom, including abyssal plains, hills, ridges and trenches","definitionCN":"深海底部的形状，包括深海平原、丘陵、海岭与海沟","example":"The map shows seamounts rising from the ocean floor.","exampleCN":"地图显示海山从洋底升起。","why":"once mapped, the deep bottom is read as landscape, so the phrase takes on a terrain sense.","whyCN":"一旦被测绘，深海底部就被读作地貌，因此这个短语带上了地形义。"},{"no":"03","title":"Surface of oceanic crust","titleCN":"洋壳的顶面","definition":"the upper boundary of the crust that lies under the open ocean","definitionCN":"开阔大洋之下洋壳的上边界","example":"Basalt makes up most of the ocean floor.","exampleCN":"玄武岩构成洋底的大部分。","why":"geology separates the water from the rock below, and that contact is the ocean floor.","whyCN":"地质学把水体与下方岩石分开，而二者的接触面就是洋底。"},{"no":"04","title":"Record of seafloor spreading","titleCN":"洋底扩张的记录面","definition":"the bottom as the archive of crust formed at mid-ocean ridges","definitionCN":"作为洋中脊所形成洋壳档案的底部","example":"Magnetic stripes on the ocean floor record reversals of the field.","exampleCN":"洋底的磁条带记录了地磁倒转。","why":"new bottom is created at ridges and moves outward, so the ocean floor carries a dated record of its own growth.","whyCN":"新的洋底在海岭生成并向外移动，因此洋底带着自身生长的可定年记录。"},{"no":"05","title":"Accumulated deep-sea sediment","titleCN":"洋底沉积物的堆积层","definition":"the layer of pelagic clay, ooze and debris that settles on the deep bottom","definitionCN":"沉降在深海底部的大洋黏土、软泥与碎屑层","example":"Slow accumulation covers much of the old ocean floor.","exampleCN":"缓慢的堆积覆盖了大部分古老洋底。","why":"the deep bottom is a quiet receiver of falling material, so the phrase also names the sediment cover.","whyCN":"深海底部安静地承接落下的物质，因此这个短语也指沉积覆盖层。"},{"no":"06","title":"Deep-sea habitat","titleCN":"深海栖息地","definition":"the environment of the deep bottom, including vent communities and soft-sediment fauna","definitionCN":"深海底部的环境，包括喷口群落与软沉积物动物群","example":"Life on the ocean floor survives without sunlight.","exampleCN":"洋底的生命在没有阳光的条件下存活。","why":"the deep floor is a place where organisms live, so the phrase can name a habitat rather than a rock surface.","whyCN":"深海底是生物生活的地方，因此这个短语可指栖息地而非岩石表面。"},{"no":"07","title":"Ground for deep-sea resources","titleCN":"深海资源所在的地面","definition":"the bottom considered as the site of nodules, crusts and other deep-sea deposits","definitionCN":"作为结核、结壳与其他深海矿床所在地的底部","example":"Nodules lie scattered across parts of the ocean floor.","exampleCN":"结核散落在洋底的一些区域。","why":"industry looks at the bottom as a store of minerals, adding a resource sense to the phrase.","whyCN":"工业把洋底看作矿产储藏，于是给这个短语添上资源义。"},{"no":"08","title":"Object of hydrographic survey","titleCN":"水文测绘的对象","definition":"the bottom as the target of echo sounding and bathymetric mapping","definitionCN":"作为回声测深与水深测绘目标的底部","example":"The survey vessel spent the summer mapping the ocean floor.","exampleCN":"勘测船花了一个夏天测绘洋底。","why":"surveying treats the deep bottom as a surface to be measured, which is a distinct practical sense.","whyCN":"测绘把深海底当作待测量的表面，这构成一个独立的实用义项。"}],"etymology":{"intro":{"en":"Ocean floor joins ocean, from Greek ōkeanos through Latin oceanus, with floor, from Old English flor 'ground, bottom'. The phrase belongs to modern oceanography. Dates are approximate.","cn":"ocean floor 由 ocean 与 floor 组合而成：ocean 经拉丁 oceanus 来自希腊 ōkeanos，floor 来自古英语 flor「地面、底部」。这个短语属于现代海洋学。年代均为约数。"},"items":[{"era":"GREEK ŌKEANOS","en":"Ōkeanos was the great river believed to encircle the world, and also its divine name. Its own origin is uncertain and may be non-Greek.","cn":"ōkeanos 是古人相信环绕大地的巨流，也是它的神名。它自身的来源不确定，可能并非希腊语。"},{"era":"LATIN OCEANUS","en":"Latin took the Greek word as oceanus, the outer sea, and passed it through French into English as ocean.","cn":"拉丁语把希腊词借作 oceanus，指外海，再经法语以 ocean 进入英语。"},{"era":"OLD ENGLISH FLOR","en":"Floor comes from Old English flor 'floor, ground, bottom', a Germanic word also used for the bottom of natural features.","cn":"floor 来自古英语 flor「地板、地面、底部」，这个日耳曼语词也用于自然事物的底部。"},{"era":"PHRASE FORMATION","en":"The phrase ocean floor became standard when nineteenth- and twentieth-century expeditions began systematic sounding of the deep sea.","cn":"十九与二十世纪的考察开始系统测深之后，ocean floor 这一短语成为标准说法。"},{"era":"PLATE TECTONICS","en":"With plate tectonics the phrase gained its modern geological reading: the top of oceanic crust and the record of spreading.","cn":"随着板块构造学说，这个短语获得现代地质含义：洋壳顶面与扩张记录。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of ōkeanos is unsettled, and the pre-Germanic root of floor is reconstructed rather than attested.","cn":"来源不确定：ōkeanos 的来源未有定论，floor 在日耳曼语之前的词根是重构而非有书证的形式。"}]},"similar":{"note":{"en":"Group one separates the oceanic terms that overlap with ocean floor; group two holds words for depth and bottom that differ in scope.","cn":"第一组区分与 ocean floor 重叠的海洋术语；第二组是表示深度与底部的词，范围不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seafloor","ipa":"/ˈsiːflɔː/","tag":"any sea bottom","definition":"The general term for any sea bottom; ocean floor usually points to the deep open ocean rather than a shelf sea.","definitionCN":"任何海洋底部的通称；ocean floor 通常指开阔深海，而非陆架浅海。"},{"word":"seabed","ipa":"/ˈsiːbed/","tag":"underwater land","definition":"The bottom viewed as land, common in law and industry; it lacks the deep-ocean focus of ocean floor.","definitionCN":"把底部视为土地的词，常见于法律与工业；它没有 ocean floor 那种深海指向。"},{"word":"oceanic crust","ipa":"/əʊˈsiːənɪk krʌst/","tag":"the rock, not the surface","definition":"The basalt-rich rock layer under the sea; its top is the ocean floor, but the crust includes the rock below.","definitionCN":"海底之下富含玄武岩的岩石层；它的顶面是洋底，但洋壳还包括下方岩石。"},{"word":"ocean basin","ipa":"/ˈəʊʃən ˈbeɪsən/","tag":"basin includes water","definition":"A large depression holding an ocean, including the water and the bottom; ocean floor names only the bottom surface.","definitionCN":"容纳大洋的大型洼地，包括水体与底部；ocean floor 只指底部表面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bottom","ipa":"/ˈbɒtəm/","tag":"general lowest part","definition":"The lowest part of anything; without ocean it could mean a box or a page.","definitionCN":"任何事物的最低部分；没有 ocean 时也可指箱子或书页的底部。"},{"word":"depths","ipa":"/depθs/","tag":"the water, not the base","definition":"The deep water as a region; it names the volume above the bottom.","definitionCN":"作为区域的深水；它指底部上方的水体积。"},{"word":"abyss","ipa":"/əˈbɪs/","tag":"the deepest zone","definition":"A bottomless or very deep place; it is more dramatic and less technical than ocean floor.","definitionCN":"无底或极深之处；比 ocean floor 更具戏剧性，也更不技术化。"},{"word":"deep sea","ipa":"/ˌdiːp ˈsiː/","tag":"the whole environment","definition":"The whole deep-water environment, including water and bottom; ocean floor selects only the base.","definitionCN":"整个深水环境，包括水与底部；ocean floor 只取基底。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ocean 'open sea' + floor 'bottom': the open sea given a floor.","cn":"ocean「开阔海洋」+ floor「底部」：给开阔海洋配一块地板。"},{"en":"The related terms run ocean floor, seafloor, seabed, ocean basin and oceanic crust.","cn":"相关术语包括 ocean floor、seafloor、seabed、ocean basin 与 oceanic crust。"},{"en":"Fixed phrases mark the science: ocean floor spreading, ocean floor sediment, ocean floor mapping.","cn":"固定搭配标出科学用法：洋底扩张、洋底沉积物、洋底测绘。"},{"en":"The phrase usually takes the definite article: on the ocean floor.","cn":"这个短语通常带定冠词：on the ocean floor。"},{"en":"It is the deep counterpart of continental shelf, the shallow shelf on the other side of the slope.","cn":"它是大陆架在深海的对应物，而大陆架位于陆坡的另一侧。"}],"abstract":[{"en":"Picture a brown plain so large that a ship above it seems to hang over nothing.","cn":"想象一片褐色平原大得让上方的船像悬在虚空之上。"},{"en":"Picture a library whose shelves are stripes of magnetised rock.","cn":"想象一座图书馆，书架由带磁的岩石条带做成。"},{"en":"Picture a darkness where animals make their own light.","cn":"想象一片黑暗，动物在那里自己发光。"}]},"examples":[{"en":"The expedition mapped a new section of the ocean floor.","cn":"考察队测绘了洋底的新区域。"},{"en":"Sediment on the ocean floor holds a long climate record.","cn":"洋底沉积物保存着漫长的气候记录。"},{"en":"The ridge raises new ocean floor above the surrounding plain.","cn":"海岭把新的洋底抬升到周围平原之上。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「ocean（大洋）+ floor（地板）」——大洋的地板就是洋底","word":"ocean floor"},"root":"ocean 经拉丁 oceanus 来自希腊 ōkeanos「环绕大地的巨流」，其来源不确定；floor 来自古英语 flor「地板、地面」；短语属现代海洋学用语，首见年代不确定。","sensesIntro":{"en":"Eight senses follow one deep floor: the open-ocean bottom, its relief, the crust below, the spreading record, the sediment cover, its life, its minerals and its role as a surveyed surface.","cn":"八个义项沿同一块深海底展开：开阔洋底、其起伏、其下洋壳、扩张记录、沉积覆盖、其生命、其矿产，以及其作为被测表面的角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: an enormous brown plain lying under miles of open water.","cn":"核心意象：数英里开阔水体之下的一片巨大褐色平原。"},"chain":["DEEP PLAIN","RELIEF","OCEANIC CRUST","SPREADING RECORD","SEDIMENT","RESOURCE"],"branches":[{"senses":"S1 · S5","en":"DEEP GROUND: the open bottom and the sediment that settles on it.","cn":"深部地面：开阔底部与沉降其上的沉积物。"},{"senses":"S2 · S3","en":"SHAPED ROCK: relief and crustal top are one surface seen two ways.","cn":"有形的岩石：地形与洋壳顶面是同一表面的两种看法。"},{"senses":"S4","en":"GROWING ARCHIVE: magnetic stripes date the bottom's own creation.","cn":"生长的档案：磁条带为洋底自身的生成定年。"},{"senses":"S6","en":"LIVING DEEP: vent communities and soft-bottom animals inhabit the floor.","cn":"活的深海：喷口群落与软底动物栖居其上。"},{"senses":"S7 · S8","en":"MEASURED STORE: the floor is both a mineral deposit and a survey target.","cn":"被测量的储藏：洋底既是矿床，也是测绘对象。"}]},"affixes":{"intro":{"en":"Ocean floor combines a Greek-derived noun with a Germanic one, so its family mixes classical compounds with plain English forms.","cn":"ocean floor 把一个希腊来源名词与一个日耳曼语名词组合起来，因此其词族混合了古典复合词与朴素英语形式。"},"latinIntro":{"en":"Greek ōkeanos passed into Latin as oceanus, which gives ocean and oceanic; floor is Germanic and contributes no Latin entry.","cn":"希腊 ōkeanos 进入拉丁语作 oceanus，由此衍生 ocean 与 oceanic；floor 属日耳曼语，不提供拉丁条目。"},"items":[{"word":"ocean","structure":"ocean (from Greek ōkeanos via Latin oceanus)","meaning":"the open sea","meaningCN":"开阔海洋","example":"The ocean stretched beyond the horizon.","exampleCN":"海洋一直延伸到地平线之外。"},{"word":"floor","structure":"Old English flor (noun, 'floor, ground')","meaning":"bottom surface","meaningCN":"底部表面","example":"The floor of the valley was flat.","exampleCN":"谷底是平的。"},{"word":"ocean floor","structure":"ocean + floor (noun phrase)","meaning":"the bottom of the open ocean","meaningCN":"开阔大洋的底部","example":"The probe reached the ocean floor.","exampleCN":"探测器抵达洋底。"},{"word":"ocean-floor","structure":"ocean floor + hyphen (attributive adjective)","meaning":"of the ocean bottom","meaningCN":"洋底的","example":"Ocean-floor rocks are mostly basalt.","exampleCN":"洋底岩石主要是玄武岩。"},{"word":"oceanic","structure":"ocean + -ic (adjective)","meaning":"of the ocean","meaningCN":"海洋的","example":"Oceanic currents move heat poleward.","exampleCN":"洋流把热量送往极地。"},{"word":"oceanography","structure":"ocean + -graphy (description, study)","meaning":"the study of the sea","meaningCN":"海洋学","example":"She studied oceanography at the coastal institute.","exampleCN":"她在海岸研究所学习海洋学。"},{"word":"ocean basin","structure":"ocean + basin (compound noun)","meaning":"a large depression holding an ocean","meaningCN":"容纳大洋的大型洼地；洋盆","example":"The Pacific is the deepest ocean basin.","exampleCN":"太平洋是最深的洋盆。"},{"word":"Oceanus","structure":"Oceanus (Latin proper noun from Greek ōkeanos)","meaning":"the encircling river of Greek myth","meaningCN":"希腊神话中环绕大地的巨流","example":"Oceanus was imagined as a river around the world.","exampleCN":"古人把 oceanus 想象成环绕世界的河流。"}],"latinEntries":[{"word":"oceanus","structure":"oceanus, oceanus (m., fourth declension)","meaning":"the outer sea; the god Oceanus","meaningCN":"外海；海神俄刻阿诺斯"},{"word":"Oceanus","structure":"Oceanus (proper noun, from Greek ōkeanos)","meaning":"the river encircling the world","meaningCN":"环绕世界的巨流"}]}},{"word":"abyss","ipa_uk":"/əˈbɪs/","ipa_us":"/əˈbɪs/","definition_zh":"深渊；深海；深不可测之处；巨大鸿沟","definition_en":"a bottomless or extremely deep opening, the deep sea, or a vast unmeasurable gap between things","core_image":"一道向下的裂口，边缘的灯光照不到底，只见黑色一层深过一层","scene":"洞口往下看不见底，丢下的石子很久才回声。 They lowered a probe into the abyss and waited for the echo.","sceneCN":"这里 abyss 指「深不见底的裂口或深处」（第 1 个义项：无底的深洞）；句意为他们把探测器放进深渊，等待回声。图中可辨识物件：洞口边缘、下坠的探测器、黑暗的竖壁、远处微光。","pos":[{"tag":"n.","zh":"深渊；深海；深不可测之处；（抽象的）巨大鸿沟"}],"collocations":[{"phrase":"the depths of the abyss","zh":"深渊深处"},{"phrase":"peer into the abyss","zh":"凝视深渊"},{"phrase":"the abyss between rich and poor","zh":"贫富之间的巨大鸿沟"},{"phrase":"fall into an abyss","zh":"跌入深渊"},{"phrase":"oceanic abyss","zh":"海洋深渊"},{"phrase":"abyss of despair","zh":"绝望的深渊"}],"forms":[{"label":"复数","form":"abysses"},{"label":"形容词（深海的；深渊的）","form":"abyssal"},{"label":"形容词（深不可测的；糟糕的）","form":"abysmal"},{"label":"名词（深渊，古旧变体）","form":"abysm"},{"label":"副词（深不可测地）","form":"abysmally"},{"label":"相关术语（深渊带的）","form":"abyssopelagic"}],"derivatives":[{"word":"abyssal","pos":"adj.","zh":"深海的；深渊的"},{"word":"abysmal","pos":"adj.","zh":"深不可测的；极糟糕的"},{"word":"abysmally","pos":"adv.","zh":"极糟糕地"},{"word":"abysm","pos":"n.","zh":"深渊（古旧变体）"},{"word":"abyssopelagic","pos":"adj.","zh":"深渊水层的"}],"senses":[{"no":"01","title":"A bottomless opening","titleCN":"深不见底的裂口","definition":"an extremely deep hole or gorge whose bottom cannot be seen or reached","definitionCN":"极深、看不见也到不了底的洞口或峡谷","example":"They lowered a probe into the abyss and waited for the echo.","exampleCN":"他们把探测器放进深渊，等待回声。","why":"abyss comes from Greek abyssos 'bottomless', built from a- 'not' plus byssos 'bottom', so the word denies that a bottom exists.","whyCN":"abyss 来自希腊 abyssos「无底的」，由 a-「不」加 byssos「底」构成，因此这个词从构词上就否认底的存在。"},{"no":"02","title":"The deep sea","titleCN":"深海；深渊海域","definition":"the deepest part of the ocean, far below the reach of sunlight","definitionCN":"海洋最深的部分，远在阳光照不到的地方","example":"Creatures of the abyss make their own light.","exampleCN":"深渊里的生物自己发光。","why":"the ocean's deepest zone is the literal bottomless place on earth, so the old word was applied to it directly.","whyCN":"海洋最深带是地球上最字面意义的无底之处，因此这个古老的词被直接用于它。"},{"no":"03","title":"A great depth or drop","titleCN":"极深的落差与深处","definition":"an overwhelming depth or vertical distance, as below a cliff or a shaft","definitionCN":"悬崖或竖井下方令人眩晕的深度或垂直距离","example":"The climber stared down into the abyss below the ridge.","exampleCN":"攀登者向下望进山脊之下的深渊。","why":"any place that seems to have no floor earns the name, even when the drop can be measured.","whyCN":"任何看似没有底的地方都能得到这个名称，即使落差其实可以测量。"},{"no":"04","title":"Immeasurable depth of knowledge or time","titleCN":"知识或时间的深不可测","definition":"a vast, unknowable extent of knowledge, history or time","definitionCN":"知识、历史或时间上广阔而不可知的深度","example":"The abyss of geological time opened before the students.","exampleCN":"地质时间的深渊在学生们面前展开。","why":"what cannot be sounded with a line is felt as an abyss, and abstract vastness borrows the same image.","whyCN":"用测深线探不到的东西就被感受为深渊，抽象的浩瀚借用了同一意象。"},{"no":"05","title":"Despair as a pit","titleCN":"绝望的深渊","definition":"a state of hopelessness felt as falling into a pit","definitionCN":"一种像跌入深坑般的无望状态","example":"After the third refusal he sank into an abyss of despair.","exampleCN":"第三次被拒之后，他陷入绝望的深渊。","why":"emotions are described with spatial images, and hopelessness is one of the most common pits.","whyCN":"情绪常用空间意象描述，而绝望是最常见的深坑之一。"},{"no":"06","title":"A vast gap between things","titleCN":"事物之间的巨大鸿沟","definition":"an immense difference or separation that seems impossible to cross","definitionCN":"大到似乎无法跨越的差异或隔阂","example":"An abyss separates the two sides of the debate.","exampleCN":"一道巨大鸿沟横在辩论的两方之间。","why":"a gap with no bridge is pictured as a chasm, so differences in wealth, belief or understanding become abysses.","whyCN":"没有桥的间隔被想象为裂隙，因此财富、信念或理解上的差异都成了深渊。"},{"no":"07","title":"The underworld of myth","titleCN":"神话与宗教中的冥府深渊","definition":"the underworld or a place of punishment imagined as a deep pit","definitionCN":"被想象为深坑的冥府或惩罚之地","example":"In the old story the dead were cast into the abyss.","exampleCN":"在古老的故事里，死者被投入深渊。","why":"religious language placed the realm of the dead below the earth, and abyss became one of its names.","whyCN":"宗教语言把亡者之境放在大地之下，abyss 便成了它的名称之一。"},{"no":"08","title":"The unknown beyond knowing","titleCN":"未知的深不可测领域","definition":"the region of what cannot be known or explored, imagined as a depth","definitionCN":"无法认识或探索的领域，被想象为一种深度","example":"The question opened an abyss of unknowns no theory could fill.","exampleCN":"这个问题打开了一个任何理论都填不满的未知深渊。","why":"the most abstract sense uses the image for the limits of understanding rather than for any physical place.","whyCN":"最抽象的义项把这个意象用于认识的边界，而非任何实体场所。"}],"etymology":{"intro":{"en":"Abyss comes from Greek abyssos 'bottomless, unfathomable', from a- 'not' plus byssos 'bottom, depth'. It reached English through Latin abyssus and Old French. Dates are approximate.","cn":"abyss 来自希腊 abyssos「无底的、不可测的」，由 a-「不」加 byssos「底、深度」构成。它经拉丁 abyssus 与古法语进入英语。年代均为约数。"},"items":[{"era":"GREEK BYSSOS","en":"Byssos meant 'bottom, depth'. A link with bathys 'deep' has been suggested, but the two forms are not certainly related.","cn":"byssos 意为「底、深度」。有人提出它与 bathys「深的」有关，但两种形式未必同源。"},{"era":"GREEK ABYSSOS","en":"The privative prefix a- 'not' plus byssos produced abyssos 'bottomless', first used of the sea and of the underworld.","cn":"否定前缀 a-「不」加 byssos 构成 abyssos「无底的」，最初用于海与冥府。"},{"era":"LATIN ABYSSUS","en":"Latin borrowed the Greek word as abyssus, used both for the deep sea and for the abode of the dead.","cn":"拉丁语借入希腊词作 abyssus，既指深海，也指亡者居所。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French abisme carried the word into English, where abyss settled as the learned form beside the older abysm.","cn":"古法语 abisme 把这个词带入英语，abyss 作为学术形式与更旧的 abysm 并存而定型。"},{"era":"FIGURATIVE USE","en":"The senses of despair, vast difference and unknowable depth are later metaphors built on the physical pit.","cn":"绝望、巨大差异与不可知之深这些义项都是后来建立在实体深坑之上的比喻。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Greek origin of byssos is unsettled, and the suggested link to bathys remains a hypothesis rather than a proven derivation.","cn":"来源不确定：byssos 在希腊语之前的来源未有定论，所提出的与 bathys 的联系仍只是假说，并非已证实的派生。"}]},"similar":{"note":{"en":"Group one separates abyss from its adjectives and its archaic doublet; group two holds near synonyms for a deep opening or a wide gap.","cn":"第一组把 abyss 与其形容词、古旧同源变体分开；第二组是表示深洞或宽阔裂隙的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"abyssal","ipa":"/əˈbɪsəl/","tag":"the adjective","definition":"An adjective meaning 'of the abyss' or 'of the deep sea'; it describes a zone or a depth, while abyss names the place.","definitionCN":"意为「深渊的、深海的」形容词，描述区域或深度；abyss 则指这个地方。"},{"word":"abysmal","ipa":"/əˈbɪzməl/","tag":"bad, not deep","definition":"Built on abysm, it means 'extremely bad' in modern use; it no longer means literally bottomless.","definitionCN":"建立在 abysm 之上，现代义为「极糟糕的」；它已不再字面地表示无底。"},{"word":"abysm","ipa":"/əˈbɪzəm/","tag":"archaic doublet","definition":"An older English form from Old French abisme, now poetic or archaic; it is a doublet of abyss, not a different feature.","definitionCN":"来自古法语 abisme 的较旧英语形式，今多用于诗歌或古语；它是 abyss 的同源变体，并非另一种事物。"},{"word":"abyssopelagic","ipa":"/əˌbɪsəˈpəlædʒɪk/","tag":"technical zone term","definition":"A compound naming the water layer above the deepest bottom; it is a zone adjective, not a synonym of the pit.","definitionCN":"指最深底部上方水层的复合术语；它是区域形容词，并非深坑的同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chasm","ipa":"/ˈkæzəm/","tag":"a split in rock","definition":"A deep, narrow opening in rock or ground; abyss stresses unmeasurable depth rather than narrowness.","definitionCN":"岩石或地面中深而窄的裂口；abyss 更强调不可测的深度，而非狭窄。"},{"word":"gulf","ipa":"/ɡʌlf/","tag":"wide separation","definition":"A large bay, or a wide separation between people; it is broader and less vertical than an abyss.","definitionCN":"大片海湾，或人与人之间的宽阔隔阂；比 abyss 更宽，也更少垂直感。"},{"word":"void","ipa":"/vɔɪd/","tag":"emptiness","definition":"An empty space or a lack of something; it stresses absence rather than depth.","definitionCN":"空无一物的空间或某物的缺失；强调空，而非深。"},{"word":"depth","ipa":"/depθ/","tag":"measurable distance","definition":"A measurable distance downward or inward; an abyss is a depth that defeats measurement.","definitionCN":"可测量的向下或向内距离；深渊是使测量失效的深度。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"a- 'not' + byssos 'bottom': literally 'bottomless'.","cn":"a-「不」+ byssos「底」：字面就是「没有底」。"},{"en":"The family runs abyss, abyssal, abysmal, abysm, abyssopelagic.","cn":"同族词包括 abyss、abyssal、abysmal、abysm、abyssopelagic。"},{"en":"Fixed phrases mark the abstract senses: an abyss of despair, the abyss between rich and poor.","cn":"固定搭配标出抽象义：绝望的深渊、贫富之间的鸿沟。"},{"en":"Oceanography names the deepest water layer the abyssopelagic zone.","cn":"海洋学把最深水层称为深渊水层。"},{"en":"The word appears in myth for the place of the dead, not only for the sea.","cn":"这个词在神话中也指亡者之地，不只指海。"}],"abstract":[{"en":"Picture a rope dropped into a hole that never reports a floor.","cn":"想象一根绳子放进洞里，永远探不到底。"},{"en":"Picture a library that grows a new shelf for every question you answer.","cn":"想象一座图书馆，你每回答一个问题它就多长出一层书架。"},{"en":"Picture two cliffs facing each other with no bridge and no wind to carry a voice.","cn":"想象两座悬崖相对，没有桥，也没有风可以传声。"}]},"examples":[{"en":"The submarine descended into the abyss.","cn":"潜艇下潜进入深渊。"},{"en":"She felt she was standing at the edge of an abyss.","cn":"她觉得自己正站在深渊边缘。"},{"en":"The report exposed the abyss between policy and practice.","cn":"报告揭示了政策与实践之间的巨大鸿沟。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「a（不）+ byss（底）」——没有底的地方 → 深渊、深海、鸿沟","word":"abyss"},"root":"希腊 abyssos「无底的」= a-（不）+ byssos（底、深度），经拉丁 abyssus 与古法语进入英语；byssos 更深来源不确定，与 bathys「深的」的联系仅为假说。","sensesIntro":{"en":"Eight senses follow one pit: a hole with no visible bottom, the deep sea, any immense drop, and then the same image is lent to unknowable time, despair, vast difference, the underworld and the limits of knowledge.","cn":"八个义项沿同一个深坑展开：看不见底的洞、深海、任何巨大的落差，随后同一意象被借给不可知的时间、绝望、巨大差异、冥府与认识的边界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dark shaft whose bottom no light reaches.","cn":"核心意象：一道没有任何光能照到底的黑暗竖井。"},"chain":["BOTTOMLESS PIT","DEEP SEA","GREAT DROP","DESPAIR","VAST GAP","UNKNOWN"],"branches":[{"senses":"S1 · S3","en":"PHYSICAL DEPTH: a hole and any dizzying drop.","cn":"实体深度：一个洞与任何令人眩晕的落差。"},{"senses":"S2","en":"OCEANIC DEEP: the sea's deepest zone is the literal bottomless place.","cn":"海洋深处：海洋最深带就是字面上的无底之处。"},{"senses":"S4 · S8","en":"UNSOUNDABLE EXTENT: time and the unknown defeat measurement.","cn":"无法测度的范围：时间与未知使测量失效。"},{"senses":"S5","en":"INNER PIT: hopelessness is felt as falling.","cn":"内心深坑：无望被感受为下坠。"},{"senses":"S6 · S7","en":"SEPARATION AND UNDERWORLD: a wide gap and the realm below.","cn":"隔阂与冥府：宽阔的裂隙与下方之境。"}]},"affixes":{"intro":{"en":"Abyss is a Greek compound of a negative prefix and a noun for 'bottom', so its morphology states its meaning outright.","cn":"abyss 是希腊语复合词，由否定前缀与表示「底」的名词构成，因此其形态直接把意思说了出来。"},"latinIntro":{"en":"Greek abyssos passed into Latin as abyssus, which gives English abyss and the adjectives abyssal and abysmal.","cn":"希腊 abyssos 进入拉丁语作 abyssus，由此衍生英语 abyss 以及形容词 abyssal 与 abysmal。"},"items":[{"word":"a-","structure":"a- (Greek privative prefix, 'not, without')","meaning":"not; without","meaningCN":"不；无","example":"The prefix negates the noun it joins.","exampleCN":"这个前缀否定它所连接的名词。"},{"word":"byssos","structure":"byssos (Greek noun, 'bottom, depth')","meaning":"bottom; depth","meaningCN":"底；深度","example":"The noun names the floor of a deep place.","exampleCN":"这个名词指深处的地面。"},{"word":"abyssos","structure":"a- + byssos (Greek adjective)","meaning":"bottomless, unfathomable","meaningCN":"无底的；不可测的","example":"The sea was called abyssos in old texts.","exampleCN":"古籍中把海称为无底之物。"},{"word":"abyssus","structure":"abyssus, abyssi (Latin noun, from Greek)","meaning":"the deep sea; the underworld","meaningCN":"深海；冥府","example":"Latin writers used abyssus for the deep.","exampleCN":"拉丁作家用 abyssus 指深处。"},{"word":"abyss","structure":"abyssus + English form","meaning":"a bottomless depth","meaningCN":"无底的深处；深渊","example":"The pit opened into an abyss.","exampleCN":"坑洞向下敞开成深渊。"},{"word":"abyssal","structure":"abyss + -al (adjective)","meaning":"of the abyss or the deep sea","meaningCN":"深渊的；深海的","example":"Abyssal plains cover much of the sea bottom.","exampleCN":"深海平原覆盖了大部分海底。"},{"word":"abysmal","structure":"abysm + -al (adjective)","meaning":"bottomless; hence extremely bad","meaningCN":"无底的；引申为极糟糕的","example":"The service was abysmal.","exampleCN":"服务糟糕透顶。"},{"word":"abysm","structure":"Old French abisme (noun)","meaning":"an abyss (archaic)","meaningCN":"深渊（古旧形式）","example":"The poet spoke of an abysm of light.","exampleCN":"诗人说到光的深渊。"}],"latinEntries":[{"word":"abyssus","structure":"abyssus, abyssi (m., second declension)","meaning":"the deep, the abyss","meaningCN":"深处；深渊"},{"word":"abyssos","structure":"abyssos (Greek adjective and noun)","meaning":"bottomless; the deep","meaningCN":"无底的；深处"},{"word":"abyssalis","structure":"abyssalis, abyssale (adj., third declension)","meaning":"of the abyss","meaningCN":"深渊的"}]}},{"word":"abyssal","ipa_uk":"/əˈbɪsəl/","ipa_us":"/əˈbɪsəl/","definition_zh":"深海的；深渊带的；无底的；深不可测的","definition_en":"relating to the deepest part of the ocean or to an abyss, or figuratively meaning unfathomably deep","core_image":"探照灯的光柱在漆黑水里只照出一小片悬浮的白色颗粒，下方仍是没有尽头的黑","scene":"深海的探测器在黑暗里拍到了一只苍白的小虾。 The abyssal zone receives no sunlight at all.","sceneCN":"这里 abyssal 指「属于深海深渊带的」（第 2 个义项：海洋深渊带的）；句意为深渊带完全接收不到阳光。图中可辨识物件：探照灯光柱、悬浮颗粒、苍白的小虾、漆黑水体。","pos":[{"tag":"adj.","zh":"深海的；深渊带的；无底的；深不可测的"}],"collocations":[{"phrase":"abyssal zone","zh":"深渊带"},{"phrase":"abyssal plain","zh":"深海平原"},{"phrase":"abyssal sediment","zh":"深海沉积物"},{"phrase":"abyssal fauna","zh":"深海动物群"},{"phrase":"abyssal depths","zh":"深渊深处"},{"phrase":"abyssal circulation","zh":"深层环流"}],"forms":[{"label":"比较级","form":"more abyssal"},{"label":"最高级","form":"most abyssal"},{"label":"名词（深渊；深海）","form":"abyss"},{"label":"名词（深渊，古旧变体）","form":"abysm"},{"label":"形容词（极糟糕的；深不可测的）","form":"abysmal"},{"label":"副词（极糟糕地）","form":"abysmally"}],"derivatives":[{"word":"abyss","pos":"n.","zh":"深渊；深海"},{"word":"abysm","pos":"n.","zh":"深渊（古旧变体）"},{"word":"abysmal","pos":"adj.","zh":"极糟糕的；深不可测的"},{"word":"abysmally","pos":"adv.","zh":"极糟糕地"},{"word":"abyssopelagic","pos":"adj.","zh":"深渊水层的"}],"senses":[{"no":"01","title":"Literally bottomless","titleCN":"字面义：无底的、深不见底的","definition":"having no measurable bottom; extremely and seemingly endless in depth","definitionCN":"没有可测量的底部；深得看似没有尽头","example":"The shaft looked abyssal, a black line cut into the rock.","exampleCN":"那口竖井像无底一般，是岩石上切开的一道黑线。","why":"abyssal is simply the adjective of abyss, which comes from Greek abyssos 'bottomless', so the literal meaning is 'having the nature of a bottomless place'.","whyCN":"abyssal 就是 abyss 的形容词，而 abyss 来自希腊 abyssos「无底的」，因此字面义是「具有无底之处性质的」。"},{"no":"02","title":"Of the abyssal zone","titleCN":"海洋深渊带的","definition":"belonging to the deep ocean zone roughly between four and six thousand metres","definitionCN":"属于大约四千米到六千米深的海洋水层","example":"The abyssal zone receives no sunlight at all.","exampleCN":"深渊带完全接收不到阳光。","why":"oceanography fixed abyssal as the name of a depth zone, turning a poetic word into a measured label.","whyCN":"海洋学把 abyssal 固定为一个深度带的名称，使这个诗意的词变成可测量的标签。"},{"no":"03","title":"Of the abyssal plain","titleCN":"深海平原的","definition":"describing the broad, nearly flat surfaces of the deepest ocean floor","definitionCN":"描述最深洋底上宽阔而近乎平坦的表面","example":"Turbidites spread across the abyssal plain after the slope collapsed.","exampleCN":"陆坡崩塌后，浊流沉积铺满深海平原。","why":"the plain is the flattest part of the abyss, so the adjective naturally names its landform.","whyCN":"平原是深渊中最平坦的部分，因此这个形容词自然用来指它的地貌。"},{"no":"04","title":"Of deep-sea sediment","titleCN":"深海沉积物的","definition":"describing the fine oozes and clays that accumulate on the deepest bottom","definitionCN":"描述堆积在最深底部上的细软泥与黏土","example":"Abyssal sediment accumulates only a few millimetres per thousand years.","exampleCN":"深海沉积物每一千年只堆积几毫米。","why":"the sediment is the slow skin of the abyss, so the adjective marks material formed in that setting.","whyCN":"沉积物是深渊缓慢形成的表皮，因此这个形容词标示在该环境中形成的物质。"},{"no":"05","title":"Of deep-sea life","titleCN":"深海生物的","definition":"describing organisms that live in the deepest water and on its bottom","definitionCN":"描述生活在最深水体及其底部的生物","example":"Abyssal fauna depend on organic matter falling from above.","exampleCN":"深海动物群依赖从上方落下的有机物。","why":"life adapted to darkness and pressure is named by the zone it inhabits.","whyCN":"适应黑暗与高压的生命，以其栖息的水层命名。"},{"no":"06","title":"At great ocean depth","titleCN":"极深水域的","definition":"occurring at very great depth in the sea, without reference to a strict zone boundary","definitionCN":"发生在海中极深之处，不严格限定于某一水层边界","example":"Abyssal currents move cold water slowly toward the equator.","exampleCN":"深层水流把冷水缓慢推向赤道。","why":"outside technical writing the adjective simply means 'very deep', which keeps the older literal sense alive.","whyCN":"在技术写作之外，这个形容词只表示「极深的」，使较早的字面义继续存活。"},{"no":"07","title":"Of deep-ocean circulation","titleCN":"深层海水环流的","definition":"describing the slow movement of dense water in the deep ocean","definitionCN":"描述深海中高密度海水的缓慢运动","example":"Abyssal circulation carries oxygen to the deepest basins.","exampleCN":"深层环流把氧气带到最深的海盆。","why":"physical oceanography uses the adjective for the water mass itself, not only for the bottom.","whyCN":"物理海洋学用这个形容词指水团本身，而不只是底部。"},{"no":"08","title":"Figuratively unfathomable","titleCN":"抽象义：深不可测的、难理解的","definition":"so profound or obscure that it cannot be understood or measured","definitionCN":"深奥或晦涩到无法理解或衡量","example":"The abyssal silence of the archive unsettled the researcher.","exampleCN":"档案库深不可测的寂静让研究者不安。","why":"the adjective keeps the metaphor of depth for anything whose extent cannot be sounded.","whyCN":"这个形容词把深度的比喻保留给任何无法测知其范围的事物。"}],"etymology":{"intro":{"en":"Abyssal is the English adjective of abyss, formed with -al on a noun that goes back through Latin abyssus to Greek abyssos 'bottomless'. The oceanographic sense is modern. Dates are approximate.","cn":"abyssal 是 abyss 的英语形容词，由名词加 -al 构成；该名词经拉丁 abyssus 上溯到希腊 abyssos「无底的」。海洋学义属现代。年代均为约数。"},"items":[{"era":"GREEK ABYSSOS","en":"Abyssos meant 'bottomless', from a- 'not' plus byssos 'bottom'. It described the sea and the underworld before it described any measured zone.","cn":"abyssos 意为「无底的」，由 a-「不」加 byssos「底」构成。它先描述海与冥府，后来才描述可测量的水层。"},{"era":"LATIN ABYSSUS","en":"Latin abyssus carried the noun into learned use; a Latin adjective abyssalis is recorded in later technical writing.","cn":"拉丁 abyssus 把这个名词带入学术用法；后期的技术写作中可见拉丁形容词 abyssalis。"},{"era":"ENGLISH ADJECTIVE","en":"English formed abyssal on abyss with the native adjective suffix -al, first in the literal sense 'bottomless'.","cn":"英语用 abyss 加本族形容词后缀 -al 构成 abyssal，最初取「无底的」字面义。"},{"era":"OCEANOGRAPHIC SENSE","en":"Late nineteenth-century deep-sea expeditions gave abyssal its modern zone sense, fixed in the twentieth century.","cn":"十九世纪末的深海考察赋予 abyssal 现代水层义，并在二十世纪固定下来。"},{"era":"EXTENDED USE","en":"The figurative sense for anything unfathomable grew from the literal depth and remains common in literary prose.","cn":"用于任何不可测之物的比喻义由字面深度引申而来，至今在文学散文中常见。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Greek origin of byssos is unsettled, and the exact date when abyssal entered English is given only approximately.","cn":"来源不确定：byssos 在希腊语之前的来源未有定论，abyssal 进入英语的确切年代也只能给出约数。"}]},"similar":{"note":{"en":"Group one separates abyssal from the other members of its own family; group two holds depth adjectives from oceanography and general prose.","cn":"第一组把 abyssal 与其同族其他成员分开；第二组是海洋学与一般散文中的深度形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"abyss","ipa":"/əˈbɪs/","tag":"the noun","definition":"The noun names the deep place; abyssal is the adjective that describes something belonging to it.","definitionCN":"名词指深处这个地方；abyssal 是描述属于该处之物的形容词。"},{"word":"abysmal","ipa":"/əˈbɪzməl/","tag":"extremely bad","definition":"Formed on the older abysm, it now means 'very bad' and is not a neutral depth adjective.","definitionCN":"建立在较旧的 abysm 之上，今义为「极糟糕的」，并非中性的深度形容词。"},{"word":"abysm","ipa":"/əˈbɪzəm/","tag":"archaic noun","definition":"An archaic or poetic noun for an abyss; it is a doublet, not an adjective.","definitionCN":"指深渊的古语或诗歌名词；它是同源变体，并非形容词。"},{"word":"abyssopelagic","ipa":"/əˌbɪsəˈpəlædʒɪk/","tag":"water-layer term","definition":"A technical adjective for the water layer above the deepest bottom; abyssal can describe both water and bottom.","definitionCN":"指最深底部上方水层的技术形容词；abyssal 既可描述水体，也可描述底部。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deep-sea","ipa":"/ˌdiːp ˈsiː/","tag":"general compound","definition":"A broad everyday compound for the deep ocean; abyssal is narrower and more technical.","definitionCN":"泛指深海的常用复合词；abyssal 更窄也更技术化。"},{"word":"hadal","ipa":"/ˈheɪdəl/","tag":"trench zone","definition":"Of the deepest trenches below six thousand metres; it is deeper than the abyssal zone and named after Hades.","definitionCN":"指六千米以下最深海沟的；比深渊带更深，词源出自冥王哈得斯。"},{"word":"benthic","ipa":"/ˈbentɪk/","tag":"bottom-dwelling","definition":"Of the bottom itself, at any depth; abyssal adds the specific depth range.","definitionCN":"指底部本身的，不限深度；abyssal 另加特定的深度范围。"},{"word":"profound","ipa":"/prəˈfaʊnd/","tag":"abstract depth","definition":"Deep in feeling or thought; it is the general abstract adjective where abyssal is the dramatic metaphor.","definitionCN":"指情感或思想深沉的；它是通用抽象形容词，而 abyssal 是更具戏剧性的比喻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"abyss + -al: 'having the nature of the abyss'.","cn":"abyss + -al：「具有深渊性质的」。"},{"en":"The family runs abyss, abyssal, abysmal, abysm, abyssopelagic.","cn":"同族词包括 abyss、abyssal、abysmal、abysm、abyssopelagic。"},{"en":"Fixed phrases mark the science: abyssal zone, abyssal plain, abyssal sediment, abyssal fauna.","cn":"固定搭配标出科学用法：深渊带、深海平原、深海沉积物、深海动物群。"},{"en":"The zone lies roughly between four and six thousand metres, below the bathyal and above the hadal.","cn":"这一水层大致位于四千米到六千米之间，在次深海带之下、超深渊带之上。"},{"en":"The adjective is paired with plain more often than with any other landform.","cn":"这个形容词最常搭配的地貌词是 plain（平原）。"}],"abstract":[{"en":"Picture a lamp that lights only one metre of water and leaves the rest black.","cn":"想象一盏灯只照亮一米水体，其余全是黑的。"},{"en":"Picture a snowfall that takes a thousand years to make a layer as thick as a coin.","cn":"想象一场雪下了一千年，才积起一枚硬币厚的层。"},{"en":"Picture a silence so deep that a single sound would travel for hours.","cn":"想象一种深得让单个声音要走几个小时才能传到的寂静。"}]},"examples":[{"en":"Abyssal temperatures stay just above freezing.","cn":"深渊带的温度只略高于冰点。"},{"en":"The abyssal plain stretched for hundreds of kilometres.","cn":"深海平原延伸数百公里。"},{"en":"The novel describes an abyssal loneliness.","cn":"这部小说描写了一种深不可测的孤独。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「abyss（深渊）+ al（形容词）」——属于深渊的 → 深海的、深渊的、深不可测的","word":"abyssal"},"root":"abyss 加形容词后缀 -al；abyss 来自希腊 abyssos「无底的」= a-（不）+ byssos（底），经拉丁 abyssus 进入英语；byssos 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one adjective: literally bottomless, then the measured deep zone, its plain, its sediment, its life, great depth in general, deep circulation, and finally the figurative sense of anything unfathomable.","cn":"八个义项沿同一个形容词展开：字面「无底」，接着是可测量的深渊带、其平原、其沉积物、其生命、泛指的极深、深层环流，最后是任何不可测之物的比喻义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lamp beam that lights one small patch of black water.","cn":"核心意象：一道灯光只照亮黑水中很小的一片。"},"chain":["NO BOTTOM","ABYSSAL ZONE","ABYSSAL PLAIN","ABYSSAL SEDIMENT","ABYSSAL LIFE","PROFOUND DEPTH"],"branches":[{"senses":"S1 · S6","en":"UNMEASURED DEPTH: the literal no-bottom idea and the general 'very deep' use.","cn":"未测的深度：字面的无底与泛指的「极深」。"},{"senses":"S2","en":"NAMED ZONE: a measured layer with a formal boundary.","cn":"有名水层：具有正式边界、可测量的层。"},{"senses":"S3 · S4","en":"FLAT AND SLOW: the plain and the sediment built by millennia.","cn":"平坦而缓慢：平原与千年堆积的沉积物。"},{"senses":"S5 · S7","en":"LIFE AND WATER: fauna adapted to darkness, and the circulation that feeds it.","cn":"生命与水：适应黑暗的动物群，以及供养它们的环流。"},{"senses":"S8","en":"METAPHOR: any silence or mystery that cannot be sounded.","cn":"比喻：任何无法测知的寂静或奥秘。"}]},"affixes":{"intro":{"en":"Abyssal joins the noun abyss to the adjective suffix -al; the noun itself is a Greek negative compound, so the whole word can be read in three pieces.","cn":"abyssal 把名词 abyss 与形容词后缀 -al 连接起来；名词本身是希腊否定复合词，因此整词可分三段读出。"},"latinIntro":{"en":"Greek abyssos became Latin abyssus and later abyssalis; English keeps abyss and builds abyssal with the native suffix -al.","cn":"希腊 abyssos 变为拉丁 abyssus，后来又有 abyssalis；英语保留 abyss，并用本族后缀 -al 构成 abyssal。"},"items":[{"word":"a-","structure":"a- (Greek privative prefix, 'not')","meaning":"not; without","meaningCN":"不；无","example":"The prefix denies the noun it joins.","exampleCN":"这个前缀否定所连接的名词。"},{"word":"byssos","structure":"byssos (Greek noun, 'bottom')","meaning":"bottom; depth","meaningCN":"底；深度","example":"The noun names the floor of a deep place.","exampleCN":"这个名词指深处的底面。"},{"word":"abyss","structure":"a- + byssos (noun)","meaning":"a bottomless depth","meaningCN":"无底的深处；深渊","example":"The crevasse opened into an abyss.","exampleCN":"冰隙向下敞开成深渊。"},{"word":"-al","structure":"-al (English adjective suffix from Latin -alis)","meaning":"pertaining to","meaningCN":"与……有关的","example":"The suffix turns a noun into an adjective of relation.","exampleCN":"这个后缀把名词变成表关系的形容词。"},{"word":"abyssal","structure":"abyss + -al","meaning":"of the abyss or the deep sea","meaningCN":"深渊的；深海的","example":"Abyssal water stays cold all year.","exampleCN":"深渊带的水全年寒冷。"},{"word":"abyssal plain","structure":"abyssal + plain (compound term)","meaning":"a flat expanse of deep ocean floor","meaningCN":"深海洋底的平坦区域；深海平原","example":"The abyssal plain lay far below the ship.","exampleCN":"深海平原远在船下。"},{"word":"abyssal zone","structure":"abyssal + zone (compound term)","meaning":"the deep water layer of the open ocean","meaningCN":"开阔大洋的深渊水层","example":"Few species live in the abyssal zone.","exampleCN":"深渊带中物种很少。"},{"word":"abyssal hill","structure":"abyssal + hill (compound term)","meaning":"a small elevated feature on the deep floor","meaningCN":"深海底的小型隆起；深海丘陵","example":"Abyssal hills roughen the plain.","exampleCN":"深海丘陵使平原变得崎岖。"}],"latinEntries":[{"word":"abyssus","structure":"abyssus, abyssi (m., second declension)","meaning":"the deep, the abyss","meaningCN":"深处；深渊"},{"word":"abyssalis","structure":"abyssalis, abyssale (adj., third declension)","meaning":"of the abyss","meaningCN":"深渊的"},{"word":"abyssos","structure":"abyssos (Greek adjective and noun)","meaning":"bottomless; the deep","meaningCN":"无底的；深处"}]}},{"word":"trench","ipa_uk":"/trentʃ/","ipa_us":"/trentʃ/","definition_zh":"沟；壕沟；战壕；海沟；挖沟","definition_en":"a long, narrow, deep cut in the ground, a military ditch, or a deep depression on the ocean floor; also to dig such a cut","core_image":"地面被直直切出一条窄而深的槽，两侧的土堆成整齐的脊","scene":"工人在路面上开出一条窄槽，准备埋电缆。 Workers dug a narrow trench along the curb for the new cable.","sceneCN":"这里 trench 指「人工挖出的狭长沟槽」（第 1 个义项：为工程开挖的沟）；句意为工人们沿路缘挖出一条窄沟，用来埋新电缆。图中可辨识物件：路缘、窄沟、铁锹、电缆盘。","pos":[{"tag":"n.","zh":"沟；壕沟；战壕；海沟；沟状凹陷"},{"tag":"vt.","zh":"在……挖沟；开槽；挖沟埋设"}],"collocations":[{"phrase":"dig a trench","zh":"挖沟"},{"phrase":"trench warfare","zh":"堑壕战"},{"phrase":"ocean trench","zh":"海沟"},{"phrase":"trench coat","zh":"风衣； trench coat"},{"phrase":"trench drain","zh":"沟渠排水"},{"phrase":"excavation trench","zh":"探沟；开挖沟"}],"forms":[{"label":"复数","form":"trenches"},{"label":"三单（he/she/it）","form":"trenches"},{"label":"过去式","form":"trenched"},{"label":"过去分词","form":"trenched"},{"label":"现在分词","form":"trenching"},{"label":"动词（使扎根；巩固）","form":"entrench"},{"label":"名词（巩固；壕沟）","form":"entrenchment"}],"derivatives":[{"word":"entrench","pos":"v.","zh":"使扎根；用壕沟防护"},{"word":"entrenchment","pos":"n.","zh":"巩固；壕沟工事"},{"word":"trenchant","pos":"adj.","zh":"尖锐的；有力的（同源但词义分化）"},{"word":"trench coat","pos":"n.","zh":"风衣"},{"word":"trench warfare","pos":"n.","zh":"堑壕战"}],"senses":[{"no":"01","title":"A dug ditch","titleCN":"人工挖出的沟槽","definition":"a long, narrow cut dug in the ground for drainage, cables or foundations","definitionCN":"为排水、电缆或基础而在地面挖出的狭长深沟","example":"Workers dug a narrow trench along the curb for the new cable.","exampleCN":"工人们沿路缘挖出一条窄沟，用来埋新电缆。","why":"trench goes back to Old French trenchier 'to cut', so the noun starts as the line left by a cutting action.","whyCN":"trench 上溯到古法语 trenchier「切」，因此这个名词最初就是切割动作留下的那条线。"},{"no":"02","title":"A military trench","titleCN":"战壕","definition":"a long defensive ditch from which soldiers fight and shelter","definitionCN":"士兵据以作战与隐蔽的狭长防御沟","example":"The regiment held the trench through the winter.","exampleCN":"这个团在战壕里守了一整个冬天。","why":"the military sense narrows the engineering sense to a ditch that protects bodies from fire.","whyCN":"军事义把工程义收窄为一条保护身体免受火力的沟。"},{"no":"03","title":"A deep ocean trench","titleCN":"海沟","definition":"a long, narrow, very deep depression on the ocean floor","definitionCN":"洋底上狭长而极深的凹陷","example":"The earthquake epicentre lay near a deep ocean trench.","exampleCN":"震中位于一条深海沟附近。","why":"the ocean floor has cuts of the same narrow shape, so geology reused the word for them.","whyCN":"洋底也有同样狭长形状的切口，因此地质学沿用了这个词。"},{"no":"04","title":"A geological trough","titleCN":"地质上的沟状凹陷","definition":"a long, narrow depression in rock or sediment formed by faulting or erosion","definitionCN":"由断裂或侵蚀在岩石、沉积物中形成的狭长凹陷","example":"A fault trench runs across the valley floor.","exampleCN":"一条断层沟横穿谷底。","why":"the shape, not the digging, is what matters here: a natural cut in the ground is still a trench.","whyCN":"这里重要的是形状而非挖掘：地面上的天然切口仍叫 trench。"},{"no":"05","title":"To dig a ditch","titleCN":"动词：挖沟","definition":"to dig a long, narrow cut in the ground","definitionCN":"在地面挖出狭长的沟","example":"They trenched the field to drain the low corner.","exampleCN":"他们在田里挖沟，为低洼的一角排水。","why":"the verb is simply the action that produces the noun, and English often pairs such nouns with a zero-derived verb.","whyCN":"动词就是产生这个名词的动作，英语常让这类名词与零派生动词配对。"},{"no":"06","title":"To cut a trench through land","titleCN":"动词：在土地上开槽穿过","definition":"to cut a trench across or through an area, as for a pipeline","definitionCN":"为铺设管道等而在某区域横切出一条沟","example":"Crews trenched the hillside for the water main.","exampleCN":"施工队在坡上开沟，铺设供水主管。","why":"with an object like field or hillside, the verb stresses the area crossed rather than the ditch itself.","whyCN":"接 field 或 hillside 这类宾语时，动词强调的是被穿越的区域，而非沟本身。"},{"no":"07","title":"To open an excavation trench","titleCN":"考古：开挖探沟","definition":"to open a controlled excavation cut at an archaeological site","definitionCN":"在考古遗址上开挖有控制的探沟","example":"The team trenched the mound in a grid pattern.","exampleCN":"团队按网格在土丘上开挖探沟。","why":"archaeology adopted the engineering word for its own orderly cuts through layered ground.","whyCN":"考古学借用了工程词，指它在层状地面上开出的有序切口。"},{"no":"08","title":"Archaic: to encroach","titleCN":"旧用法：侵占、侵犯","definition":"to encroach or infringe upon something, as in the old phrase trench upon","definitionCN":"侵占或侵犯某物，见于旧短语 trench upon","example":"The old statute forbade anyone to trench upon the commons.","exampleCN":"旧法令禁止任何人侵占公地。","why":"the image of cutting into another's ground produced an older legal sense of encroachment that survives only in archaic prose.","whyCN":"切入他人土地的意象产生了较早的法律义「侵占」，今仅存于古旧文字。"}],"etymology":{"intro":{"en":"Trench comes from Old French trenche 'a cut, ditch', from trenchier 'to cut', a verb of uncertain deeper origin, sometimes linked to Latin truncare 'to cut off'. Dates are approximate.","cn":"trench 来自古法语 trenche「切口、沟」，出自 trenchier「切」；这个动词更深的来源不确定，有人把它与拉丁 truncare「切掉」联系起来。年代均为约数。"},"items":[{"era":"OLD FRENCH TRENCHIER","en":"Trenchier meant 'to cut, slice, carve'. Its relation to Latin truncare 'to cut off' is often proposed but not established beyond doubt.","cn":"trenchier 意为「切、割、刻」。人们常提出它与拉丁 truncare「切掉」有关，但并未确凿证实。"},{"era":"OLD FRENCH TRENCHE","en":"The noun trenche named a cut or a ditch, and English borrowed it in the fifteenth century.","cn":"名词 trenche 指切口或沟，英语在十五世纪借入。"},{"era":"MILITARY SENSE","en":"From the seventeenth century trench was used for siege and field fortifications, and the sense dominated after the trench warfare of 1914 to 1918.","cn":"从十七世纪起，trench 用于攻城与野战工事；一九一四至一九一八年的堑壕战之后，这一义项占据主导。"},{"era":"GEOLOGICAL SENSE","en":"Oceanography applied the word to deep linear depressions of the sea floor in the late nineteenth century.","cn":"海洋学在十九世纪末把这个词用于洋底狭长的深凹陷。"},{"era":"VERBAL SENSE","en":"The verb meaning 'to dig a trench' developed alongside the noun; the archaic sense 'to encroach' is older and now rare.","cn":"意为「挖沟」的动词与名词并行发展；古旧的「侵占」义更早，今已罕见。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: whether trenchier descends from Latin truncare is disputed, and the exact first English date is not fixed, so any intermediate form is a reconstruction.","cn":"来源不确定：trenchier 是否源自拉丁 truncare 尚有争议，英语最早书证的确切年代也未固定，凡给出的中间形式均属重构。"}]},"similar":{"note":{"en":"Group one separates trench from its own compounds and its sharp-edged relative trenchant; group two holds near synonyms for a long cut or channel.","cn":"第一组把 trench 与其复合词、以及同源但词义分化的 trenchant 分开；第二组是表示狭长切口或通道的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"entrench","ipa":"/ɪnˈtrentʃ/","tag":"verb with en-","definition":"En- 'in' plus trench: to fix firmly, or to protect with a trench; it is a verb, not the ditch itself.","definitionCN":"en-「进入」加 trench：使牢固扎根，或用壕沟防护；它是动词，不指沟本身。"},{"word":"trenchant","ipa":"/ˈtrentʃənt/","tag":"cutting, figurative","definition":"From the same Old French 'cutting' stock: sharp and forceful in speech or writing, not a physical ditch.","definitionCN":"同出古法语「切」的词源：指言辞犀利有力，并非实体沟渠。"},{"word":"trench coat","ipa":"/ˈtrentʃ kəʊt/","tag":"garment compound","definition":"A belted raincoat named after the trenches of the First World War; it contains trench but names clothing.","definitionCN":"得名于第一次世界大战战壕的束带雨衣；它虽含 trench，却指衣物。"},{"word":"trench warfare","ipa":"/ˈtrentʃ ˈwɔːfeə/","tag":"military compound","definition":"War fought from opposing systems of trenches; it uses trench but names a kind of conflict.","definitionCN":"从相互对峙的壕沟体系进行的战争；它虽含 trench，却指一种冲突形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ditch","ipa":"/dɪtʃ/","tag":"drainage cut","definition":"A long narrow channel dug for drainage or irrigation; it is usually shallower and less military than a trench.","definitionCN":"为排水或灌溉挖出的狭长渠道；通常比 trench 浅，也没有军事含义。"},{"word":"channel","ipa":"/ˈtʃænəl/","tag":"waterway","definition":"A passage for water, natural or built; it stresses flow rather than the cut itself.","definitionCN":"天然或人工的水道；强调水流，而非切口本身。"},{"word":"groove","ipa":"/ɡruːv/","tag":"narrow slot","definition":"A long narrow depression cut into a surface, often shallow and machined; a trench is deeper and in ground.","definitionCN":"切在表面上的狭长凹槽，常较浅且为机加工；trench 更深且开在地面。"},{"word":"furrow","ipa":"/ˈfərəʊ/","tag":"plough line","definition":"A narrow cut made by a plough in soil; it is agricultural and shallow, not a fortification.","definitionCN":"犁在土里开出的狭沟；属农业用途且较浅，不是工事。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"trench- 'cut' + the noun ending: the cut itself.","cn":"trench-「切」+ 名词词尾：切出来的那道口子。"},{"en":"The family runs trench, entrench, entrenchment, trenchant, trench coat.","cn":"同族词包括 trench、entrench、entrenchment、trenchant、trench coat。"},{"en":"Fixed phrases mark the military sense: trench warfare, trench coat, trench foot.","cn":"固定搭配标出军事义：堑壕战、风衣、战壕足。"},{"en":"Geology says trench for the deep cut and trench for its two walls.","cn":"地质学用 trench 指深切口，也指切口的两壁。"},{"en":"The verb takes field or line as its object: trench a field, trench a line.","cn":"这个动词常以 field 或 line 作宾语：在田里开沟、沿线开沟。"}],"abstract":[{"en":"Picture a cake cut once and left open, its layers exposed on both sides.","cn":"想象一个蛋糕被切了一刀后摊开，两边的层次都露出来。"},{"en":"Picture two gardens separated by a line no one is allowed to cross.","cn":"想象两座花园之间隔着一条谁也不许越过的线。"},{"en":"Picture a sentence that cuts cleanly through an argument.","cn":"想象一句话干净利落地切开一场争论。"}]},"examples":[{"en":"The workers filled the trench after laying the pipe.","cn":"铺好管道后，工人把沟填了回去。"},{"en":"Soldiers shared a narrow trench for three weeks.","cn":"士兵们在一条窄战壕里共处了三周。"},{"en":"The Mariana Trench is the deepest known ocean trench.","cn":"马里亚纳海沟是已知最深的洋底海沟。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「trench（切）」——在地上切出一道窄口 → 沟、战壕、海沟","word":"trench"},"root":"古法语 trenche「切口、沟」来自 trenchier「切」；与拉丁 truncare「切掉」的联系常被提出但未确证，更深来源不确定，相关中间形式均属重构。","sensesIntro":{"en":"Eight senses follow one cut: a dug ditch, a military line, an ocean deep, a fault trough, three kinds of digging, and an archaic encroachment that survives in old prose.","cn":"八个义项沿同一条切口展开：挖出的沟、军事防线、海底深凹、断层沟、三种开挖动作，以及仅存于古旧文字的侵占义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a single straight cut opening the ground into two walls.","cn":"核心意象：一道笔直的切口把地面分成两壁。"},"chain":["CUT LINE","DITCH","BATTLE LINE","OCEAN DEEP","EXCAVATE","ENCROACH"],"branches":[{"senses":"S1 · S4","en":"CUT IN GROUND: a dug ditch and a natural fault trough share the shape.","cn":"地面切口：人工沟与天然断层沟共享同一形状。"},{"senses":"S2","en":"DEFENSIVE LINE: the ditch becomes a place to fight from.","cn":"防御线：沟变成据以作战的地方。"},{"senses":"S3","en":"OCEANIC CUT: the same narrow deep shape lies under the sea.","cn":"海底切口：同样的狭长深形出现在海面之下。"},{"senses":"S5 · S6 · S7","en":"DIGGING ACTS: engineering, crossing land, archaeology.","cn":"开挖动作：工程、穿越土地、考古。"},{"senses":"S8","en":"OLD INFRINGEMENT: cutting into another's ground became legal encroachment.","cn":"旧日侵占：切入他人土地变成法律上的侵占。"}]},"affixes":{"intro":{"en":"Trench is a borrowed French noun of cutting; its family includes the verb entrench, the adjective trenchant and two modern compounds.","cn":"trench 是借自法语的「切」名词；其词族包括动词 entrench、形容词 trenchant 与两个现代复合词。"},"latinIntro":{"en":"The deeper origin is uncertain; a link to Latin truncare 'to cut off' is often proposed but not proven, so the Latin entries are given only as possible sources.","cn":"更深来源不确定；与拉丁 truncare「切掉」的联系常被提出却未证实，因此所给拉丁条目只能视为可能的来源。"},"items":[{"word":"trenchier","structure":"trenchier (Old French verb, 'to cut')","meaning":"to cut, slice","meaningCN":"切；割","example":"The verb named the act of cutting into the ground.","exampleCN":"这个动词指切入地面的动作。"},{"word":"trench","structure":"trenche (Old French noun) + English form","meaning":"a cut, a ditch","meaningCN":"切口；沟","example":"The trench was two metres deep.","exampleCN":"这条沟有两米深。"},{"word":"trench","structure":"zero-derived verb from the noun","meaning":"to dig a trench","meaningCN":"挖沟","example":"They trenched the whole field.","exampleCN":"他们给整块田开了沟。"},{"word":"entrench","structure":"en- (in) + trench","meaning":"to fix firmly; to fortify with trenches","meaningCN":"使牢固扎根；用壕沟防护","example":"The habit was entrenched by years of use.","exampleCN":"这个习惯因多年使用而根深蒂固。"},{"word":"entrenchment","structure":"entrench + -ment (result noun)","meaning":"a fortified ditch; a fixed state","meaningCN":"壕沟工事；根深蒂固的状态","example":"The entrenchment slowed the advance.","exampleCN":"壕沟工事拖慢了推进。"},{"word":"trenchant","structure":"trenchier + -ant (present participle)","meaning":"cutting; hence sharp and incisive","meaningCN":"切割的；引申为犀利有力的","example":"Her trenchant criticism silenced the room.","exampleCN":"她犀利的批评让全场安静。"},{"word":"trench coat","structure":"trench + coat (compound noun)","meaning":"a belted raincoat in military style","meaningCN":"军用风格的风衣","example":"He wore a trench coat in the rain.","exampleCN":"他雨天穿着一件风衣。"},{"word":"trench warfare","structure":"trench + warfare (compound noun)","meaning":"war fought from opposing trench systems","meaningCN":"以对峙壕沟体系进行的战争","example":"Trench warfare defined the western front.","exampleCN":"堑壕战定义了西线战场。"}],"latinEntries":[{"word":"truncare","structure":"truncare, truncavi, truncatum (verb, first conjugation; possible source)","meaning":"to cut off, mutilate","meaningCN":"切掉；截断"},{"word":"truncus","structure":"truncus, trunci (m., second declension; possible source)","meaning":"trunk, stem; cut-off piece","meaningCN":"树干；截下的部分"}]}},{"word":"ocean trench","ipa_uk":"/ˈəʊʃən trentʃ/","ipa_us":"/ˈoʊʃən trentʃ/","definition_zh":"海沟；大洋底部的狭长深凹","definition_en":"a long, narrow, very deep depression on the ocean floor, usually marking a subduction boundary","core_image":"海图上一条细长的深蓝带子紧贴岛弧外侧，两侧坡壁陡直","scene":"海图上一条细长的深蓝带子沿着岛弧延伸。 The survey mapped a deep ocean trench east of the island arc.","sceneCN":"这里 ocean trench 指「大洋底部的狭长深凹」（第 1 个义项：洋底上的深沟地貌）；句意为勘测在东侧岛弧外画出这条深海沟。图中可辨识物件：海图、深蓝带、岛弧、勘测船。","pos":[{"tag":"n.","zh":"海沟；大洋底的狭长深凹"}],"collocations":[{"phrase":"deep ocean trench","zh":"深海沟"},{"phrase":"ocean trench system","zh":"海沟体系"},{"phrase":"trench axis","zh":"海沟轴部"},{"phrase":"trench wall","zh":"海沟壁"},{"phrase":"ocean trench sediment","zh":"海沟沉积物"},{"phrase":"the deepest ocean trench","zh":"最深的海沟"}],"forms":[{"label":"复数","form":"ocean trenches"},{"label":"同义术语","form":"oceanic trench"},{"label":"简称","form":"trench"},{"label":"形容词形式","form":"ocean-trench"},{"label":"相关术语","form":"trench axis"},{"label":"相关术语","form":"hadal zone"}],"derivatives":[{"word":"oceanic trench","pos":"n.","zh":"海沟（同义术语）"},{"word":"trench axis","pos":"n.","zh":"海沟轴部"},{"word":"trench wall","pos":"n.","zh":"海沟壁"},{"word":"trench sediment","pos":"n.","zh":"海沟沉积物"},{"word":"hadal zone","pos":"n.","zh":"超深渊带"}],"senses":[{"no":"01","title":"A deep linear depression on the ocean floor","titleCN":"洋底上的狭长深凹","definition":"a long, narrow and extremely deep hollow in the sea bottom","definitionCN":"海底长而窄且极深的凹处","example":"The survey mapped a deep ocean trench east of the island arc.","exampleCN":"勘测在东侧岛弧外画出这条深海沟。","why":"ocean gives the setting and trench the shape: a long cut in the bottom of the open sea.","whyCN":"ocean 提供环境，trench 提供形状：开阔海洋底部的一道长切口。"},{"no":"02","title":"A subduction landform","titleCN":"板块俯冲形成的地貌","definition":"the depression formed where one tectonic plate bends and sinks beneath another","definitionCN":"一个板块弯折并沉入另一个板块之下处形成的凹陷","example":"The ocean trench marks where the old plate begins to sink.","exampleCN":"这条海沟标示出老板块开始下沉的位置。","why":"the deepest cuts occur exactly where crust is consumed, so the phrase became a structural term.","whyCN":"最深的切口正好出现在洋壳被消减处，因此这个短语成了构造术语。"},{"no":"03","title":"A belt of earthquakes","titleCN":"地震带","definition":"the zone along a trench where earthquakes and volcanoes cluster","definitionCN":"沿海沟分布、地震与火山密集的地带","example":"Instruments line the ocean trench to record local quakes.","exampleCN":"仪器沿海沟布设，记录当地地震。","why":"sinking plates fracture and melt nearby, so the trench is also read as a seismic belt.","whyCN":"下沉板块在附近破裂与熔融，因此海沟也被视为一条地震带。"},{"no":"04","title":"The deepest point of the sea","titleCN":"海沟的最深处","definition":"the extreme depth reached at the axis of a trench, often the deepest point of the ocean","definitionCN":"海沟轴部达到的极端深度，常是海洋的最深点","example":"A small submersible reached the bottom of the ocean trench.","exampleCN":"一艘小型潜水器抵达了这条海沟的底部。","why":"a trench is where the bottom falls furthest, so the phrase can name the record depth itself.","whyCN":"海沟是底部下落最深的地方，因此这个短语也可指那个纪录深度。"},{"no":"05","title":"A hadal habitat","titleCN":"超深渊环境的栖息地","definition":"the extreme environment inside a trench, under enormous pressure and without light","definitionCN":"海沟内部高压、无光的极端环境","example":"Specialised microbes survive inside the ocean trench.","exampleCN":"特化的微生物在这条海沟中存活。","why":"the trench holds the ocean's most extreme habitat, so ecology uses the phrase for that living space.","whyCN":"海沟容纳着海洋最极端的栖息地，因此生态学用这个短语指那片生存空间。"},{"no":"06","title":"Trench sediment","titleCN":"海沟中的沉积物","definition":"the material that collects in the trench, including turbidites and pelagic ooze","definitionCN":"在海沟中堆积的物质，包括浊流沉积与大洋软泥","example":"Layers in the ocean trench record landslides from the slope.","exampleCN":"海沟中的层理记录了来自陆坡的滑坡。","why":"the trough traps falling and sliding material, so the phrase also names the deposit it holds.","whyCN":"这条深槽截留落下的与滑动的物质，因此这个短语也指其中所存的沉积。"},{"no":"07","title":"A plate boundary","titleCN":"板块边界","definition":"the line where two plates meet and one descends beneath the other","definitionCN":"两个板块相接、其中一个俯冲到另一个之下的界线","example":"The ocean trench forms part of the boundary between two plates.","exampleCN":"这条海沟构成两个板块边界的一部分。","why":"in plate tectonics the trench is the surface expression of a convergent boundary.","whyCN":"在板块构造中，海沟是汇聚型边界的表面表现。"},{"no":"08","title":"An object of charting and naming","titleCN":"测绘与命名的对象","definition":"a named feature on charts, defined by soundings and coordinates","definitionCN":"海图上由测深与坐标界定并命名的地貌","example":"The new ocean trench was named after the survey ship.","exampleCN":"这条新海沟以勘测船命名。","why":"hydrography turns the feature into a charted line with a name, which is a distinct practical sense.","whyCN":"水文测量把这个地貌变成图上带名字的一条线，这构成一个独立的实用义项。"}],"etymology":{"intro":{"en":"Ocean trench joins ocean, from Greek ōkeanos through Latin oceanus, with trench, from Old French trenche 'cut'. The compound is a modern scientific term. Dates are approximate.","cn":"ocean trench 由 ocean 与 trench 组合：ocean 经拉丁 oceanus 来自希腊 ōkeanos，trench 来自古法语 trenche「切口」。这个复合词属现代科技术语。年代均为约数。"},"items":[{"era":"GREEK ŌKEANOS","en":"Ōkeanos named the river believed to encircle the world; its own origin is uncertain and may not be Greek.","cn":"ōkeanos 指古人相信环绕世界的巨流；它自身的来源不确定，可能并非希腊语。"},{"era":"OLD FRENCH TRENCHE","en":"Trenche 'a cut, ditch' came from trenchier 'to cut', a verb whose deeper origin is disputed.","cn":"trenche「切口、沟」来自 trenchier「切」，这个动词更深的来源有争议。"},{"era":"EARLY SOUNDINGS","en":"Nineteenth-century expeditions found that the deepest parts of the sea form long narrow troughs, and the phrase ocean trench was coined for them.","cn":"十九世纪的考察发现海洋最深的部分呈狭长深槽，于是为它们造出 ocean trench 这一短语。"},{"era":"PLATE TECTONICS","en":"Twentieth-century plate theory explained trenches as subduction sites, fixing the technical sense.","cn":"二十世纪的板块理论把海沟解释为俯冲地点，固定了技术含义。"},{"era":"HADAL RESEARCH","en":"Deep-diving vehicles later made the trench a place of biological and geochemical study rather than only a depth record.","cn":"深潜器后来使海沟成为生物学与地球化学研究的场所，而不仅是深度纪录。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origins of ōkeanos and of trenchier are both unsettled, so any reconstructed forms offered for them are reconstructions.","cn":"来源不确定：ōkeanos 与 trenchier 的来源都未有定论，凡为它们给出的重构形式均属重构。"}]},"similar":{"note":{"en":"Group one separates the trench from the floor around it and from the tectonic terms it belongs to; group two holds deep depressions of different origin.","cn":"第一组把海沟与其周围底部及所属构造术语分开；第二组是成因不同的深凹。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"trench","ipa":"/trentʃ/","tag":"the short form","definition":"Any long narrow cut, including a military ditch; ocean trench specifies the submarine feature.","definitionCN":"任何狭长切口，包括战壕；ocean trench 特指海底地貌。"},{"word":"ocean floor","ipa":"/ˈəʊʃən flɔː/","tag":"the surrounding surface","definition":"The bottom around and beyond the trench; a trench is a depression cut into that floor.","definitionCN":"海沟周围及之外的底部；海沟是切入这块底部的一个凹陷。"},{"word":"subduction zone","ipa":"/səbˈdʌkʃən zəʊn/","tag":"the process zone","definition":"The broader belt where one plate sinks; the trench is the surface depression within it.","definitionCN":"一个板块下沉的较宽地带；海沟是其中的地表凹陷。"},{"word":"hadal zone","ipa":"/ˈheɪdəl zəʊn/","tag":"the depth layer","definition":"The water layer deeper than six thousand metres, named after Hades; it is a depth term, not the landform.","definitionCN":"六千米以下的深水层，得名于冥王；它是深度术语，不是地貌。"}]},{"heading":"NEAR MEANING","entries":[{"word":"trough","ipa":"/trɒf/","tag":"any long depression","definition":"A long narrow low area, on land or sea; a trench is deeper and usually tectonic.","definitionCN":"陆地或海上的狭长低洼；trench 更深，且通常与构造有关。"},{"word":"abyss","ipa":"/əˈbɪs/","tag":"depth, not shape","definition":"A bottomless depth; it stresses the unfathomable rather than the long narrow form.","definitionCN":"无底的深处；强调不可测，而非狭长形状。"},{"word":"basin","ipa":"/ˈbeɪsən/","tag":"broad depression","definition":"A wide, often rounded depression; a trench is narrow and linear by contrast.","definitionCN":"宽阔且常呈圆形的凹陷；相比之下海沟狭长成线。"},{"word":"deep","ipa":"/diːp/","tag":"general depth","definition":"Any deep part of the sea; it lacks the specific shape and tectonic meaning of ocean trench.","definitionCN":"海中任何深处；缺少 ocean trench 那种具体形状与构造含义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ocean 'open sea' + trench 'cut': a cut in the bottom of the open sea.","cn":"ocean「开阔海洋」+ trench「切口」：开阔海洋底部的一道切口。"},{"en":"The related terms run ocean trench, oceanic trench, trench axis, trench wall, hadal zone.","cn":"相关术语包括 ocean trench、oceanic trench、trench axis、trench wall、hadal zone。"},{"en":"Fixed phrases mark the science: deep ocean trench, ocean trench sediment, ocean trench system.","cn":"固定搭配标出科学用法：深海沟、海沟沉积物、海沟体系。"},{"en":"The Mariana Trench is the standard example of the phrase in textbooks.","cn":"教科书常用马里亚纳海沟作为这个短语的典型例子。"},{"en":"The phrase usually takes the definite article: at the bottom of the ocean trench.","cn":"这个短语通常带定冠词：在海沟底部。"}],"abstract":[{"en":"Picture a scar so long that it runs from one island chain to another.","cn":"想象一道长得从一串岛链延伸到另一串岛链的伤疤。"},{"en":"Picture a valley whose walls are water and whose floor is never lit.","cn":"想象一条山谷，两壁是水，谷底永无光。"},{"en":"Picture two plates meeting at a line drawn on a map in deep blue.","cn":"想象两个板块在地图上以深蓝线条相接。"}]},"examples":[{"en":"The ocean trench lies parallel to the volcanic arc.","cn":"这条海沟与火山弧平行。"},{"en":"Pressure at the bottom of the ocean trench crushes most instruments.","cn":"海沟底部的压力会压坏大多数仪器。"},{"en":"Sediment in the ocean trench records a million years of slides.","cn":"海沟中的沉积物记录了百万年的滑坡。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「ocean（大洋）+ trench（沟）」——大洋底部切出的深沟就是海沟","word":"ocean trench"},"root":"ocean 经拉丁 oceanus 来自希腊 ōkeanos「环绕大地的巨流」，来源不确定；trench 来自古法语 trenche「切口」，出自 trenchier「切」，更深来源有争议。复合词属现代海洋学术语。","sensesIntro":{"en":"Eight senses follow one submarine cut: the linear hollow, the subduction that makes it, its earthquake belt, its record depth, its extreme life, its sediment, its plate boundary, and its charted name.","cn":"八个义项沿同一条海底切口展开：狭长凹陷、造成它的俯冲、其地震带、其纪录深度、其极端生命、其沉积物、其板块边界，以及其在海图上的名字。"},"semanticMap":{"core":{"en":"CORE IMAGE: a narrow deep-blue line on a chart, hugging the outer side of an island arc.","cn":"核心意象：海图上一道紧贴岛弧外侧的狭长深蓝线。"},"chain":["DEEP CUT","SUBDUCTION","QUAKE BELT","DEEPEST POINT","EXTREME LIFE","CHARTED LINE"],"branches":[{"senses":"S1 · S7","en":"THE CUT AND ITS BOUNDARY: the hollow is the surface mark of a plate edge.","cn":"切口与边界：凹陷是板块边缘的表面标记。"},{"senses":"S2","en":"SINKING PLATE: subduction explains why the cut is so deep.","cn":"下沉板块：俯冲解释了切口为何如此之深。"},{"senses":"S3","en":"SHAKING BELT: fracture and melt cluster along the line.","cn":"震动带：破裂与熔融沿这条线聚集。"},{"senses":"S4 · S6","en":"RECORD AND TRAP: the deepest point and the sediment that collects there.","cn":"纪录与截留：最深点与堆积其中的沉积物。"},{"senses":"S5 · S8","en":"EXTREME HABITAT AND NAME: life under pressure, and a line defined by soundings.","cn":"极端栖息地与名字：高压下的生命，以及由测深界定的线。"}]},"affixes":{"intro":{"en":"Ocean trench is a modern compound of a Greek-derived noun and a French-derived noun, so its parts come from two different loan layers.","cn":"ocean trench 是现代复合词，由一个希腊来源名词与一个法语来源名词构成，两部分来自不同的借词层。"},"latinIntro":{"en":"Greek ōkeanos passed into Latin as oceanus; trench goes back to Old French trenchier, whose possible link to Latin truncare is only a hypothesis.","cn":"希腊 ōkeanos 进入拉丁语作 oceanus；trench 上溯到古法语 trenchier，其与拉丁 truncare 的可能联系仅为假说。"},"items":[{"word":"ocean","structure":"ocean (from Greek ōkeanos via Latin oceanus)","meaning":"the open sea","meaningCN":"开阔海洋","example":"The ocean covers most of the planet.","exampleCN":"海洋覆盖了地球的大部分。"},{"word":"trench","structure":"trench (from Old French trenche, 'cut')","meaning":"a long narrow cut","meaningCN":"狭长的沟或切口","example":"The trench was cut into the plain.","exampleCN":"这条沟切进了平原。"},{"word":"ocean trench","structure":"ocean + trench (compound noun)","meaning":"a deep linear depression in the sea floor","meaningCN":"洋底上的狭长深凹；海沟","example":"The ocean trench runs beside the arc.","exampleCN":"这条海沟沿岛弧延伸。"},{"word":"oceanic trench","structure":"oceanic + trench (synonym)","meaning":"a trench of the open ocean","meaningCN":"开阔大洋中的海沟","example":"Some maps prefer oceanic trench.","exampleCN":"有些地图偏好 oceanic trench 这一说法。"},{"word":"trench axis","structure":"trench + axis (compound term)","meaning":"the deepest line along a trench","meaningCN":"海沟轴部；沿沟的最深线","example":"Samples were taken on the trench axis.","exampleCN":"样品采自海沟轴部。"},{"word":"trench wall","structure":"trench + wall (compound term)","meaning":"the steep side of a trench","meaningCN":"海沟陡壁","example":"The trench wall rises two kilometres.","exampleCN":"海沟壁升高两千米。"},{"word":"trench sediment","structure":"trench + sediment (compound term)","meaning":"material deposited inside a trench","meaningCN":"堆积在海沟内的沉积物","example":"Trench sediment holds a record of slope failures.","exampleCN":"海沟沉积物保存着陆坡崩塌的记录。"},{"word":"hadal","structure":"Hades + -al (adjective, 'of the deepest zone')","meaning":"of the water below six thousand metres","meaningCN":"六千米以下深水层的","example":"Hadal species live only in trenches.","exampleCN":"超深渊物种只生活在海沟里。"}],"latinEntries":[{"word":"oceanus","structure":"oceanus, oceanus (m., fourth declension)","meaning":"the outer sea","meaningCN":"外海"},{"word":"truncare","structure":"truncare, truncavi, truncatum (verb, first conjugation; possible source)","meaning":"to cut off","meaningCN":"切掉；截断"},{"word":"Oceanus","structure":"Oceanus (proper noun, from Greek ōkeanos)","meaning":"the river encircling the world","meaningCN":"环绕世界的巨流"}]}},{"word":"mid-ocean ridge","ipa_uk":"/ˌmɪd əʊʃən ˈrɪdʒ/","ipa_us":"/ˌmɪd oʊʃən ˈrɪdʒ/","definition_zh":"洋中脊；大洋中脊（贯穿洋底的巨大海底山脉）","definition_en":"a long system of underwater mountains running down the middle of an ocean, where new crust forms as plates move apart","core_image":"海底一条长长的隆起，中央裂开一道谷，像被两只手从中间掰开的伤口","scene":"潜水器沿着海底山脉的裂谷缓慢前进，热液从烟囱里冒出。 New crust forms along the mid-ocean ridge where plates pull apart.","sceneCN":"这里 mid-ocean ridge 指「大洋中脊这一海底山脉体系」（第 1 个义项：贯穿洋底的长条隆起）；句意为新洋壳在板块拉开的洋中脊处形成。图中可辨识物件：海底山脉、中央裂谷、热液烟囱、潜水器。","pos":[{"tag":"n.","zh":"洋中脊；大洋中脊（通常作单数，带定冠词）"}],"collocations":[{"phrase":"mid-ocean ridge system","zh":"洋中脊体系"},{"phrase":"mid-ocean ridge axis","zh":"洋中脊轴部"},{"phrase":"mid-ocean ridge basalt","zh":"洋中脊玄武岩"},{"phrase":"along the mid-ocean ridge","zh":"沿洋中脊"},{"phrase":"mid-ocean ridge crest","zh":"洋中脊脊顶"},{"phrase":"mid-ocean ridge volcanism","zh":"洋中脊火山活动"}],"forms":[{"label":"复数","form":"mid-ocean ridges"},{"label":"简称","form":"ocean ridge"},{"label":"同义术语","form":"oceanic ridge"},{"label":"形容词形式","form":"mid-ocean-ridge"},{"label":"相关术语","form":"ridge axis"},{"label":"相关术语","form":"rift valley"}],"derivatives":[{"word":"ocean ridge","pos":"n.","zh":"洋脊（简称）"},{"word":"oceanic ridge","pos":"n.","zh":"洋脊（同义术语）"},{"word":"ridge axis","pos":"n.","zh":"洋中脊轴部"},{"word":"rift valley","pos":"n.","zh":"裂谷"},{"word":"mid-ocean-ridge","pos":"adj.","zh":"洋中脊的"}],"senses":[{"no":"01","title":"A long underwater mountain chain","titleCN":"贯穿洋底的长条海底山脉","definition":"a long elevated chain of underwater mountains running through the middle of an ocean","definitionCN":"贯穿大洋中部、由海底山脉构成的长条隆起","example":"New crust forms along the mid-ocean ridge where plates pull apart.","exampleCN":"新洋壳在板块拉开的洋中脊处形成。","why":"the phrase is transparent: mid 'middle' + ocean + ridge 'long raised back', a spine running down the sea's centre.","whyCN":"这个短语很透明：mid「中间」+ ocean「海洋」+ ridge「长条脊背」，即沿海洋中央延伸的一条脊。"},{"no":"02","title":"A divergent plate boundary","titleCN":"板块离散边界","definition":"the boundary where two plates move apart and new material rises between them","definitionCN":"两个板块相互分离、其间有新物质上升的边界","example":"The ridge marks a boundary where two plates are separating.","exampleCN":"这条洋脊标示出两个板块正在分离的边界。","why":"plate theory redefined the ridge from a mountain chain into a boundary of divergence.","whyCN":"板块理论把洋中脊从一条山脉重新定义为一条离散边界。"},{"no":"03","title":"The place where new crust is born","titleCN":"新洋壳生成处","definition":"the zone where rising magma cools to form fresh oceanic crust","definitionCN":"上升岩浆冷却形成新洋壳的地带","example":"Lava erupts quietly at the mid-ocean ridge and builds new rock.","exampleCN":"熔岩在洋中脊平静喷出，堆积成新的岩石。","why":"because the ridge is where plates part, it is also the cradle of new crust.","whyCN":"由于洋脊是板块分开的地方，它也是新洋壳的摇篮。"},{"no":"04","title":"The axial rift","titleCN":"洋中脊中央的裂谷","definition":"the central depression along the crest of a slowly spreading ridge","definitionCN":"缓慢扩张的洋脊脊顶沿线的中央凹陷","example":"A narrow rift runs along the crest of the mid-ocean ridge.","exampleCN":"一条狭窄裂谷沿洋中脊脊顶延伸。","why":"tension pulls the crest apart, so the ridge is often split by a valley at its axis.","whyCN":"张力把脊顶拉开，因此洋脊常在轴部被一条谷劈开。"},{"no":"05","title":"A field of hydrothermal vents","titleCN":"热液喷口活动区","definition":"a zone of hot mineral-rich water rising through the ridge, feeding vent communities","definitionCN":"沿洋脊上升的富矿物热水区，供养喷口生物群落","example":"Chimneys on the mid-ocean ridge support worms that need no sunlight.","exampleCN":"洋中脊上的烟囱供养不需要阳光的蠕虫。","why":"seawater circulates through hot new rock and returns as vents, a process peculiar to ridge crests.","whyCN":"海水在高温新岩石中循环，再以喷口形式返回，这是脊顶特有的过程。"},{"no":"06","title":"The magma supply system","titleCN":"洋中脊的岩浆供给系统","definition":"the upwelling mantle and magma chamber that feed the ridge volcanism","definitionCN":"为洋脊火山活动提供物质的上升地幔与岩浆房","example":"Seismic images show a magma chamber beneath the mid-ocean ridge.","exampleCN":"地震成像显示洋中脊之下有一个岩浆房。","why":"the ridge is the surface sign of deeper upwelling, so the phrase can name the whole plumbing system.","whyCN":"洋脊是更深部上升流的表面标志，因此这个短语可指整套供给系统。"},{"no":"07","title":"The axis of symmetric magnetic stripes","titleCN":"对称磁条带的对称轴","definition":"the ridge crest as the line about which magnetic stripes are arranged in mirror image","definitionCN":"作为磁条带呈镜像排列基准线的脊顶","example":"The magnetic pattern is symmetrical about the mid-ocean ridge.","exampleCN":"磁条带图样以洋中脊为轴左右对称。","why":"crust forms at the axis and moves both ways, so the stripe pattern repeats on each side of the ridge.","whyCN":"洋壳在轴部形成并向两侧移动，因此条带图样在洋脊两侧重复。"},{"no":"08","title":"A connected global system","titleCN":"全球连通的洋中脊体系","definition":"the worldwide network of ridges that links the oceans into one system","definitionCN":"把各大洋连成一个体系的全球洋脊网络","example":"The mid-ocean ridge forms the longest mountain system on Earth.","exampleCN":"洋中脊构成长度居地球之首的山系。","why":"the separate ridges join into one continuous uplift, which is why geologists speak of a ridge system.","whyCN":"各段洋脊连成一条连续的隆起，因此地质学家称之为洋脊体系。"}],"etymology":{"intro":{"en":"Mid-ocean ridge joins mid, from Old English midd 'middle', ocean, from Greek ōkeanos through Latin, and ridge, from Old English hrycg 'back, spine'. The term is modern. Dates are approximate.","cn":"mid-ocean ridge 由 mid、ocean 与 ridge 组合：mid 来自古英语 midd「中间」，ocean 经拉丁语来自希腊 ōkeanos，ridge 来自古英语 hrycg「背、脊」。这个术语属现代。年代均为约数。"},"items":[{"era":"OLD ENGLISH MIDD","en":"Midd meant 'middle' and survives in mid and midnight. Its deeper Germanic origin is reconstructed.","cn":"midd 意为「中间」，在 mid 与 midnight 中留存。其更早的日耳曼语来源属重构。"},{"era":"GREEK ŌKEANOS","en":"Ōkeanos named the river around the world; through Latin oceanus it gives ocean. Its own origin is uncertain.","cn":"ōkeanos 指环绕世界的巨流；经拉丁 oceanus 衍生 ocean。它自身的来源不确定。"},{"era":"OLD ENGLISH HRYCG","en":"Hrycg meant 'back, spine, ridge', and was applied to raised lines in land and rock.","cn":"hrycg 意为「背、脊、隆起」，也用于土地与岩石中的隆起线。"},{"era":"NINETEENTH-CENTURY SOUNDING","en":"Deep-sea cables and soundings revealed a long central rise in the Atlantic, and mid-ocean ridge was coined for such features.","cn":"深海电缆与测深揭示出大西洋中部有一条长隆起，于是为这类地貌造出 mid-ocean ridge 一词。"},{"era":"PLATE TECTONICS","en":"Twentieth-century plate theory made the ridge the type example of a divergent boundary and a spreading centre.","cn":"二十世纪的板块理论使洋中脊成为离散边界与扩张中心的典型例子。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Germanic roots of midd and hrycg are reconstructions, the origin of ōkeanos is disputed, and the term's first date is only approximate.","cn":"来源不确定：midd 与 hrycg 在日耳曼语之前的词根均为重构，ōkeanos 的来源有争议，术语首见年代也只是约数。"}]},"similar":{"note":{"en":"Group one separates the full term from its short forms and the features that sit on the ridge; group two holds raised sea-floor features of different size.","cn":"第一组把完整术语与其简称、以及位于洋脊上的地貌分开；第二组是规模不同的海底隆起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ocean ridge","ipa":"/ˈəʊʃən rɪdʒ/","tag":"short form","definition":"A general short form for a ridge in the ocean; mid-ocean ridge adds the central, spreading setting.","definitionCN":"海洋中洋脊的通用简称；mid-ocean ridge 另加「中央、扩张」的环境限定。"},{"word":"oceanic ridge","ipa":"/əʊˈsiːənɪk rɪdʒ/","tag":"synonym","definition":"A near synonym used in geology; it does not always carry the 'middle of the ocean' idea.","definitionCN":"地质学中的近义术语；它并不总带「大洋中央」的意思。"},{"word":"rift valley","ipa":"/ˈrɪft ˈvæli/","tag":"feature on the ridge","definition":"The central depression along a ridge crest; it is a valley within the ridge, not the ridge itself.","definitionCN":"沿脊顶的中央凹陷；它是洋脊内部的谷，而非洋脊本身。"},{"word":"ridge axis","ipa":"/ˈrɪdʒ ˈæksɪs/","tag":"the centre line","definition":"The line of active volcanism and crust formation at the crest; it is a part of the ridge, not a synonym.","definitionCN":"脊顶火山活动与洋壳生成的中心线；它是洋脊的一部分，并非同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ridge","ipa":"/rɪdʒ/","tag":"any long crest","definition":"Any long narrow raised feature; the sea-floor term is one kind of ridge among many.","definitionCN":"任何狭长隆起；海底的这个术语只是众多 ridge 中的一种。"},{"word":"rise","ipa":"/raɪz/","tag":"broad uplift","definition":"A broad, gentle elevation of the sea floor; it is wider and less steep than a ridge.","definitionCN":"海底宽广而平缓的隆起；比洋脊更宽、更不陡。"},{"word":"seamount","ipa":"/ˈsiːmaʊnt/","tag":"single volcano","definition":"An isolated underwater mountain, usually volcanic; a ridge is a long connected chain.","definitionCN":"孤立的海底山，通常为火山成因；洋脊是长条相连的山链。"},{"word":"plateau","ipa":"/plæˈtəʊ/","tag":"flat uplift","definition":"A broad flat elevated area; a ridge is linear and often faulted, not a tableland.","definitionCN":"宽广平坦的隆起区；洋脊成线状且常有断裂，不是台地。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mid 'middle' + ocean + ridge 'spine': a spine down the ocean's middle.","cn":"mid「中间」+ ocean「海洋」+ ridge「脊」：沿海洋中部的一条脊。"},{"en":"The related terms run mid-ocean ridge, ocean ridge, ridge axis, rift valley, oceanic ridge.","cn":"相关术语包括 mid-ocean ridge、ocean ridge、ridge axis、rift valley、oceanic ridge。"},{"en":"Fixed phrases mark the science: mid-ocean ridge basalt, ridge crest, ridge volcanism.","cn":"固定搭配标出科学用法：洋中脊玄武岩、脊顶、洋脊火山活动。"},{"en":"The phrase is the standard opposite-setting to ocean trench in plate tectonics.","cn":"在板块构造中，这个短语与 ocean trench 构成标准的环境对照。"},{"en":"Magnetic stripes are symmetrical about the ridge axis, a fact textbooks repeat.","cn":"磁条带以脊轴为对称，这是教科书反复提到的事实。"}],"abstract":[{"en":"Picture a long scar that pushes two halves of a body apart very slowly.","cn":"想象一道长伤疤把身体的两半极缓慢地推开。"},{"en":"Picture a factory that makes new ground and ships it away in both directions.","cn":"想象一座工厂不断制造新地面，并向两边运走。"},{"en":"Picture a seam that runs around the world under every ocean.","cn":"想象一条接缝在各大洋之下环绕世界。"}]},"examples":[{"en":"The mid-ocean ridge runs the length of the Atlantic.","cn":"洋中脊贯穿大西洋的长度。"},{"en":"Basalt from the mid-ocean ridge is poor in silica.","cn":"洋中脊的玄武岩含硅量低。"},{"en":"Vents along the mid-ocean ridge host unique ecosystems.","cn":"洋中脊沿线的喷口养育着独特的生态系统。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「mid（中间）+ ocean（海洋）+ ridge（脊）」——海洋中间的脊就是洋中脊","word":"mid-ocean ridge"},"root":"mid 来自古英语 midd「中间」，ocean 经拉丁 oceanus 来自希腊 ōkeanos，ridge 来自古英语 hrycg「背、脊」；日耳曼词根均为重构，ōkeanos 来源有争议，术语属现代。","sensesIntro":{"en":"Eight senses follow one long uplift: the mountain chain, the divergent boundary, the birth of crust, the axial rift, its vents, its magma supply, its magnetic symmetry and the global network it belongs to.","cn":"八个义项沿同一条长隆起展开：海底山脉、离散边界、洋壳的诞生、轴部裂谷、其喷口、其岩浆供给、其磁对称，以及它所属的全球网络。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long raised seam with a groove down its middle.","cn":"核心意象：一条长长的隆起接缝，中间裂着一道槽。"},"chain":["LONG SWELL","DIVERGENT EDGE","NEW CRUST","AXIAL RIFT","HYDROTHERMAL FIELD","GLOBAL NETWORK"],"branches":[{"senses":"S1","en":"MOUNTAIN CHAIN: the visible long uplift in the middle of the sea.","cn":"海底山脉：海洋中部可见的长条隆起。"},{"senses":"S2 · S3","en":"OPENING AND BIRTH: plates separate and new crust is made.","cn":"开裂与新生：板块分离，新洋壳生成。"},{"senses":"S4","en":"CENTRAL GROOVE: tension splits the crest into a rift.","cn":"中央深槽：张力把脊顶劈成裂谷。"},{"senses":"S5 · S6","en":"HEAT AND PLUMBING: vents at the surface, magma chambers below.","cn":"热量与管道：表面是喷口，深处是岩浆房。"},{"senses":"S7 · S8","en":"SYMMETRY AND SYSTEM: stripes mirror across the axis, and the ridges connect worldwide.","cn":"对称与体系：条带以轴镜像，洋脊在全球相连。"}]},"affixes":{"intro":{"en":"Mid-ocean ridge is a three-part English compound, readable piece by piece without Latin knowledge.","cn":"mid-ocean ridge 是三段式英语复合词，无需拉丁语知识即可逐段读出。"},"latinIntro":{"en":"Only ocean has a classical source, Greek ōkeanos through Latin oceanus; mid and ridge are Germanic.","cn":"只有 ocean 有古典来源，即经拉丁 oceanus 的希腊 ōkeanos；mid 与 ridge 属日耳曼语。"},"items":[{"word":"mid","structure":"Old English midd (adjective, 'middle')","meaning":"middle; in the centre","meaningCN":"中间的；在中央","example":"The ridge lies mid-ocean.","exampleCN":"洋脊位于海洋中部。"},{"word":"ocean","structure":"ocean (from Greek ōkeanos via Latin oceanus)","meaning":"the open sea","meaningCN":"开阔海洋","example":"The ocean basin is deep.","exampleCN":"洋盆很深。"},{"word":"ridge","structure":"Old English hrycg (noun, 'back, spine')","meaning":"a long raised crest","meaningCN":"狭长的隆起脊","example":"A ridge of rock crossed the valley.","exampleCN":"一道岩脊横过山谷。"},{"word":"mid-ocean ridge","structure":"mid + ocean + ridge (compound noun)","meaning":"a central submarine mountain chain","meaningCN":"海底中央山脉；洋中脊","example":"The mid-ocean ridge splits the Atlantic.","exampleCN":"洋中脊把大西洋分开。"},{"word":"ocean ridge","structure":"ocean + ridge (short compound)","meaning":"a ridge in the sea","meaningCN":"海中的洋脊","example":"Ocean ridges ring the globe.","exampleCN":"洋脊环绕地球。"},{"word":"ridge axis","structure":"ridge + axis (compound term)","meaning":"the centre line of a ridge","meaningCN":"洋脊轴部","example":"Lava rises at the ridge axis.","exampleCN":"熔岩在脊轴上升。"},{"word":"rift valley","structure":"rift + valley (compound term)","meaning":"a central depression on a ridge","meaningCN":"脊顶的中央裂谷","example":"The rift valley lies along the crest.","exampleCN":"裂谷沿脊顶分布。"},{"word":"ridge crest","structure":"ridge + crest (compound term)","meaning":"the highest line of a ridge","meaningCN":"洋脊脊顶","example":"The ridge crest stands two kilometres above the plain.","exampleCN":"脊顶高出平原两千米。"}],"latinEntries":[{"word":"oceanus","structure":"oceanus, oceanus (m., fourth declension)","meaning":"the outer sea","meaningCN":"外海"},{"word":"Oceanus","structure":"Oceanus (proper noun, from Greek ōkeanos)","meaning":"the river encircling the world","meaningCN":"环绕世界的巨流"}]}},{"word":"continental shelf","ipa_uk":"/kənˌtɪnəntəl ˈʃelf/","ipa_us":"/kənˌtɪnəntəl ˈʃelf/","definition_zh":"大陆架；大陆棚（大陆边缘向海缓倾的浅海平台）","definition_en":"the shallow, gently sloping submarine platform that extends from a continent to the point where the sea floor drops away more steeply","core_image":"大陆像一块高台，边缘缓缓伸进浅水，铺成一片平坦的浅海底","scene":"渔船在离岸不远的浅水区拖网，水深刚过几十米。 Most of the catch came from the continental shelf.","sceneCN":"这里 continental shelf 指「大陆边缘的浅海平台」（第 1 个义项：大陆向海缓倾的浅水海底）；句意为大部分渔获来自大陆架。图中可辨识物件：渔船、拖网、浅水、远处的海岸线。","pos":[{"tag":"n.","zh":"大陆架；大陆棚（通常作单数，带定冠词）"}],"collocations":[{"phrase":"continental shelf waters","zh":"大陆架水域"},{"phrase":"outer continental shelf","zh":"外大陆架"},{"phrase":"continental shelf break","zh":"陆架坡折"},{"phrase":"continental shelf sediment","zh":"大陆架沉积物"},{"phrase":"continental shelf fishery","zh":"大陆架渔场"},{"phrase":"the edge of the continental shelf","zh":"大陆架边缘"}],"forms":[{"label":"复数","form":"continental shelves"},{"label":"形容词形式","form":"continental-shelf"},{"label":"相关地貌","form":"continental slope"},{"label":"相关地貌","form":"continental rise"},{"label":"相关术语","form":"shelf break"},{"label":"相关术语","form":"continental margin"}],"derivatives":[{"word":"continental-shelf","pos":"adj.","zh":"大陆架的"},{"word":"continental slope","pos":"n.","zh":"大陆坡"},{"word":"continental rise","pos":"n.","zh":"大陆隆"},{"word":"shelf break","pos":"n.","zh":"陆架坡折"},{"word":"continental margin","pos":"n.","zh":"大陆边缘"}],"senses":[{"no":"01","title":"The shallow submarine platform","titleCN":"大陆边缘的浅海平台","definition":"the submerged, gently sloping plain that borders a continent","definitionCN":"环绕大陆、没入水中且坡度平缓的平面","example":"Most of the catch came from the continental shelf.","exampleCN":"大部分渔获来自大陆架。","why":"a shelf is a flat ledge attached to something larger, so the phrase pictures a continent with a ledge under shallow water.","whyCN":"shelf 是附着在更大物体上的平坦台面，因此这个短语把大陆想象成带有一块浅水下的台地。"},{"no":"02","title":"A gently sloping surface","titleCN":"坡度平缓的陆架表面","definition":"the surface of the shelf, which slopes only a few metres per kilometre","definitionCN":"陆架的表面，每一公里只下降几米","example":"The shelf slopes so gently that the tide moves far offshore.","exampleCN":"陆架坡度极缓，潮水退得很远。","why":"the defining feature is not only depth but slope, so the phrase also names that gentle gradient.","whyCN":"定义性特征不只是深度，还有坡度，因此这个短语也指那种平缓的倾斜。"},{"no":"03","title":"A shallow-water fishery","titleCN":"大陆架渔场","definition":"the shelf as a productive fishing ground fed by nutrients and sunlight","definitionCN":"作为受养分与阳光滋养的高产渔场的大陆架","example":"Herring spawn along the continental shelf every spring.","exampleCN":"鲱鱼每年春天在大陆架沿线产卵。","why":"shallow sunlit water supports abundant life, so industry and ecology read the shelf as a fishery.","whyCN":"浅而有阳光的水养育大量生命，因此产业与生态学把陆架读作渔场。"},{"no":"04","title":"A province of oil and gas","titleCN":"大陆架的油气区","definition":"the shelf as a geological province holding offshore petroleum","definitionCN":"作为蕴藏近海石油的地质区域的大陆架","example":"The continental shelf holds large reserves of gas.","exampleCN":"大陆架蕴藏着大量天然气。","why":"shelf sediments bury organic matter that becomes oil and gas, so the shelf is also an energy province.","whyCN":"陆架沉积物埋藏有机物并转化为油气，因此陆架也是能源区域。"},{"no":"05","title":"A legal maritime zone","titleCN":"法律上的大陆架管辖区","definition":"the shelf as defined in the law of the sea as part of a coastal state's rights","definitionCN":"海洋法上作为沿海国权利范围的大陆架","example":"The treaty set the limit of the continental shelf at two hundred nautical miles.","exampleCN":"条约把大陆架的界限定为二百海里。","why":"because the shelf is physically attached to the land, law treats it as an extension of coastal rights.","whyCN":"由于陆架在物理上附着于陆地，法律把它当作沿海国权利的延伸。"},{"no":"06","title":"The shelf edge or break","titleCN":"大陆架外缘、陆架坡折","definition":"the outer margin where the gentle shelf ends and the slope begins","definitionCN":"平缓陆架结束、陆坡开始的外缘边界","example":"Warm water spills over the continental shelf break.","exampleCN":"暖水越过陆架坡折向外流。","why":"the break is the shelf's boundary, so the phrase can name the edge as well as the whole platform.","whyCN":"坡折是陆架的边界，因此这个短语既可指整个平台，也可指这条边缘。"},{"no":"07","title":"A body of shelf sediment","titleCN":"大陆架沉积层","definition":"the sand, mud and gravel laid down on the shelf by rivers and waves","definitionCN":"河流与波浪在陆架上堆积的沙、泥与砾石","example":"River sand covers much of the continental shelf here.","exampleCN":"河流带来的沙覆盖了这里的大部分大陆架。","why":"the shelf is a trap for land-derived sediment, so the phrase can name that sedimentary body.","whyCN":"陆架截留来自陆地的沉积物，因此这个短语可指那套沉积体。"},{"no":"08","title":"A shelf exposed in the past","titleCN":"古大陆架（低海平面时露出）","definition":"the shelf as dry land during periods of lower sea level","definitionCN":"海平面较低时期露出成陆的大陆架","example":"Ancient rivers cut channels across the exposed continental shelf.","exampleCN":"古河流在出露的大陆架上切出水道。","why":"when the sea falls, the shelf becomes land, so the phrase can name a past landscape.","whyCN":"海水下降时陆架变成陆地，因此这个短语可指过去的地貌。"}],"etymology":{"intro":{"en":"Continental shelf combines continental, from Latin continens 'continuous land' and continere 'to hold together', with shelf, from Old English scylfe 'ledge, partition'. The geological term is modern. Dates are approximate.","cn":"continental shelf 由 continental 与 shelf 组合：continental 来自拉丁 continens「连续的土地」与 continere「连在一起」，shelf 来自古英语 scylfe「台板、隔板」。这个地质术语属现代。年代均为约数。"},"items":[{"era":"LATIN CONTINERE","en":"Continere meant 'to hold together, contain'. Its participle continens described land that holds together as one mass.","cn":"continere 意为「连在一起、容纳」。其分词 continens 描述连成一整块的土地。"},{"era":"CONTINENT","en":"English continent came through French from continens, naming one of the great continuous land masses.","cn":"英语 continent 经法语来自 continens，指一块巨大的连续陆地。"},{"era":"OLD ENGLISH SCYLFE","en":"Scylfe meant a ledge or partition, a flat projecting surface attached to something larger.","cn":"scylfe 指台板或隔板，即附着在更大物体上的平坦伸出面。"},{"era":"GEOLOGICAL TERM","en":"Late nineteenth-century geologists coined continental shelf for the shallow platform bordering each continent.","cn":"十九世纪末的地质学家为环绕各大陆的浅水平台造出 continental shelf 这一术语。"},{"era":"LAW OF THE SEA","en":"Twentieth-century maritime law gave the physical shelf a legal meaning as part of a coastal state's rights.","cn":"二十世纪的海洋法赋予这一实际存在的陆架法律含义，使其成为沿海国权利的一部分。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Germanic origin of scylfe is not settled, and the exact first date of the geological term is only approximate.","cn":"来源不确定：scylfe 在日耳曼语之前的来源未有定论，这一地质术语的确切首见年代也只是约数。"}]},"similar":{"note":{"en":"Group one separates the shelf from the other parts of the continental margin and from continental crust; group two holds flat shallow features of different scale.","cn":"第一组把陆架与大陆边缘的其他部分、以及大陆地壳分开；第二组是规模不同的平坦浅水地貌。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"continental slope","ipa":"/kənˌtɪnəntəl ˈsləʊp/","tag":"the steep next part","definition":"The steeper descent beyond the shelf break; it begins where the shelf ends and leads down to the rise.","definitionCN":"陆架坡折之外较陡的下降段；它从陆架结束处开始，向下通往大陆隆。"},{"word":"continental rise","ipa":"/kənˌtɪnəntəl ˈraɪz/","tag":"the gentle apron","definition":"The gentle slope of sediment at the foot of the continental slope; it lies deeper and farther out than the shelf.","definitionCN":"陆坡脚下的沉积缓坡；比陆架更深、更靠外。"},{"word":"continental crust","ipa":"/kənˌtɪnəntəl krʌst/","tag":"the rock, not the platform","definition":"The thick granitic rock forming the continents; the shelf is a submerged surface of that margin, not the crust itself.","definitionCN":"构成大陆的厚花岗质岩石；陆架是该边缘的淹没表面，而非地壳本身。"},{"word":"continental margin","ipa":"/kənˌtɪnəntəl ˈmɑːdʒɪn/","tag":"the whole edge","definition":"The whole zone of shelf, slope and rise together; the shelf is only its shallow inland part.","definitionCN":"陆架、陆坡与大陆隆合起来的一整条边缘；陆架只是其中较浅的内侧部分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"shelf","ipa":"/ʃelf/","tag":"the base noun","definition":"Any flat ledge; without continental it usually means a board for storing things.","definitionCN":"任何平坦台板；没有 continental 时通常指置物板。"},{"word":"platform","ipa":"/ˈplætfɔːm/","tag":"raised flat area","definition":"A flat raised surface; it is more general and need not be underwater.","definitionCN":"平坦的隆起面；更泛，不必在水下。"},{"word":"bank","ipa":"/bæŋk/","tag":"shallow fishing ground","definition":"A shallow elevation in the sea, often rich in fish; it is smaller and more local than a continental shelf.","definitionCN":"海中的浅隆起，常鱼产丰富；比大陆架更小、更局部。"},{"word":"shoal","ipa":"/ʃəʊl/","tag":"very shallow water","definition":"A stretch of shallow water, often a hazard to ships; it lacks the continental and tectonic meaning of the shelf.","definitionCN":"一片浅水，常对船只有危险；缺少陆架那种大陆与构造含义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"continental 'of a continent' + shelf 'ledge': a ledge attached to a continent.","cn":"continental「大陆的」+ shelf「台板」：附着在大陆上的一块台板。"},{"en":"The margin family runs continental shelf, continental slope, continental rise, continental margin.","cn":"大陆边缘词族包括 continental shelf、continental slope、continental rise、continental margin。"},{"en":"Fixed phrases mark law and industry: outer continental shelf, shelf break, shelf fishery.","cn":"固定搭配标出法律与产业用法：外大陆架、陆架坡折、陆架渔场。"},{"en":"The plural is shelves, not shelfs.","cn":"复数形式是 shelves，不是 shelfs。"},{"en":"Textbooks place the shelf between the shore and the shelf break.","cn":"教科书把陆架放在海岸与陆架坡折之间。"}],"abstract":[{"en":"Picture a continent wearing a wide flat apron that disappears under the sea.","cn":"想象一块大陆围着一圈宽大的平围裙，围裙没入海中。"},{"en":"Picture a table whose edge drops away into a dark room.","cn":"想象一张桌子，边缘之外直接落进黑暗的房间。"},{"en":"Picture a drowned field still showing the lines of old rivers.","cn":"想象一片被淹没的田野，仍看得见古河道的线。"}]},"examples":[{"en":"The continental shelf here is less than a hundred metres deep.","cn":"这里的大陆架水深不足一百米。"},{"en":"Oil platforms stand on the continental shelf.","cn":"石油平台立在大陆架上。"},{"en":"The continental shelf nourishes most of the coastal fishery.","cn":"大陆架滋养着大部分近海渔业。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「continental（大陆的）+ shelf（台板）」——大陆伸进水里的那块平台 → 大陆架","word":"continental shelf"},"root":"continental 来自拉丁 continens「连续的土地」，出自 continere「连在一起」；shelf 来自古英语 scylfe「台板、隔板」；scylfe 更深来源不确定，地质术语首见年代只是约数。","sensesIntro":{"en":"Eight senses follow one ledge: the shallow platform, its gentle slope, its fish, its oil and gas, its legal zone, its break, its sediment, and its dry past when the sea was low.","cn":"八个义项沿同一块台板展开：浅水平台、其缓坡、其鱼类、其油气、其法律管辖、其坡折、其沉积物，以及海平面较低时出露成陆的过去。"},"semanticMap":{"core":{"en":"CORE IMAGE: a continent wearing a wide flat apron that sinks under shallow water.","cn":"核心意象：大陆围着一圈宽大的平围裙，缓缓没入浅水。"},"chain":["SHALLOW LEDGE","GENTLE SLOPE","FISHERY","OIL PROVINCE","LEGAL ZONE","SHELF EDGE"],"branches":[{"senses":"S1 · S2","en":"THE LEDGE ITSELF: shallow platform and its almost flat surface.","cn":"台板本身：浅水平台及其近乎平坦的表面。"},{"senses":"S3","en":"LIFE AND FISH: sunlit shallows feed a fishery.","cn":"生命与鱼：有阳光的浅水养育渔场。"},{"senses":"S4","en":"BURIED ENERGY: shelf sediment holds oil and gas.","cn":"埋藏的能源：陆架沉积物蕴藏油气。"},{"senses":"S5 · S6","en":"DRAWN LIMITS: law defines the zone, and the break defines its outer edge.","cn":"画出的界限：法律界定管辖区，坡折界定其外缘。"},{"senses":"S7 · S8","en":"SEDIMENT AND PAST LAND: what fills the shelf and what it looked like when dry.","cn":"沉积与旧陆：填充陆架的物质，以及它出露时的样子。"}]},"affixes":{"intro":{"en":"Continental shelf joins a Latin-derived adjective with a Germanic noun, so its two halves belong to different layers of English.","cn":"continental shelf 把拉丁来源的形容词与日耳曼语名词结合，两半属于英语的不同层次。"},"latinIntro":{"en":"Latin continens and continere give continent and continental; the Latin entries below show the form behind the adjective.","cn":"拉丁 continens 与 continere 衍生 continent 与 continental；下面的拉丁条目给出形容词背后的形式。"},"items":[{"word":"continens","structure":"continens, continentis (Latin present participle, 'holding together')","meaning":"continuous; holding together","meaningCN":"连续的；连在一起的","example":"Terra continens means land that holds together as one mass.","exampleCN":"terra continens 指连成一整块的陆地。"},{"word":"continent","structure":"continent (from Latin continens via French)","meaning":"a great continuous land mass","meaningCN":"巨大的连续陆块","example":"The continent stretches for thousands of kilometres.","exampleCN":"这块大陆延伸数千公里。"},{"word":"-al","structure":"-al (English adjective suffix from Latin -alis)","meaning":"pertaining to","meaningCN":"与……有关的","example":"The suffix builds the adjective from the noun.","exampleCN":"这个后缀由名词构成形容词。"},{"word":"continental","structure":"continent + -al","meaning":"of a continent","meaningCN":"大陆的","example":"Continental air is dry in winter.","exampleCN":"冬季大陆气团干燥。"},{"word":"shelf","structure":"Old English scylfe (noun, 'ledge, partition')","meaning":"a flat ledge","meaningCN":"平坦的台板","example":"The shelf projected over the water.","exampleCN":"台板伸出水面之上。"},{"word":"continental shelf","structure":"continental + shelf (compound term)","meaning":"the shallow platform around a continent","meaningCN":"环绕大陆的浅水平台；大陆架","example":"Fish feed along the continental shelf.","exampleCN":"鱼群在大陆架沿线觅食。"},{"word":"continental slope","structure":"continental + slope (compound term)","meaning":"the descent beyond the shelf break","meaningCN":"陆架坡折之外的下降段；大陆坡","example":"The continental slope falls away steeply.","exampleCN":"大陆坡陡峭下落。"},{"word":"shelf break","structure":"shelf + break (compound term)","meaning":"the outer edge of the shelf","meaningCN":"陆架坡折；陆架外缘","example":"The current turns at the shelf break.","exampleCN":"水流在陆架坡折处转向。"}],"latinEntries":[{"word":"continens","structure":"continens, continentis (present participle of continere)","meaning":"holding together; continuous","meaningCN":"连在一起的；连续的"},{"word":"continere","structure":"continere, continui, contentum (verb, second conjugation)","meaning":"to hold together, contain","meaningCN":"连在一起；容纳"},{"word":"continentia","structure":"continentia, continentiae (f., first declension)","meaning":"continuity, connection","meaningCN":"连续；连接"}]}},{"word":"continental slope","ipa_uk":"/kənˌtɪnəntəl ˈsləʊp/","ipa_us":"/kənˌtɪnəntəl ˈsloʊp/","definition_zh":"大陆坡；陆坡（大陆架外缘与大陆隆之间的陡坡）","definition_en":"the steep descent that links the outer edge of the continental shelf to the deeper ocean floor","core_image":"浅水平台走到尽头，地面忽然折下，像被刀削出一道长长的斜面","scene":"声呐剖面显示，平坦的浅海底部突然向下折成陡坡。 The seafloor drops steeply along the continental slope.","sceneCN":"这里 continental slope 指「陆架外缘与深海之间较陡的过渡坡面」（第 1 个义项：大陆边缘的陡坡段）；句意为海底沿大陆坡陡峭下落。图中可辨识物件：声呐剖面、平缓陆架、折点、向下延伸的斜面。","pos":[{"tag":"n.","zh":"大陆坡；陆坡（通常作单数，带定冠词）"}],"collocations":[{"phrase":"the continental slope","zh":"大陆坡（带定冠词的常用形式）"},{"phrase":"continental slope sediment","zh":"大陆坡沉积物"},{"phrase":"continental slope canyon","zh":"大陆坡海底峡谷"},{"phrase":"continental slope failure","zh":"大陆坡滑塌"},{"phrase":"along the continental slope","zh":"沿大陆坡"},{"phrase":"lower continental slope","zh":"下大陆坡"}],"forms":[{"label":"复数","form":"continental slopes"},{"label":"形容词形式","form":"continental-slope"},{"label":"相关地貌","form":"continental shelf"},{"label":"相关地貌","form":"continental rise"},{"label":"相关术语","form":"shelf break"},{"label":"相关术语","form":"submarine canyon"}],"derivatives":[{"word":"continental-slope","pos":"adj.","zh":"大陆坡的"},{"word":"continental shelf","pos":"n.","zh":"大陆架"},{"word":"continental rise","pos":"n.","zh":"大陆隆"},{"word":"slope failure","pos":"n.","zh":"坡体滑塌"},{"word":"submarine canyon","pos":"n.","zh":"海底峡谷"}],"senses":[{"no":"01","title":"The steep descent from the shelf","titleCN":"陆架外缘的陡坡段","definition":"the relatively steep part of the continental margin between the shelf break and the rise","definitionCN":"大陆边缘上介于陆架坡折与大陆隆之间的较陡部分","example":"The seafloor drops steeply along the continental slope.","exampleCN":"海底沿大陆坡陡峭下落。","why":"slope is the general word for inclined ground, and continental marks the edge of a continent, so the phrase names the inclined face of that edge.","whyCN":"slope 是表示倾斜地面的通用词，continental 标出大陆边缘，因此这个短语指那条边缘的斜面。"},{"no":"02","title":"Its gradient and profile","titleCN":"大陆坡的坡度与剖面","definition":"the angle and shape of the descent, typically steeper than the shelf and gentler than a cliff","definitionCN":"下降段的角度与形状，通常比陆架陡、比悬崖缓","example":"The continental slope here averages four degrees.","exampleCN":"这里的大陆坡平均坡度为四度。","why":"a slope is measured as an angle, so the phrase also names the gradient rather than only the place.","whyCN":"坡以角度计量，因此这个短语也指坡度，而不只是地点。"},{"no":"03","title":"A zone of sediment failure","titleCN":"沉积物滑塌带","definition":"the part of the margin where sediment slides and flows down as turbidity currents","definitionCN":"沉积物下滑并以浊流形式流动的边缘地带","example":"An earthquake triggered a slide on the continental slope.","exampleCN":"一次地震引发了大陆坡上的滑塌。","why":"steep sediment piles are unstable, so the slope is also a zone of landslides and turbidity currents.","whyCN":"陡坡上的沉积堆不稳定，因此大陆坡也是滑坡与浊流发生的区域。"},{"no":"04","title":"A setting for submarine canyons","titleCN":"海底峡谷所在的坡面","definition":"the slope as the place where canyons are cut by sediment flows","definitionCN":"作为沉积流切割出峡谷之处的坡面","example":"A canyon cuts deep into the continental slope.","exampleCN":"一条峡谷深深切入大陆坡。","why":"flows running down the incline carve channels, so the slope is the natural home of submarine canyons.","whyCN":"沿斜面下行的水流切出水道，因此大陆坡是海底峡谷的天然所在。"},{"no":"05","title":"A deep-water habitat","titleCN":"深水生物栖息地","definition":"the slope as a habitat for organisms living on its sediment and rock","definitionCN":"作为生物栖息于其沉积物与岩石上的场所","example":"Corals colonise rocky outcrops on the continental slope.","exampleCN":"珊瑚在陆坡的岩质露头上定居。","why":"the slope spans a wide depth range, so it offers a varied habitat from shelf edge to deep water.","whyCN":"大陆坡跨越很大的深度范围，因此从陆架边缘到深水提供了多样的栖息地。"},{"no":"06","title":"A crustal transition","titleCN":"地壳过渡带","definition":"the zone where continental crust thins and gives way to oceanic crust","definitionCN":"大陆地壳变薄并让位于洋壳的地带","example":"The continental slope marks the transition from continental to oceanic crust.","exampleCN":"大陆坡标示出大陆地壳到洋壳的过渡。","why":"the steep drop coincides with a change in crustal thickness, so the phrase also names a structural boundary.","whyCN":"陡降与地壳厚度的变化同时发生，因此这个短语也指一条构造边界。"},{"no":"07","title":"A target for survey and industry","titleCN":"测绘与产业的目标","definition":"the slope as an object of bathymetric mapping, cable routing and resource exploration","definitionCN":"作为水深测绘、电缆布线与资源勘探对象的坡面","example":"Engineers surveyed the continental slope before routing the cable.","exampleCN":"工程师在布线之前勘测了大陆坡。","why":"steep ground is hard to work on, so industry treats the slope as a special surveying problem.","whyCN":"陡坡难以施工，因此产业把大陆坡当作特殊的测绘难题。"},{"no":"08","title":"The transition to the deep plain","titleCN":"通向深海平原的过渡带","definition":"the slope as the passage from shelf water to the abyssal plain","definitionCN":"作为从陆架浅水通往深海平原的通道","example":"Cold water sinks as it moves down the continental slope.","exampleCN":"冷水沿大陆坡下行时下沉。","why":"the incline connects two worlds, shallow shelf and deep plain, which is why it is read as a transition.","whyCN":"这道斜面连接浅水陆架与深海平原两个世界，因此被看作一条过渡带。"}],"etymology":{"intro":{"en":"Continental slope combines continental, from Latin continens 'continuous land', with slope, an English word of uncertain origin first recorded in the late Middle Ages. Dates are approximate.","cn":"continental slope 由 continental 与 slope 组合：continental 来自拉丁 continens「连续的土地」，slope 是来源不确定的英语词，最早书证见于中世纪末期。年代均为约数。"},"items":[{"era":"LATIN CONTINENS","en":"Continens, the participle of continere 'to hold together', named a continuous land mass and gives English continent and continental.","cn":"continens 是 continere「连在一起」的分词，指连续的陆块，并衍生英语 continent 与 continental。"},{"era":"MIDDLE ENGLISH SLOPE","en":"Slope first appears in Middle English as a word for a slant or inclined surface. Its source is not established; a link to Scandinavian or Low German forms is suggested but unproven.","cn":"slope 最早在中古英语中出现，指斜面或倾斜的表面。其来源未得确认；有人提出与斯堪的纳维亚或低地德语形式有关，但未获证实。"},{"era":"GENERAL ENGLISH USE","en":"By the early modern period slope was the ordinary word for any inclined line, hillside or gradient.","cn":"到近代早期，slope 已是表示任何斜线、山坡或坡度的普通词。"},{"era":"GEOLOGICAL TERM","en":"Nineteenth-century oceanography named the steep edge of the continent the continental slope, pairing it with the shelf above and the rise below.","cn":"十九世纪的海洋学把大陆的陡峭边缘命名为 continental slope，并与上方的陆架、下方的大陆隆配对。"},{"era":"DEEP-SEA RESEARCH","en":"Twentieth-century submersible and sonar work added the senses of canyon, landslide and habitat to the term.","cn":"二十世纪的深潜与声呐工作给这个术语增加了峡谷、滑坡与栖息地等义项。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of slope before English is unsettled, and the exact first date of the geological phrase is only approximate.","cn":"来源不确定：slope 在英语之前的来源未有定论，这一地质短语的确切首见年代也只是约数。"}]},"similar":{"note":{"en":"Group one separates the slope from the shelf above it, the rise below it and the whole margin; group two holds words for inclined ground of different steepness.","cn":"第一组把大陆坡与上方的陆架、下方的大陆隆以及整条边缘分开；第二组是陡度不同的倾斜地面词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"continental shelf","ipa":"/kənˌtɪnəntəl ˈʃelf/","tag":"the flat part above","definition":"The shallow gentle platform before the break; the slope starts where the shelf ends.","definitionCN":"坡折之前的浅水平缓平台；大陆坡从陆架结束处开始。"},{"word":"continental rise","ipa":"/kənˌtɪnəntəl ˈraɪz/","tag":"the apron below","definition":"The gentle sediment apron at the foot of the slope; it is far less steep than the slope.","definitionCN":"坡脚的沉积缓裙；远比大陆坡平缓。"},{"word":"continental margin","ipa":"/kənˌtɪnəntəl ˈmɑːdʒɪn/","tag":"the whole edge","definition":"Shelf, slope and rise taken together; the slope is only its middle, steepest section.","definitionCN":"陆架、陆坡与大陆隆合称；大陆坡只是其中间最陡的一段。"},{"word":"shelf break","ipa":"/ˈʃelf breɪk/","tag":"the hinge point","definition":"The outer edge of the shelf where the slope begins; it is a line, not the inclined face.","definitionCN":"陆架外缘、大陆坡开始处的折点；它是一条线，不是斜面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"slope","ipa":"/sləʊp/","tag":"any incline","definition":"Any inclined surface or gradient; the geological term adds the continental setting.","definitionCN":"任何斜面或坡度；这个地质术语另加大陆环境。"},{"word":"escarpment","ipa":"/ɪˈskɑːpmənt/","tag":"steep rock face","definition":"A long steep face of rock left by faulting or erosion; it is steeper and more abrupt than a continental slope.","definitionCN":"由断裂或侵蚀形成的长陡岩面；比大陆坡更陡、更突兀。"},{"word":"gradient","ipa":"/ˈɡreɪdiənt/","tag":"measured steepness","definition":"The measured rate of rise or fall; it is a number, while the continental slope is a place.","definitionCN":"测量得到的升降率；它是数值，而大陆坡是地点。"},{"word":"descent","ipa":"/dɪˈsent/","tag":"the act of going down","definition":"The act or path of going downward; the continental slope is the ground, not the journey.","definitionCN":"向下走的行为或路径；大陆坡是地面，不是旅程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"continental 'of a continent' + slope 'incline': the inclined edge of a continent.","cn":"continental「大陆的」+ slope「斜面」：大陆的倾斜边缘。"},{"en":"The margin sequence runs shelf, slope, rise, plain.","cn":"大陆边缘的顺序是陆架、陆坡、大陆隆、深海平原。"},{"en":"Fixed phrases mark the science: slope sediment, slope failure, slope canyon.","cn":"固定搭配标出科学用法：陆坡沉积物、陆坡滑塌、陆坡峡谷。"},{"en":"The phrase usually takes the definite article: down the continental slope.","cn":"这个短语通常带定冠词：沿大陆坡向下。"},{"en":"It is often paired with submarine canyon because flows cut canyons into the incline.","cn":"它常与 submarine canyon 搭配，因为水流会在斜面上切出峡谷。"}],"abstract":[{"en":"Picture a table edge that turns into a long ramp down to a dark floor.","cn":"想象桌子的边缘变成一条长斜坡，通向下方的暗地板。"},{"en":"Picture sand pouring off the end of a shelf and never stopping.","cn":"想象沙子从台面边缘倾泻而下，从不停止。"},{"en":"Picture a border where the ground itself changes its material.","cn":"想象一条边界，连地面的材料都在那里改变。"}]},"examples":[{"en":"Cold currents flow down the continental slope.","cn":"寒流沿大陆坡向下流动。"},{"en":"The continental slope is cut by many canyons.","cn":"大陆坡被许多峡谷切开。"},{"en":"Sediment on the continental slope is unstable after storms.","cn":"风暴之后大陆坡上的沉积物不稳定。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「continental（大陆的）+ slope（斜坡）」——大陆边缘的斜坡就是大陆坡","word":"continental slope"},"root":"continental 来自拉丁 continens「连续的土地」，出自 continere「连在一起」；slope 来源不确定，中古英语已见，可能与斯堪的纳维亚或低地德语形式有关但未证实。","sensesIntro":{"en":"Eight senses follow one incline: the steep edge, its gradient, its slides, its canyons, its life, its crustal transition, its survey problems and its role as the passage to the deep plain.","cn":"八个义项沿同一道斜面展开：陡峭边缘、其坡度、其滑塌、其峡谷、其生命、其地壳过渡、其测绘难题，以及其作为通往深海平原通道的角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flat ledge ending in a long cut face that runs down into darkness.","cn":"核心意象：一块平缓台面走到尽头，接上一条向下伸入黑暗的长斜面。"},"chain":["BROKEN EDGE","STEEP FACE","SEDIMENT SLIDE","SUBMARINE CANYON","DEEP HABITAT","CRUSTAL TRANSITION"],"branches":[{"senses":"S1 · S2","en":"THE INCLINE: the place and its measured angle.","cn":"斜面本身：这个地点及其可测的角度。"},{"senses":"S3","en":"SLIDING SEDIMENT: unstable piles fail and flow down.","cn":"滑动的沉积：不稳的堆积崩塌并向下流动。"},{"senses":"S4","en":"CARVED CHANNELS: flows cut canyons into the face.","cn":"刻出的水道：水流在斜面上切出峡谷。"},{"senses":"S5","en":"DEEP LIFE: the wide depth range becomes habitat.","cn":"深部生命：宽广的深度范围成为栖息地。"},{"senses":"S6 · S7 · S8","en":"BOUNDARY AND PASSAGE: crust changes, surveys begin, and the slope leads to the plain.","cn":"边界与通道：地壳改变、测绘开始，斜面通向平原。"}]},"affixes":{"intro":{"en":"Continental slope joins a Latin-derived adjective with an English noun of uncertain origin, so its two parts come from different layers.","cn":"continental slope 把拉丁来源的形容词与来源不确定的英语名词结合，两部分来自不同层次。"},"latinIntro":{"en":"Latin continens and continere supply continent and continental; slope is not Latin, so it contributes no Latin entry.","cn":"拉丁 continens 与 continere 提供 continent 与 continental；slope 并非拉丁语，因此不提供拉丁条目。"},"items":[{"word":"continens","structure":"continens, continentis (Latin present participle, 'holding together')","meaning":"continuous; holding together","meaningCN":"连续的；连在一起的","example":"Terra continens means one continuous land mass.","exampleCN":"terra continens 指一整块连续陆地。"},{"word":"-al","structure":"-al (English adjective suffix from Latin -alis)","meaning":"pertaining to","meaningCN":"与……有关的","example":"The suffix turns continent into an adjective.","exampleCN":"这个后缀把 continent 变成形容词。"},{"word":"continental","structure":"continent + -al","meaning":"of a continent","meaningCN":"大陆的","example":"Continental shelves border every continent.","exampleCN":"每个大陆都有大陆架环绕。"},{"word":"slope","structure":"slope (English noun, 'inclined surface'; origin uncertain)","meaning":"an inclined surface or gradient","meaningCN":"斜面或坡度","example":"The slope runs down to the river.","exampleCN":"斜坡一直通到河边。"},{"word":"continental slope","structure":"continental + slope (compound term)","meaning":"the steep edge of a continent under the sea","meaningCN":"海下大陆的陡峭边缘；大陆坡","example":"The continental slope falls to the rise.","exampleCN":"大陆坡向下通往大陆隆。"},{"word":"continental-slope","structure":"continental slope + hyphen (attributive adjective)","meaning":"of the continental slope","meaningCN":"大陆坡的","example":"Continental-slope sediment is unstable.","exampleCN":"大陆坡沉积物不稳定。"},{"word":"shelf break","structure":"shelf + break (compound term)","meaning":"the outer edge of the shelf","meaningCN":"陆架坡折","example":"The slope begins at the shelf break.","exampleCN":"大陆坡从陆架坡折开始。"},{"word":"submarine canyon","structure":"submarine + canyon (compound term)","meaning":"a steep valley cut into the sea floor","meaningCN":"切在海底的陡峭谷地；海底峡谷","example":"A submarine canyon cuts the slope.","exampleCN":"一条海底峡谷切开大陆坡。"}],"latinEntries":[{"word":"continens","structure":"continens, continentis (present participle of continere)","meaning":"holding together; continuous","meaningCN":"连在一起的；连续的"},{"word":"continere","structure":"continere, continui, contentum (verb, second conjugation)","meaning":"to hold together, contain","meaningCN":"连在一起；容纳"},{"word":"continentia","structure":"continentia, continentiae (f., first declension)","meaning":"continuity, connection","meaningCN":"连续；连接"}]}}]);
